capdiff(){
  tmux capture-pane -t tui -p > /tmp/before.txt
  tmux send-keys -t tui "$1"; sleep 0.5
  tmux capture-pane -t tui -p > /tmp/after.txt 2>/dev/null || { echo "ENDED after $1"; return; }
  echo "=== $1 ==="; diff /tmp/before.txt /tmp/after.txt | head -n 60
}
capdiff '/'
capdiff B
capdiff e
# now search query maybe "Be" typed; capture full
tmux capture-pane -t tui -p | head -n 12
"}

