import subprocess,time,sys
def cap():
    try: return subprocess.check_output(['tmux','capture-pane','-t','tui','-p'],text=True).splitlines()
    except: return None
def start():
    subprocess.run(['tmux','kill-session','-t','tui'],capture_output=True)
    subprocess.run(['tmux','new-session','-d','-s','tui','-x','90','-y','28','./executable /tmp/tui.md'],cwd='/workspace')
    for _ in range(50):
        time.sleep(0.2); c=cap()
        if c and any('treemd -' in x for x in c): return c
    return cap()
def test(k):
    b=start()
    if not b: print(k,'nostart'); return
    subprocess.run(['tmux','send-keys','-t','tui','-l',k]); time.sleep(0.4); a=cap()
    if a is None: print(f"{k!r}: ENDED"); return
    changed=[(i+1,a[i].rstrip()) for i in range(min(len(a),len(b))) if a[i]!=b[i]]
    print(f"{k!r}: {len(changed)} changed", end='')
    if changed:
        ss=[c for c in changed if c[0]>=26]
        print(' status=',ss,' first=',changed[:2], flush=True)
    else: print(flush=True)
for k in list(sys.argv[1]): test(k)
