            }
        } else {
            // dropped, without acting as a separator
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

pub fn count_words(s: &str) -> usize {
    s.split_whitespace().count()
}

fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

/// Count leading spaces (a tab counts as moving to the next multiple of 4).
fn leading_columns(s: &str) -> usize {
    let mut col = 0usize;
    for c in s.chars() {
        match c {
            ' ' => col += 1,
            '\t' => col += 4 - (col % 4),
            _ => break,
        }
    }
    col
}

/// Byte index after stripping up to `cols` columns of leading whitespace.
fn strip_columns(s: &str, mut cols: usize) -> usize {
    let mut idx = 0usize;
    let mut col = 0usize;
    for (i, c) in s.char_indices() {
        if cols == 0 {
            break;
        }
        match c {
            ' ' => {
                idx = i + 1;
                col += 1;
                cols -= 1;
            }
            '\t' => {
                let w = 4 - (col % 4);
                if w > cols {
                    // partially consumed tab: treat as fully consumed
                    idx = i + 1;
                    cols = 0;
                } else {
                    idx = i + 1;
                    col += w;
                    cols -= w;
                }
            }
            _ => break,
        }
    }
    idx
}

#[derive(Clone, Debug)]
struct Line {
    text: String,
    /// byte offset in the original (effective) source of `text`
    start: usize,
    /// byte offset just after the physical line (including newline)
    end: usize,
}

fn split_lines(source: &str) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    for part in source.split_inclusive('\n') {
        let end = start + part.len();
        let mut text = part.strip_suffix('\n').unwrap_or(part);
        if text.ends_with('\r') {
            text = &text[..text.len() - 1];
        }
        lines.push(Line {
            text: text.to_string(),
            start,
            end,
        });
        start = end;
    }
    if source.is_empty() {
        // no lines
    } else if source.ends_with('\n') {
        // split_inclusive does not yield a trailing empty line; that's fine
    }
    lines
}

// ---------- reference definitions ----------

pub type RefMap = HashMap<String, (String, Option<String>)>;

pub fn normalize_label(s: &str) -> String {
    s.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

/// Try to parse a link reference definition starting at `text` (single line,
/// possibly with a following line for the title). Returns (label, dest, title, lines_used).
fn parse_ref_def(lines: &[Line], i: usize) -> Option<(String, String, Option<String>, usize)> {
    let line = &lines[i].text;
    let indent = leading_columns(line);
    if indent > 3 {
        return None;
    }
    let rest = &line[strip_columns(line, indent)..];
    if !rest.starts_with('[') {
        return None;
    }
    let close = find_unescaped(rest, ']')?;
    if close == 1 {
        return None;
    }
    let label = &rest[1..close];
    if label.contains('[') {
        return None;
    }
    let after = &rest[close + 1..];
    if !after.starts_with(':') {
        return None;
    }
    let mut rest = after[1..].trim_start_matches([' ', '\t']);
    let mut extra_lines = 0usize;
    if rest.is_empty() {
        // destination may be on the next line
        if i + 1 >= lines.len() {
            return None;
        }
        extra_lines = 1;
        rest = lines[i + 1].text.trim_start();
        if rest.is_empty() {
            return None;
        }
    }
    // destination
    let (dest, used) = if let Some(stripped) = rest.strip_prefix('<') {
        let end = find_unescaped(stripped, '>')?;
        (decode_escapes_entities(&stripped[..end]), end + 2)
    } else {
        let mut depth = 0i32;
        let mut idx = 0usize;
        let bytes: Vec<char> = rest.chars().collect();
        let mut last = 0usize;
        while idx < bytes.len() {
            let c = bytes[idx];
            if c == '\\' {
                idx += 2;
                last = idx;
                continue;
            }
            if c == '(' {
                depth += 1;
            } else if c == ')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if c.is_whitespace() {
                if depth == 0 {
                    break;
                }
            }
            idx += 1;
            last = idx;
        }
        if last == 0 {
            return None;
        }
        let raw: String = bytes[..last].iter().collect();
        (decode_escapes_entities(&raw), rest.char_indices().nth(last).map(|(b, _)| b).unwrap_or(rest.len()))
    };
    let mut tail = rest[used..].trim_start_matches([' ', '\t']);
    let mut title: Option<String> = None;
    let mut used_title_line = false;
    if tail.is_empty() && extra_lines == 0 {
        // title may be on next line
        if i + 1 < lines.len() {
            let cand = lines[i + 1].text.trim_start();
            if let Some(t) = parse_link_title(cand) {
                if cand[t.1..].trim().is_empty() {
                    title = Some(t.0);
                    used_title_line = true;
                    tail = "";
                }
            }
        }
    } else if !tail.is_empty() {
        if let Some(t) = parse_link_title(tail) {
            if tail[t.1..].trim().is_empty() {
                title = Some(t.0);
                tail = "";
            }
        }
    }
    if !tail.trim().is_empty() {
        return None;
    }
    let mut consumed = 1 + extra_lines;
    if used_title_line {
        consumed += 1;
    }
    Some((normalize_label(label), dest, title, consumed))
}

fn find_unescaped(s: &str, target: char) -> Option<usize> {
    let mut escaped = false;
    for (i, c) in s.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if c == '\\' {
            escaped = true;
        } else if c == target {
            return Some(i);
        }
    }
    None
}

/// Parse a link title at start of `s`: " " , ' ' or ( ). Returns (title, bytes used).
pub fn parse_link_title(s: &str) -> Option<(String, usize)> {
    let mut chars = s.char_indices();
    let (_, first) = chars.next()?;
    let close = match first {
        '"' => '"',
        '\'' => '\'',
        '(' => ')',
        _ => return None,
    };
    let mut out = String::new();
    let mut escaped = false;
    for (i, c) in chars {
        if escaped {
            if c.is_ascii_punctuation() {
                out.push(c);
            } else {
                out.push('\\');
                out.push(c);
            }
            escaped = false;
            continue;
        }
        if c == '\\' {
            escaped = true;
            continue;
        }
        if c == close {
            return Some((out, i + c.len_utf8()));
        }
        if first == '(' && c == '(' {
            return None;
        }
        out.push(c);
    }
    None
}

pub fn decode_escapes_entities(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some(&n) if n.is_ascii_punctuation() => {
                    out.push(chars.next().unwrap());
                }
                _ => out.push('\\'),
            }
        } else if c == '&' {
            let rest: String = chars.clone().collect();
            if let Some((decoded, used)) = decode_entity(&rest) {
                out.push_str(&decoded);
                for _ in 0..used {
                    chars.next();
                }
            } else {
                out.push('&');
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Decode an entity body (text after '&'). Returns (decoded, chars consumed incl ';').
pub fn decode_entity(rest: &str) -> Option<(String, usize)> {
    let semi = rest.find(';')?;
    if semi == 0 || semi > 10 {
