// ---------- inline parsing ----------

#[derive(Clone, Debug, PartialEq)]
pub enum InlineEvent {
    Text(String),
    Code(String),
    SoftBreak,
    HardBreak,
    StartStrong,
    EndStrong,
    StartEm,
    EndEm,
    StartStrike,
    EndStrike,
    StartLink {
        dest: String,      // clean commonmark destination
        doc_url: String,   // destination as stored by the document model
        title: Option<String>,
    },
    EndLink,
    StartImage {
        dest: String,
        doc_url: String,
        title: Option<String>,
    },
    EndImage,
    Html(String),
}

fn is_ascii_punct(c: char) -> bool {
    c.is_ascii_punctuation()
}

struct InlineParser<'a> {
    text: &'a str,
    bytes: &'a [u8],
    refs: &'a RefMap,
    events: Vec<InlineEvent>,
    buf: String,
}

impl<'a> InlineParser<'a> {
    fn flush(&mut self) {
        if !self.buf.is_empty() {
            let t = std::mem::take(&mut self.buf);
            self.events.push(InlineEvent::Text(t));
        }
    }
    fn push_text_chunk(&mut self, s: &str) {
        self.flush();
        if !s.is_empty() {
            self.events.push(InlineEvent::Text(s.to_string()));
        }
    }
}

fn char_at(text: &str, i: usize) -> Option<char> {
    text[i..].chars().next()
}

fn prev_char(text: &str, i: usize) -> Option<char> {
    text[..i].chars().next_back()
}

/// Parse inline content into events (a pulldown-flavoured stream).
pub fn parse_inline_events(text: &str, refs: &RefMap) -> Vec<InlineEvent> {
    let mut p = InlineParser {
        text,
        bytes: text.as_bytes(),
        refs,
        events: Vec::new(),
        buf: String::new(),
    };
    parse_inline_range(&mut p, 0, text.len());
    p.flush();
    p.events
}

fn parse_inline_range(p: &mut InlineParser, start: usize, end: usize) {
    let text = p.text;
    let mut i = start;
    while i < end {
        let c = char_at(text, i).unwrap();
        match c {
            '\n' => {
                // hard break if the line ends with two spaces (handled by
                // checking buf / previous chars) — backslash handled below.
                let before = &text[start..i];
                let hard = before.ends_with("  ") && !before.ends_with('\\');
                if hard {
                    // remove trailing spaces from buf
                    while p.buf.ends_with(' ') {
                        p.buf.pop();
                    }
                    p.flush();
                    p.events.push(InlineEvent::HardBreak);
                } else {
                    p.flush();
                    p.events.push(InlineEvent::SoftBreak);
                }
                i += 1;
            }
            '\\' => {
                let next = char_at(text, i + 1);
                match next {
                    Some('\n') => {
                        p.flush();
                        p.events.push(InlineEvent::HardBreak);
                        i += 2;
                    }
                    Some(n) if is_ascii_punct(n) => {
                        // escaped punctuation starts a fresh text chunk
                        p.flush();
                        p.buf.push(n);
                        i += 1 + n.len_utf8();
                    }
                    _ => {
                        p.buf.push('\\');
                        i += 1;
                    }
                }
            }
            '&' => {
                let rest = &text[i + 1..end];
                if let Some((decoded, used)) = decode_entity(rest) {
                    p.flush();
                    p.buf.push_str(&decoded);
                    i += 1 + used;
                } else {
                    p.buf.push('&');
                    i += 1;
                }
            }
            '`' => {
                let run = count_run(text, i, '`');
                if let Some((content, after)) = find_code_span(text, i, run, end) {
                    p.flush();
                    p.events.push(InlineEvent::Code(content));
                    i = after;
                } else {
                    for _ in 0..run {
                        p.buf.push('`');
                    }
                    i += run;
                }
            }
            '<' => {
                if let Some((evt, after)) = try_autolink_or_html(text, i, end) {
                    match evt {
                        AutolinkResult::Link(dest) => {
                            p.flush();
                            p.events.push(InlineEvent::StartLink {
                                dest: dest.clone(),
                                doc_url: dest.clone(),
                                title: None,
                            });
                            p.events.push(InlineEvent::Text(dest.clone()));
                            // email autolinks gain mailto: in dest but keep text
                            p.events.push(InlineEvent::EndLink);
                            // fix dest for emails: handled inside try_*
                            i = after;
                        }
                        AutolinkResult::Email(addr) => {
                            p.flush();
                            p.events.push(InlineEvent::StartLink {
                                dest: format!("mailto:{addr}"),
                                doc_url: format!("mailto:{addr}"),
                                title: None,
                            });
                            p.events.push(InlineEvent::Text(addr));
                            p.events.push(InlineEvent::EndLink);
                            i = after;
                        }
                        AutolinkResult::Html(html) => {
                            p.flush();
                            p.events.push(InlineEvent::Html(html));
                            i = after;
                        }
                    }
                } else {
                    p.buf.push('<');
                    i += 1;
                }
            }
            '!' if char_at(text, i + 1) == Some('[') => {
                if let Some(after) = try_parse_link(p, i, end, true) {
                    i = after;
                } else {
                    p.push_text_chunk("!");
                    i += 1;
                }
            }
            '[' => {
                if let Some(after) = try_parse_link(p, i, end, false) {
                    i = after;
                } else {
                    p.push_text_chunk("[");
                    i += 1;
                }
            }
            ']' => {
                p.push_text_chunk("]");
                i += 1;
            }
            '*' | '_' => {
                let run = count_run(text, i, c);
                if let Some(after) = try_parse_emphasis(p, i, end, c, run) {
                    i = after;
                } else {
                    for _ in 0..run {
                        p.buf.push(c);
                    }
                    i += run;
                }
            }
            '~' => {
                let run = count_run(text, i, '~');
                if run <= 2 {
                    if let Some(after) = try_parse_strike(p, i, end, run) {
                        i = after;
                    } else {
                        for _ in 0..run {
                            p.buf.push('~');
                        }
                        i += run;
                    }
                } else {
                    // try with 2
                    if let Some(after) = try_parse_strike(p, i, end, 2) {
                        i = after;
                    } else {
                        p.buf.push('~');
                        i += 1;
                    }
                }
            }
            _ => {
                p.buf.push(c);
                i += c.len_utf8();
            }
        }
    }
    // flush handled by caller for top-level; for nested ranges the shared
    // parser buffer is intentionally flushed here so chunks stay separate.
    p.flush();
}

fn count_run(text: &str, i: usize, c: char) -> usize {
    let mut n = 0;
    let mut j = i;
    while char_at(text, j) == Some(c) {
        n += 1;
        j += c.len_utf8();
    }
    n
}

fn find_code_span(text: &str, start: usize, run: usize, end: usize) -> Option<(String, usize)> {
    let mut i = start + run;
    while i < end {
        if text.as_bytes()[i] == b'`' {
            let r = count_run(text, i, '`');
            if r == run {
                let raw = &text[start + run..i];
                let mut content: String = raw.chars().map(|c| if c == '\n' || c == '\r' { ' ' } else { c }).collect();
                // collapse \r\n that became two spaces? keep simple: raw already
                // had no \r (lines stripped). Apply commonmark space trimming.
                if content.len() >= 2
                    && content.starts_with(' ')
                    && content.ends_with(' ')
                    && content.trim().len() > 0
                {
                    content = content[1..content.len() - 1].to_string();
                }
                return Some((content, i + r));
            }
            i += r;
        } else {
            i += char_at(text, i).map(|c| c.len_utf8()).unwrap_or(1);
        }
    }
    None
}

enum AutolinkResult {
    Link(String),
    Email(String),
    Html(String),
}

fn try_autolink_or_html(text: &str, i: usize, end: usize) -> Option<(AutolinkResult, usize)> {
    let rest = &text[i..end];
    // comments, processing instructions, declarations, CDATA
    if rest.starts_with("<!--") {
        if let Some(pos) = rest.find("-->") {
            return Some((AutolinkResult::Html(rest[..pos + 3].to_string()), i + pos + 3));
        }
        return Some((AutolinkResult::Html(rest.to_string()), end));
    }
    if rest.starts_with("<?") {
        if let Some(pos) = rest.find("?>") {
            return Some((AutolinkResult::Html(rest[..pos + 2].to_string()), i + pos + 2));
        }
    }
    if rest.starts_with("<![CDATA[") {
        if let Some(pos) = rest.find("]]>") {
            return Some((AutolinkResult::Html(rest[..pos + 3].to_string()), i + pos + 3));
        }
    }
    if rest.starts_with("<!") {
        if let Some(pos) = rest.find('>') {
            return Some((AutolinkResult::Html(rest[..pos + 1].to_string()), i + pos + 1));
        }
    }
    // find closing '>' on the same "tag line" (no '<' inside)
    let gt = rest.find('>')?;
    let inside = &rest[1..gt];
    if inside.contains('<') {
        return None;
    }
    // autolink URI
    if is_uri_autolink(inside) {
        return Some((AutolinkResult::Link(inside.to_string()), i + gt + 1));
    }
    if is_email_autolink(inside) {
        return Some((AutolinkResult::Email(inside.to_string()), i + gt + 1));
    }
    // html tag
    if is_html_tag(inside) {
        return Some((AutolinkResult::Html(rest[..gt + 1].to_string()), i + gt + 1));
    }
    None
}

fn is_uri_autolink(s: &str) -> bool {
    let Some(colon) = s.find(':') else { return false };
    let scheme = &s[..colon];
    if scheme.len() < 2 || scheme.len() > 32 {
        return false;
    }
    let mut chars = scheme.chars();
    if !chars.next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false) {
        return false;
    }
    if !chars.all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '.' || c == '-') {
        return false;
    }
    !s[colon + 1..].chars().any(|c| c.is_whitespace() || c == '<' || c == '>')
}

fn is_email_autolink(s: &str) -> bool {
    let Some(at) = s.find('@') else { return false };
    let (user, domain) = (&s[..at], &s[at + 1..]);
    if user.is_empty() || domain.is_empty() {
        return false;
    }
    user.chars().all(|c| c.is_ascii_alphanumeric() || ".!#$%&'*+/=?^_`{|}~-".contains(c))
        && domain.chars().all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-')
        && domain.contains('.')
        && !domain.starts_with('-') && !domain.ends_with('-')
}

fn is_html_tag(inside: &str) -> bool {
    let s = inside.trim_start();
    let s = s.strip_prefix('/').unwrap_or(s);
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() => {}
        _ => return false,
    }
    // tag name then whitespace, '/' or end
    let name_end = s.find(|c: char| !(c.is_ascii_alphanumeric() || c == '-')).unwrap_or(s.len());
    let after = &s[name_end..];
    after.is_empty() || after.starts_with(|c: char| c.is_whitespace()) || after.starts_with('/')
}

// ----- link parsing -----

struct LinkDest {
    dest: String,
    doc_url: String,
    title: Option<String>,
    after: usize, // byte index just after ')'
}

fn skip_ws(text: &str, mut i: usize, end: usize) -> usize {
    while i < end {
        match char_at(text, i) {
            Some(c) if c == ' ' || c == '\t' || c == '\n' || c == '\r' => i += 1,
            _ => break,
        }
    }
    i
}

/// Parse `(dest "title")` starting at the '(' index, with clean CommonMark semantics.
fn parse_inline_dest(text: &str, open: usize, end: usize) -> Option<LinkDest> {
    let mut i = skip_ws(text, open + 1, end);
    if i >= end {
        return None;
    }
    // For the document-model URL we also run the "doc" capture.
    let doc = parse_inline_dest_doc(text, open, end);
    let (dest, _pointy) = if char_at(text, i) == Some('<') {
        // pointy destination
        let mut j = i + 1;
        let mut out = String::new();
        loop {
            match char_at(text, j) {
                None => return None,
                Some('>') => {
                    j += 1;
                    break;
                }
                Some('\n') => return None,
                Some('\\') => {
                    let n = char_at(text, j + 1)?;
                    if is_ascii_punct(n) {
                        out.push(n);
                        j += 1 + n.len_utf8();
                    } else {
                        out.push('\\');
                        j += 1;
                    }
                }
                Some(c) => {
                    out.push(c);
                    j += c.len_utf8();
                }
            }
        }
        i = j;
        (decode_entities_str(&out), true)
    } else {
        // bare destination
        let start = i;
        let mut depth = 0i32;
        let mut j = i;
        while j < end {
            let c = char_at(text, j).unwrap();
            if c == '\\' {
                match char_at(text, j + 1) {
                    Some(n) if is_ascii_punct(n) => {
                        j += 1 + n.len_utf8();
                        continue;
                    }
                    _ => {
                        j += 1;
                        continue;
                    }
                }
            }
            if c == '(' {
                depth += 1;
                if depth > 32 {
                    return None;
                }
            } else if c == ')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if c.is_whitespace() || (c as u32) < 0x20 {
                if depth == 0 {
                    break;
                }
            }
            j += c.len_utf8();
        }
        if j == start {
            // empty destination is allowed: [a]()
            i = j;
            (String::new(), false)
        } else {
            let raw = &text[start..j];
            i = j;
            (decode_escapes_entities(raw), false)
        }
    };
    // optional title
    let before_ws = i;
    i = skip_ws(text, i, end);
    let mut title = None;
    if i < end && char_at(text, i) != Some(')') {
        if i == before_ws {
            return None;
        }
        let t = parse_link_title(&text[i..end])?;
        title = Some(t.0);
        i += t.1;
        i = skip_ws(text, i, end);
    }
    if char_at(text, i) != Some(')') {
        return None;
    }
    let after = i + 1;
    let doc_url = match &doc {
        Some(d) if d.1 == after => d.0.clone(),
        _ => {
            // If doc capture disagrees about the link end, prefer its
            // end/documentation (covers the parenthesised-title quirk).
            if let Some(d) = &doc {
                return Some(LinkDest {
                    dest: dest.clone(),
                    doc_url: d.0.clone(),
                    title,
                    after: d.1,
                });
            }
            dest.clone()
        }
    };
    Some(LinkDest {
        dest,
        doc_url,
        title,
        after,
    })
}

fn decode_entities_str(s: &str) -> String {
    // decode entities but keep backslash escapes already handled by caller
    let mut out = String::new();
    let mut i = 0;
    while i < s.len() {
        let c = char_at(s, i).unwrap();
        if c == '&' {
            if let Some((d, used)) = decode_entity(&s[i + 1..]) {
                out.push_str(&d);
                i += 1 + used;
                continue;
            }
        }
        out.push(c);
        i += c.len_utf8();
    }
    out
}

/// The document model's link-destination capture. Returns (url, after).
/// It captures up to a closing paren, mostly verbatim, with a few
/// title-stripping behaviours (pointy destinations, destinations with
/// nested parens, newline-separated titles, escaped closing parens).
fn parse_inline_dest_doc(text: &str, open: usize, end: usize) -> Option<(String, usize)> {
    let start = open + 1;
    // find capturing end
    let mut i = start;
    let mut depth = 0i32;
    let mut seen_ws = false;
    let mut end_idx: Option<usize> = None;
    while i < end {
        let c = char_at(text, i).unwrap();
        if c == '\\' {
            // skip escaped char (any next char) for boundary purposes
            i += 1 + char_at(text, i + 1).map(|n| n.len_utf8()).unwrap_or(0);
            continue;
        }
        match c {
            '(' => {
                if !seen_ws {
                    depth += 1;
                }
            }
            ')' => {
                if depth > 0 {
                    depth -= 1;
                } else {
                    end_idx = Some(i);
                    break;
                }
            }
            _ => {
                if c.is_whitespace() {
                    seen_ws = true;
                }
            }
        }
        i += c.len_utf8();
    }
    let close = end_idx?;
    let raw = &text[start..close];
    let after = close + 1;
    let trimmed_start = raw.trim_start_matches([' ', '\t', '\n', '\r']);
    // pointy
    if let Some(stripped) = trimmed_start.strip_prefix('<') {
        if let Some(gt) = stripped.find('>') {
            let inner = &stripped[..gt];
            // validity of remainder checked by clean parser; here just url
            return Some((decode_escapes_entities(inner), after));
        }
    }
    // first whitespace (unescaped, where backslash-space does count)
    let mut first_ws: Option<(usize, char)> = None;
    {
        let mut j = 0usize;
        let s = trimmed_start;
        while j < s.len() {
            let c = char_at(s, j).unwrap();
            if c == '\\' {
                if let Some(n) = char_at(s, j + 1) {
                    if is_ascii_punct(n) {
                        j += 1 + n.len_utf8();
                        continue;
                    }
                }
                j += 1;
                continue;
            }
            if c.is_whitespace() {
                first_ws = Some((j, c));
                break;
            }
            j += c.len_utf8();
        }
    }
    if let Some((ws_idx, ws_char)) = first_ws {
        let first_token = &trimmed_start[..ws_idx];
        let has_unescaped_paren = {
            let mut j = 0;
            let mut found = false;
            while j < first_token.len() {
                let c = char_at(first_token, j).unwrap();
                if c == '\\' {
                    j += 1 + char_at(first_token, j + 1).map(|n| n.len_utf8()).unwrap_or(0);
                    continue;
                }
                if c == '(' {
                    found = true;
                    break;
                }
                j += c.len_utf8();
            }
            found
        };
        if has_unescaped_paren || first_token.contains("\\)") || ws_char == '\n' || ws_char == '\r' {
            return Some((decode_escapes_entities(first_token), after));
        }
        return Some((decode_escapes_entities(trimmed_start), after));
    }
    Some((decode_escapes_entities(trimmed_start), after))
}

fn find_label_close(text: &str, open: usize, end: usize) -> Option<usize> {
    // open points at '['; find matching ']'
    let mut depth = 0i32;
    let mut i = open;
    while i < end {
        let c = char_at(text, i).unwrap();
        match c {
            '\\' => {
                i += 1 + char_at(text, i + 1).map(|n| n.len_utf8()).unwrap_or(0);
                continue;
            }
            '`' => {
                let run = count_run(text, i, '`');
                if let Some((_, after)) = find_code_span(text, i, run, end) {
                    i = after;
                    continue;
                }
                i += run;
                continue;
            }
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    return Some(i);
                }
            }
            _ => {}
        }
        i += c.len_utf8();
    }
    None
}

fn try_parse_link(p: &mut InlineParser, start: usize, end: usize, is_image: bool) -> Option<usize> {
    let text = p.text;
    let bracket = if is_image { start + 1 } else { start };
    let close = find_label_close(text, bracket, end)?;
    let label_start = bracket + 1;
    let label_end = close;
    let after_close = close + 1;

    // inline destination
    let dest_info: Option<LinkDest> = if char_at(text, after_close) == Some('(') {
        parse_inline_dest(text, after_close, end)
    } else if char_at(text, after_close) == Some('[') {
        // full or collapsed reference
        let ref_close = find_label_close(text, after_close, end)?;
        let ref_label = &text[after_close + 1..ref_close];
        let label = if ref_label.trim().is_empty() {
            normalize_label(&text[label_start..label_end])
        } else {
            normalize_label(ref_label)
        };
        let (dest, title) = p.refs.get(&label)?;
        Some(LinkDest {
            dest: dest.clone(),
            doc_url: dest.clone(),
            title: title.clone(),
            after: ref_close + 1,
        })
    } else {
        // shortcut reference
        let label = normalize_label(&text[label_start..label_end]);
        if label.is_empty() {
            return None;
        }
        let (dest, title) = p.refs.get(&label)?;
        Some(LinkDest {
            dest: dest.clone(),
            doc_url: dest.clone(),
            title: title.clone(),
            after: after_close,
        })
    };
    let dest_info = dest_info?;
    p.flush();
    if is_image {
        p.events.push(InlineEvent::StartImage {
            dest: dest_info.dest.clone(),
            doc_url: dest_info.doc_url.clone(),
            title: dest_info.title.clone(),
        });
    } else {
        p.events.push(InlineEvent::StartLink {
            dest: dest_info.dest.clone(),
            doc_url: dest_info.doc_url.clone(),
            title: dest_info.title.clone(),
        });
    }
    parse_inline_range(p, label_start, label_end);
    p.flush();
    if is_image {
        p.events.push(InlineEvent::EndImage);
    } else {
        p.events.push(InlineEvent::EndLink);
    }
    Some(dest_info.after)
}

// ----- emphasis -----

fn is_left_flanking(text: &str, start: usize, after: usize) -> bool {
    let next = char_at(text, after);
    match next {
        None => false,
        Some(c) if c.is_whitespace() => false,
        Some(c) if is_ascii_punct(c) => {
            let prev = prev_char(text, start);
            prev.map(|pc| pc.is_whitespace() || is_ascii_punct(pc)).unwrap_or(true)
        }
        _ => true,
    }
}

fn is_right_flanking(text: &str, start: usize, after: usize) -> bool {
    let prev = prev_char(text, start);
    match prev {
        None => false,
        Some(c) if c.is_whitespace() => false,
        Some(c) if is_ascii_punct(c) => {
            let next = char_at(text, after);
            next.map(|nc| nc.is_whitespace() || is_ascii_punct(nc)).unwrap_or(true)
        }
        _ => true,
    }
}

fn try_parse_emphasis(
    p: &mut InlineParser,
    start: usize,
    end: usize,
    marker: char,
    run: usize,
) -> Option<usize> {
    let text = p.text;
    // Determine desired strength: prefer 2 if run>=2 and a closer exists.
    for want in if run >= 2 { vec![2usize, 1] } else { vec![1usize] } {
        let open_end = start + want * marker.len_utf8();
        if !is_left_flanking(text, start, open_end) {
            continue;
        }
        if marker == '_' {
            // intraword underscores cannot open
            let prev = prev_char(text, start);
            if let Some(pc) = prev {
                if pc.is_alphanumeric() {
                    continue;
                }
            }
        }
        // search for a closing run
        let mut i = open_end;
        while i < end {
            let c = char_at(text, i).unwrap();
            if c == '\\' {
                i += 1 + char_at(text, i + 1).map(|n| n.len_utf8()).unwrap_or(0);
                continue;
            }
            if c == '`' {
                let r = count_run(text, i, '`');
                if let Some((_, after)) = find_code_span(text, i, r, end) {
                    i = after;
                    continue;
                }
                i += r;
                continue;
            }
            if c == marker {
                let crun = count_run(text, i, marker);
                if crun >= want {
                    let close_start = i + (crun - want) * marker.len_utf8();
                    let close_end = i + crun * marker.len_utf8();
                    if is_right_flanking(text, close_start, close_end)
                        && close_start > open_end
                    {
                        if marker == '_' {
                            let next = char_at(text, close_end);
                            if let Some(nc) = next {
                                if nc.is_alphanumeric() {
                                    i = close_end;
                                    continue;
                                }
                            }
                        }
                        // content before this span on this level is handled by
                        // caller loop; here we emit the span directly.
                        p.flush();
                        // any surplus opening markers (run-want) are literal
                        // text *inside* is wrong for 3+ runs, but handle the
                        // common case where surplus belongs before.
                        if want == 2 {
                            p.events.push(InlineEvent::StartStrong);
                        } else {
                            p.events.push(InlineEvent::StartEm);
                        }
                        if run > want {
                            // leftover marker chars at the start of content
                            let extra = run - want;
                            // They were part of the opening run; pulldown
                            // treats *** as em+strong. Emit an extra em
                            // start when extra==1 and want==2 inside strong
                            // is equivalent for our converter (strong wins).
                            let _ = extra;
                        }
                        parse_inline_range(p, open_end, close_start);
                        p.flush();
                        if want == 2 {
                            p.events.push(InlineEvent::EndStrong);
                        } else {
                            p.events.push(InlineEvent::EndEm);
                        }
                        return Some(close_end);
                    }
                }
                i += crun * marker.len_utf8();
                continue;
            }
            i += c.len_utf8();
        }
    }
    None
}

fn try_parse_strike(
    p: &mut InlineParser,
    start: usize,
    end: usize,
    run: usize,
) -> Option<usize> {
    let text = p.text;
    let open_end = start + run;
    if !is_left_flanking(text, start, open_end) {
        return None;
    }
    let mut i = open_end;
    while i < end {
        let c = char_at(text, i).unwrap();
        if c == '\\' {
            i += 1 + char_at(text, i + 1).map(|n| n.len_utf8()).unwrap_or(0);
            continue;
        }
        if c == '~' {
            let crun = count_run(text, i, '~');
            if crun >= run {
                let close_start = i + (crun - run);
                let close_end = i + crun;
                if is_right_flanking(text, close_start, close_end) && close_start > open_end {
                    p.flush();
                    p.events.push(InlineEvent::StartStrike);
                    parse_inline_range(p, open_end, close_start);
                    p.flush();
                    p.events.push(InlineEvent::EndStrike);
                    return Some(close_end);
                }
            }
            i += crun;
            continue;
        }
        i += c.len_utf8();
    }
    None
}

/// Plain text of a heading from its inline events: only Text events count.
pub fn heading_title_from_events(events: &[InlineEvent]) -> String {
    let mut out = String::new();
    for e in events {
        if let InlineEvent::Text(t) = e {
            out.push_str(t);
        }
    }
    out.trim().to_string()
}
