// ---------- inline model (document JSON) ----------

#[derive(Clone, Debug, Serialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum Inline {
    Text {
        value: String,
    },
    Code {
        value: String,
    },
    Strong {
        value: String,
    },
    Emphasis {
        value: String,
    },
    Strikethrough {
        value: String,
    },
    Link {
        text: String,
        url: String,
        title: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        line_offset: Option<usize>,
    },
    Image {
        alt: String,
        src: String,
        title: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        line_offset: Option<usize>,
    },
}

impl Inline {
    pub fn to_json(&self) -> JsonValue {
        serde_json::to_value(self).unwrap()
    }
    /// Text value for rendering (TUI etc.)
    pub fn plain_text(&self) -> &str {
        match self {
            Inline::Text { value }
            | Inline::Code { value }
            | Inline::Strong { value }
            | Inline::Emphasis { value }
            | Inline::Strikethrough { value } => value,
            Inline::Link { text, .. } => text,
            Inline::Image { alt, .. } => alt,
        }
    }
}

struct LinkState {
    text: String,
    url: String,
}
struct ImageState {
    alt: String,
    src: String,
}

/// Convert inline events into (model inlines, paragraph content string).
/// When `in_list` is true, Link/Image nodes carry line_offset 0 and
/// soft breaks do not create separate Text(" ") nodes.
pub fn convert_inlines(events: &[InlineEvent], in_list: bool) -> (Vec<Inline>, String) {
    let mut out: Vec<Inline> = Vec::new();
    let mut content = String::new();
    let mut strong = false;
    let mut em = false;
    let mut strike = false;
    let mut link: Option<LinkState> = None;
    let mut image: Option<ImageState> = None;

    let styled = |strong: bool, em: bool, strike: bool, v: String| -> Inline {
        if strong {
            Inline::Strong { value: v }
        } else if em {
            Inline::Emphasis { value: v }
        } else if strike {
            Inline::Strikethrough { value: v }
        } else {
            Inline::Text { value: v }
        }
    };

    for e in events {
        match e {
            InlineEvent::StartStrong => strong = true,
            InlineEvent::EndStrong => strong = false,
            InlineEvent::StartEm => em = true,
            InlineEvent::EndEm => em = false,
            InlineEvent::StartStrike => strike = true,
            InlineEvent::EndStrike => strike = false,
            InlineEvent::StartLink { doc_url, .. } => {
                link = Some(LinkState {
                    text: String::new(),
                    url: doc_url.clone(),
                });
            }
            InlineEvent::EndLink => {
                if let Some(l) = link.take() {
                    content.push_str(&format!("[{}]({})", l.text, l.url));
                    out.push(Inline::Link {
                        text: l.text,
                        url: l.url,
                        title: None,
                        line_offset: if in_list { Some(0) } else { None },
                    });
                }
            }
            InlineEvent::StartImage { doc_url, .. } => {
                content.clear();
                image = Some(ImageState {
                    alt: String::new(),
                    src: doc_url.clone(),
                });
            }
            InlineEvent::EndImage => {
                if let Some(im) = image.take() {
                    content.push_str(&format!("![{}]({})", im.alt, im.src));
                    out.push(Inline::Image {
                        alt: im.alt,
                        src: im.src,
                        title: None,
                        line_offset: if in_list { Some(0) } else { None },
                    });
                }
            }
            InlineEvent::Text(t) => {
                if let Some(im) = &mut image {
                    im.alt.push_str(t);
                } else if let Some(l) = &mut link {
                    l.text.push_str(t);
                } else {
                    content.push_str(t);
                    out.push(styled(strong, em, strike, t.clone()));
                }
            }
            InlineEvent::Code(v) => {
                if image.is_some() {
                    // code inside alt text is emitted as its own node
                    content.push_str(v);
                    out.push(Inline::Code { value: v.clone() });
                } else if link.is_some() {
                    content.push_str(v);
                    out.push(Inline::Code { value: v.clone() });
                } else {
                    content.push_str(v);
                    out.push(Inline::Code { value: v.clone() });
                }
            }
            InlineEvent::SoftBreak => {
                if let Some(im) = &mut image {
                    im.alt.push(' ');
                } else if let Some(l) = &mut link {
                    l.text.push(' ');
                } else if in_list {
                    content.push(' ');
                } else {
                    content.push(' ');
                    out.push(Inline::Text {
                        value: " ".to_string(),
                    });
                }
            }
            InlineEvent::HardBreak => {
                if let Some(im) = &mut image {
                    im.alt.push('\n');
                } else if let Some(l) = &mut link {
                    l.text.push('\n');
                } else {
                    content.push('\n');
                    out.push(Inline::Text {
                        value: "\n".to_string(),
                    });
                }
            }
            InlineEvent::Html(_) => {}
        }
    }
    (out, content)
}

/// All text from events (used for blockquote text): Text events only,
/// concatenated with no break characters.
fn events_text_only(events: &[InlineEvent]) -> String {
    let mut out = String::new();
    for e in events {
        if let InlineEvent::Text(t) = e {
            out.push_str(t);
        }
    }
    out
}

// ---------- block nodes ----------

#[derive(Clone, Debug)]
pub struct HeadingNode {
    pub level: usize,
    /// raw inline source of the heading (may contain '\n' for setext)
    pub inline_src: String,
    /// byte offset of '#' (or of setext title start) in effective source
    pub offset: usize,
    /// byte offset just after the first physical line of the heading
    pub first_line_end: usize,
}

#[derive(Clone, Debug)]
pub enum Node {
    Heading(HeadingNode),
    Paragraph {
        text: String,
    },
    Code {
        language: Option<String>,
        content: String,
    },
    Table {
        headers: Vec<String>,
        alignments: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    List {
        ordered: bool,
        items: Vec<ListItemNode>,
    },
    BlockQuote(Vec<Node>),
    HorizontalRule,
}

#[derive(Clone, Debug)]
pub struct ListItemNode {
    pub checked: Option<bool>,
    pub blocks: Vec<Node>,
}

fn atx_heading(line: &Line) -> Option<HeadingNode> {
    let text = &line.text;
    let indent = leading_columns(text);
    if indent > 3 {
        return None;
    }
    let stripped_idx = strip_columns(text, indent);
    let rest = &text[stripped_idx..];
    let hashes = rest.chars().take_while(|&c| c == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let after = &rest[hashes..];
    if !after.is_empty() && !after.starts_with([' ', '\t']) {
        return None;
    }
    let mut title = after.trim_matches([' ', '\t']).to_string();
    // strip an optional closing sequence of hashes
    if title.ends_with('#') {
        let trimmed = title.trim_end_matches('#');
        if trimmed.is_empty() {
            title = String::new();
        } else if trimmed.ends_with([' ', '\t']) {
            title = trimmed.trim_end_matches([' ', '\t']).to_string();
        }
    }
    Some(HeadingNode {
        level: hashes,
        inline_src: title,
        offset: line.start + stripped_idx,
        first_line_end: line.end,
    })
}

fn is_thematic_break(s: &str) -> bool {
    let indent = leading_columns(s);
    if indent > 3 {
        return false;
    }
    let rest = &s[strip_columns(s, indent)..];
    let mut marker: Option<char> = None;
    let mut count = 0usize;
    for c in rest.chars() {
        match c {
            '-' | '*' | '_' => {
                match marker {
                    None => marker = Some(c),
                    Some(m) if m == c => {}
                    _ => return false,
                }
                count += 1;
            }
            ' ' | '\t' => {}
            _ => return false,
        }
    }
    count >= 3
}

fn fence_start(s: &str) -> Option<(char, usize, String)> {
    let indent = leading_columns(s);
    if indent > 3 {
        return None;
    }
    let rest = &s[strip_columns(s, indent)..];
    let c = rest.chars().next()?;
    if c != '`' && c != '~' {
        return None;
    }
    let run = rest.chars().take_while(|&x| x == c).count();
    if run < 3 {
        return None;
    }
    let info = rest[run * c.len_utf8()..].trim().to_string();
    if c == '`' && info.contains('`') {
        return None;
    }
    Some((c, run, info))
}

fn fence_end(s: &str, fc: char, min_run: usize) -> bool {
    let indent = leading_columns(s);
    if indent > 3 {
        return false;
    }
    let rest = &s[strip_columns(s, indent)..];
    let run = rest.chars().take_while(|&x| x == fc).count();
    if run < min_run {
        return false;
    }
    rest[run * fc.len_utf8()..].trim().is_empty()
}

fn blockquote_prefix(s: &str) -> Option<usize> {
    // returns byte index in s where inner content starts
    let indent = leading_columns(s);
    if indent > 3 {
        return None;
    }
    let idx = strip_columns(s, indent);
    let rest = &s[idx..];
    if !rest.starts_with('>') {
        return None;
    }
    let mut after = idx + 1;
    // one optional space or tab (tab expands; approximate with 1 byte)
    if after < s.len() && (s.as_bytes()[after] == b' ' || s.as_bytes()[after] == b'\t') {
        after += 1;
    }
    Some(after)
}

struct ListMarker {
    ordered: bool,
    number: u64,
    bullet: char,
    delim: char,
    content_idx: usize, // byte index into line.text where item content starts
    content_col: usize, // column where content starts
    indent: usize,
}

fn list_marker(s: &str) -> Option<ListMarker> {
    let indent = leading_columns(s);
    if indent > 3 {
        return None;
    }
    let idx = strip_columns(s, indent);
    let rest = &s[idx..];
    let mut chars = rest.char_indices();
    let (_, first) = chars.next()?;
    if (first == '-' || first == '+' || first == '*') {
        let after = &rest[1..];
        if after.is_empty() {
            return Some(ListMarker {
                ordered: false,
                number: 0,
                bullet: first,
                delim: first,
                content_idx: idx + 1,
                content_col: indent + 2,
                indent,
            });
        }
        if !after.starts_with([' ', '\t']) {
            return None;
        }
        let spaces = count_space_columns(after, indent + 1);
        let used = if spaces >= 5 { 1 } else { spaces };
        let bidx = strip_columns(after, used);
        return Some(ListMarker {
            ordered: false,
            number: 0,
            bullet: first,
            delim: first,
            content_idx: idx + 1 + bidx,
            content_col: indent + 1 + used,
            indent,
        });
    }
    if first.is_ascii_digit() {
        let digits: String = rest.chars().take_while(|c| c.is_ascii_digit()).collect();
        if digits.is_empty() || digits.len() > 9 {
            return None;
        }
        let after_num = &rest[digits.len()..];
        let mut ach = after_num.chars();
        let delim = ach.next()?;
        if delim != '.' && delim != ')' {
            return None;
        }
        let after = &after_num[1..];
        let marker_len = digits.len() + 1;
        if after.is_empty() {
            return Some(ListMarker {
                ordered: true,
                number: digits.parse().unwrap_or(0),
                bullet: delim,
                delim,
                content_idx: idx + marker_len,
                content_col: indent + marker_len + 1,
                indent,
            });
        }
        if !after.starts_with([' ', '\t']) {
            return None;
        }
        let spaces = count_space_columns(after, indent + marker_len);
        let used = if spaces >= 5 { 1 } else { spaces };
        let bidx = strip_columns(after, used);
        return Some(ListMarker {
            ordered: true,
            number: digits.parse().unwrap_or(0),
            bullet: delim,
            delim,
            content_idx: idx + marker_len + bidx,
            content_col: indent + marker_len + used,
            indent,
        });
    }
    None
}

fn count_space_columns(s: &str, base_col: usize) -> usize {
    let mut col = 0usize;
    for c in s.chars() {
        match c {
            ' ' => col += 1,
            '\t' => col += 4 - ((base_col + col) % 4),
            _ => break,
        }
    }
    col
}

fn split_table_row(s: &str) -> Vec<String> {
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut escaped = false;
    let mut in_code = false;
    let trimmed = s.trim();
    let body = trimmed.strip_prefix('|').unwrap_or(trimmed);
    // handle trailing pipe specially at the end
    for c in body.chars() {
        if escaped {
            if c == '|' {
                cur.push('|');
            } else {
                cur.push('\\');
                cur.push(c);
            }
            escaped = false;
            continue;
        }
        match c {
            '\\' => escaped = true,
            '`' => {
                in_code = !in_code;
                cur.push(c);
            }
            '|' if !in_code => {
                cells.push(cur.trim().to_string());
                cur = String::new();
            }
            _ => cur.push(c),
        }
    }
    if escaped {
        cur.push('\\');
    }
    let last = cur.trim().to_string();
    // If the row ended with a pipe, the final empty segment is dropped.
    let ends_with_pipe = {
        let t = trimmed.trim_end();
        t.ends_with('|') && !t.ends_with("\\|")
    };
    if !last.is_empty() || !ends_with_pipe {
        cells.push(last);
    }
    cells
}

fn table_delimiter(s: &str) -> Option<Vec<String>> {
    if !s.contains('-') {
        return None;
    }
    let cells = split_table_row(s);
    if cells.is_empty() {
        return None;
    }
    let mut aligns = Vec::new();
    for c in &cells {
        let c = c.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let core = c.trim_matches(':');
        if core.is_empty() || !core.chars().all(|x| x == '-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => "center".to_string(),
            (true, false) => "left".to_string(),
            (false, true) => "right".to_string(),
            (false, false) => "none".to_string(),
        });
    }
    Some(aligns)
}

fn is_html_block_start(s: &str) -> bool {
    let indent = leading_columns(s);
    if indent > 3 {
        return false;
    }
    let rest = &s[strip_columns(s, indent)..];
    if !rest.starts_with('<') {
        return false;
    }
    if rest.starts_with("<!--")
        || rest.starts_with("<?")
        || rest.starts_with("<![CDATA[")
        || rest.starts_with("<!")
    {
        return true;
    }
    let inner = rest[1..].strip_prefix('/').unwrap_or(&rest[1..]);
    let name: String = inner
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '-')
        .collect::<String>()
        .to_lowercase();
    if name.is_empty() {
        return false;
    }
    if !matches!(inner.chars().next(), Some(c) if c.is_ascii_alphabetic()) {
        return false;
    }
    const BLOCK_TAGS: &[&str] = &[
        "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption",
        "center", "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt",
        "fieldset", "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2",
        "h3", "h4", "h5", "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link",
        "main", "menu", "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param",
        "section", "source", "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title",
        "tr", "track", "ul", "script", "pre", "style", "textarea",
    ];
    // A closing tag or any block tag starts an HTML block; other tags can
    // also start one when the line is a complete open/close tag at line start.
    if BLOCK_TAGS.contains(&name.as_str()) {
        let after = &inner[name.len()..];
        return after.is_empty()
            || after.starts_with(|c: char| c.is_whitespace() || c == '>' || c == '/');
    }
    false
}

fn setext_level(s: &str) -> Option<usize> {
    let indent = leading_columns(s);
    if indent > 3 {
        return None;
    }
    let rest = s[strip_columns(s, indent)..].trim_end();
    if !rest.is_empty() && rest.chars().all(|c| c == '=') {
        Some(1)
    } else if !rest.is_empty() && rest.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

pub struct BlockParseOptions {
    pub allow_metadata: bool,
}

pub fn parse_nodes(lines_in: &[Line], refs: &mut RefMap, opts: &BlockParseOptions) -> Vec<Node> {
    let lines: Vec<Line> = lines_in.to_vec();
    let mut nodes: Vec<Node> = Vec::new();
    let mut i = 0usize;
    let mut first_block = true;
    while i < lines.len() {
        let line = &lines[i];
        if is_blank(&line.text) {
            i += 1;
            continue;
        }
        // YAML metadata at document start
        if first_block && opts.allow_metadata && line.text == "---" {
            if let Some(close) = (i + 1..lines.len())
                .find(|&j| lines[j].text == "---" || lines[j].text == "...")
            {
                i = close + 1;
                first_block = false;
                continue;
            }
        }
        first_block = false;

        // reference definitions
        if let Some((label, dest, title, used)) = parse_ref_def(&lines, i) {
            refs.entry(label).or_insert((dest, title));
            i += used;
            continue;
        }

        // fenced code
        if let Some((fc, run, info)) = fence_start(&line.text) {
            let mut j = i + 1;
            let mut content_lines: Vec<String> = Vec::new();
            while j < lines.len() {
                if fence_end(&lines[j].text, fc, run) {
                    break;
                }
                content_lines.push(lines[j].text.clone());
                j += 1;
            }
            let language = {
                let first = info.split_whitespace().next().unwrap_or("");
                if first.is_empty() {
                    None
                } else {
                    Some(first.to_string())
                }
            };
            nodes.push(Node::Code {
                language,
                content: content_lines.join("\n"),
            });
            i = if j < lines.len() { j + 1 } else { j };
            continue;
        }

        // ATX heading
        if let Some(h) = atx_heading(line) {
            nodes.push(Node::Heading(h));
            i += 1;
            continue;
        }

        // thematic break
        if is_thematic_break(&line.text) {
            nodes.push(Node::HorizontalRule);
            i += 1;
            continue;
        }

        // html block (dropped)
        if is_html_block_start(&line.text) {
            i += 1;
            while i < lines.len() && !is_blank(&lines[i].text) {
                i += 1;
            }
            continue;
        }

        // blockquote
        if blockquote_prefix(&line.text).is_some() {
            let mut inner: Vec<Line> = Vec::new();
            let mut j = i;
            while j < lines.len() {
                let l = &lines[j];
                if let Some(after) = blockquote_prefix(&l.text) {
                    inner.push(Line {
                        text: l.text[after..].to_string(),
                        start: l.start + after,
                        end: l.end,
                    });
                    j += 1;
                } else if is_blank(&l.text) {
                    // blank line ends the quote unless a later line is quoted
                    break;
                } else if !inner.is_empty()
                    && !is_blank(&inner.last().unwrap().text)
                    && atx_heading(l).is_none()
                    && fence_start(&l.text).is_none()
                    && !is_thematic_break(&l.text)
                    && list_marker(&l.text).is_none()
                    && !is_html_block_start(&l.text)
                {
                    // lazy continuation
                    inner.push(l.clone());
                    j += 1;
                } else {
                    break;
                }
            }
            let children = parse_nodes(&inner, refs, opts);
            nodes.push(Node::BlockQuote(children));
            i = j;
            continue;
        }

        // list
        if let Some(marker) = list_marker(&line.text) {
            let (list, used) = parse_list(&lines, i, &marker, refs, opts);
            nodes.push(list);
            i += used;
            continue;
        }

        // indented code
        if leading_columns(&line.text) >= 4 {
            let mut j = i;
            let mut contents: Vec<String> = Vec::new();
            while j < lines.len() {
                let l = &lines[j];
                if leading_columns(&l.text) >= 4 {
                    let idx = strip_columns(&l.text, 4);
                    contents.push(l.text[idx..].to_string());
                    j += 1;
                } else if is_blank(&l.text) {
                    contents.push(String::new());
                    j += 1;
                } else {
                    break;
                }
            }
            while contents.last().map(|c| c.is_empty()).unwrap_or(false) {
                contents.pop();
            }
            nodes.push(Node::Code {
                language: None,
                content: contents.join("\n"),
            });
            i = j;
            continue;
        }

        // table starting at this line
        if line.text.contains('|') && i + 1 < lines.len() {
            if let Some(aligns) = table_delimiter(&lines[i + 1].text) {
                let headers = split_table_row(&line.text);
                if headers.len() == aligns.len() {
                    let mut rows = Vec::new();
                    let mut j = i + 2;
                    while j < lines.len()
                        && !is_blank(&lines[j].text)
                        && lines[j].text.contains('|')
                    {
                        let mut row = split_table_row(&lines[j].text);
                        row.resize(headers.len(), String::new());
                        rows.push(row);
                        j += 1;
                    }
                    nodes.push(Node::Table {
                        headers,
                        alignments: aligns,
                        rows,
                    });
                    i = j;
                    continue;
                }
            }
        }

        // paragraph (possibly becoming setext heading or table)
        let mut para: Vec<Line> = vec![line.clone()];
        let mut j = i + 1;
        let mut consumed_extra = false;
        loop {
            if j >= lines.len() {
                break;
            }
            let l = &lines[j];
            if is_blank(&l.text) {
                break;
            }
            // setext underline
            if let Some(level) = setext_level(&l.text) {
                let first = para[0].clone();
                let inline_src = para
                    .iter()
                    .map(|pl| pl.text.trim().to_string())
                    .collect::<Vec<_>>()
                    .join("\n");
                nodes.push(Node::Heading(HeadingNode {
                    level,
                    inline_src,
                    offset: first.start + strip_columns(&first.text, leading_columns(&first.text).min(3)),
                    first_line_end: first.end,
                }));
                j += 1;
                consumed_extra = true;
                para.clear();
                break;
            }
            // table: delimiter next, last para line is the header
            if l.text.contains('|') || true {
                if let Some(aligns) = table_delimiter(&l.text) {
                    let headers = split_table_row(&para.last().unwrap().text);
                    if headers.len() == aligns.len() && para.last().unwrap().text.contains('|') {
                        // preceding lines form their own paragraph
                        if para.len() > 1 {
                            let pre: Vec<String> =
                                para[..para.len() - 1].iter().map(|pl| para_line_text(pl)).collect();
                            nodes.push(Node::Paragraph {
                                text: pre.join("\n"),
                            });
                        }
                        let mut rows = Vec::new();
                        let mut k = j + 1;
                        while k < lines.len()
                            && !is_blank(&lines[k].text)
                            && lines[k].text.contains('|')
                        {
                            let mut row = split_table_row(&lines[k].text);
                            row.resize(headers.len(), String::new());
                            rows.push(row);
                            k += 1;
                        }
                        nodes.push(Node::Table {
                            headers,
                            alignments: aligns,
                            rows,
                        });
                        j = k;
                        consumed_extra = true;
                        para.clear();
                        break;
                    }
                }
            }
            // interruptions
            if atx_heading(l).is_some()
                || fence_start(&l.text).is_some()
                || blockquote_prefix(&l.text).is_some()
                || is_thematic_break(&l.text)
                || is_html_block_start(&l.text)
            {
                break;
            }
            if let Some(m) = list_marker(&l.text) {
                // a list can interrupt a paragraph unless it is an empty
                // item or an ordered list not starting at 1
                let empty_item = l.text[m.content_idx..].trim().is_empty();
                if !empty_item && (!m.ordered || m.number == 1) {
                    break;
                }
            }
            para.push(l.clone());
            j += 1;
        }
        if !para.is_empty() {
            let text: Vec<String> = para.iter().map(|pl| para_line_text(pl)).collect();
            nodes.push(Node::Paragraph {
                text: text.join("\n"),
            });
        }
        let _ = consumed_extra;
        i = j;
    }
    nodes
}

fn para_line_text(l: &Line) -> String {
    let indent = leading_columns(&l.text).min(3);
    let idx = strip_columns(&l.text, indent);
    l.text[idx..].to_string()
}

fn same_list(a: &ListMarker, b: &ListMarker) -> bool {
    if a.ordered != b.ordered {
        return false;
    }
    if a.ordered {
        a.delim == b.delim
    } else {
        a.bullet == b.bullet
    }
}

fn parse_list(
    lines: &[Line],
    start: usize,
    first_marker: &ListMarker,
    refs: &mut RefMap,
    opts: &BlockParseOptions,
) -> (Node, usize) {
    let mut items: Vec<ListItemNode> = Vec::new();
    let mut i = start;
    let mut current_marker = ListMarker {
        ordered: first_marker.ordered,
        number: first_marker.number,
        bullet: first_marker.bullet,
        delim: first_marker.delim,
        content_idx: first_marker.content_idx,
        content_col: first_marker.content_col,
        indent: first_marker.indent,
    };
    loop {
        // collect lines for one item
        let first_line = &lines[i];
        let mut item_lines: Vec<Line> = vec![Line {
            text: first_line.text[current_marker.content_idx..].to_string(),
            start: first_line.start + current_marker.content_idx,
            end: first_line.end,
        }];
        let base_indent = current_marker.indent;
        let content_col = current_marker.content_col;
        let mut j = i + 1;
        let mut next_marker: Option<ListMarker> = None;
        while j < lines.len() {
            let l = &lines[j];
            if is_blank(&l.text) {
                // look ahead: blank belongs to the item if followed by
                // indented content or another item of this list
                let mut k = j + 1;
                while k < lines.len() && is_blank(&lines[k].text) {
                    k += 1;
                }
                if k >= lines.len() {
                    j = k;
                    break;
                }
                let nl = &lines[k];
                if leading_columns(&nl.text) >= content_col {
                    for _ in j..k {
                        item_lines.push(Line {
                            text: String::new(),
                            start: nl.start,
                            end: nl.start,
                        });
                    }
                    j = k;
                    continue;
                }
                if let Some(m) = list_marker(&nl.text) {
                    if m.indent <= base_indent + 3 && same_list(&current_marker, &m) {
                        next_marker = Some(m);
                        j = k;
                        break;
                    }
                }
                j = k;
                break;
            }
            if leading_columns(&l.text) >= content_col {
                let idx = strip_columns(&l.text, content_col);
                item_lines.push(Line {
                    text: l.text[idx..].to_string(),
                    start: l.start + idx,
                    end: l.end,
                });
                j += 1;
                continue;
            }
            if let Some(m) = list_marker(&l.text) {
                if m.indent <= base_indent + 3 && same_list(&current_marker, &m) {
                    next_marker = Some(m);
                    break;
                }
            }
            // block starts that end the whole list
            if atx_heading(l).is_some()
                || fence_start(&l.text).is_some()
                || blockquote_prefix(&l.text).is_some()
                || is_thematic_break(&l.text)
            {
                break;
            }
            // lazy continuation (previous line non-blank)
            if !item_lines.last().map(|x| is_blank(&x.text)).unwrap_or(true) {
                item_lines.push(l.clone());
                j += 1;
                continue;
            }
            break;
        }
        // task checkbox on the first line
        let mut checked: Option<bool> = None;
        if let Some(first) = item_lines.first_mut() {
            let t = first.text.clone();
            for (pat, val) in [("[ ]", false), ("[x]", true), ("[X]", true)] {
                if let Some(rest) = t.strip_prefix(pat) {
                    if rest.is_empty() || rest.starts_with([' ', '\t']) {
                        checked = Some(val);
                        first.text = rest.trim_start_matches([' ', '\t']).to_string();
                        first.start += t.len() - first.text.len();
                        break;
                    }
                }
            }
        }
        let blocks = parse_nodes(&item_lines, refs, opts);
        items.push(ListItemNode { checked, blocks });
        match next_marker {
            Some(m) => {
                current_marker = m;
                i = j;
            }
            None => {
                i = j;
                break;
            }
        }
    }
    (
        Node::List {
            ordered: first_marker.ordered,
            items,
        },
        i - start,
    )
}
