    pub blocks: Vec<Block>,
}

fn cell_text(raw: &str, refs: &RefMap) -> String {
    let events = parse_inline_events(raw, refs);
    let (_, content) = convert_inlines(&events, false);
    content
}

fn convert_table(
    headers: &[String],
    alignments: &[String],
    rows: &[Vec<String>],
    refs: &RefMap,
) -> Block {
    Block::Table {
        headers: headers.iter().map(|h| cell_text(h, refs)).collect(),
        alignments: alignments.to_vec(),
        rows: rows
            .iter()
            .map(|r| r.iter().map(|c| cell_text(c, refs)).collect())
            .collect(),
    }
}

fn node_text_only(node: &Node, refs: &RefMap) -> String {
    let mut out = String::new();
    match node {
        Node::Paragraph { text } => {
            let events = parse_inline_events(text, refs);
            out.push_str(&events_text_only(&events));
        }
        Node::Heading(h) => {
            let events = parse_inline_events(&h.inline_src, refs);
            out.push_str(&events_text_only(&events));
        }
        Node::List { items, .. } => {
            for item in items {
                for b in &item.blocks {
                    out.push_str(&node_text_only(b, refs));
                }
            }
        }
        Node::BlockQuote(children) => {
            for c in children {
                out.push_str(&node_text_only(c, refs));
            }
        }
        Node::Table { headers, rows, .. } => {
            for h in headers {
                out.push_str(h);
            }
            for r in rows {
                for c in r {
                    out.push_str(c);
                }
            }
        }
        _ => {}
    }
    out
}

/// Stray inline conversion used inside blockquotes: non-text inline
/// elements are collected, link/image text is dropped.
fn stray_inlines(events: &[InlineEvent], in_list: bool) -> (Vec<Inline>, String) {
    let mut out: Vec<Inline> = Vec::new();
    let mut content = String::new();
    for e in events {
        match e {
            InlineEvent::Code(v) => {
                content.push_str(v);
                out.push(Inline::Code { value: v.clone() });
            }
            InlineEvent::SoftBreak => {
                content.push(' ');
                out.push(Inline::Text {
                    value: " ".to_string(),
                });
            }
            InlineEvent::HardBreak => {
                content.push('\n');
                out.push(Inline::Text {
                    value: "\n".to_string(),
                });
            }
            InlineEvent::StartLink { doc_url, .. } => {
                content.push_str(&format!("[]({doc_url})"));
                out.push(Inline::Link {
                    text: String::new(),
                    url: doc_url.clone(),
                    title: None,
                    line_offset: if in_list { Some(0) } else { None },
                });
            }
            InlineEvent::StartImage { doc_url, .. } => {
                content.push_str(&format!("![]({doc_url})"));
                out.push(Inline::Image {
                    alt: String::new(),
                    src: doc_url.clone(),
                    title: None,
                    line_offset: if in_list { Some(0) } else { None },
                });
            }
            _ => {}
        }
    }
    (out, content)
}

fn convert_list(
    ordered: bool,
    items: &[ListItemNode],
    refs: &RefMap,
    code_line: usize,
    in_quote: bool,
) -> Block {
    let mut out_items: Vec<ListItem> = Vec::new();
    for item in items {
        if item.blocks.is_empty() {
            out_items.push(ListItem {
                checked: item.checked,
                content: String::new(),
                inline: vec![],
                blocks: vec![],
            });
            continue;
        }
        match &item.blocks[0] {
            Node::Paragraph { text } => {
                let events = parse_inline_events(text, refs);
                let (inline, content) = if in_quote {
                    stray_inlines(&events, true)
                } else {
                    convert_inlines(&events, true)
                };
                let rest: Vec<Block> = item.blocks[1..]
                    .iter()
                    .flat_map(|n| convert_node(n, refs, code_line, in_quote))
                    .collect();
                out_items.push(ListItem {
                    checked: item.checked,
                    content,
                    inline,
                    blocks: rest,
                });
            }
            Node::Heading(h) => {
                let events = parse_inline_events(&h.inline_src, refs);
                let (inline, _content) = if in_quote {
                    stray_inlines(&events, true)
                } else {
                    convert_inlines(&events, true)
                };
                let content = heading_title_from_events(&events);
                let rest: Vec<Block> = item.blocks[1..]
                    .iter()
                    .flat_map(|n| convert_node(n, refs, code_line, in_quote))
                    .collect();
                out_items.push(ListItem {
                    checked: item.checked,
                    content: if in_quote { String::new() } else { content },
                    inline,
                    blocks: rest,
                });
            }
            _ => {
                let rest: Vec<Block> = item
                    .blocks
                    .iter()
                    .flat_map(|n| convert_node(n, refs, code_line, in_quote))
                    .collect();
                out_items.push(ListItem {
                    checked: item.checked,
                    content: String::new(),
                    inline: vec![],
                    blocks: rest,
                });
            }
        }
    }
    Block::List {
        ordered,
        items: out_items,
    }
}

/// Convert a block node into zero or more document blocks.
fn convert_node(node: &Node, refs: &RefMap, code_line: usize, in_quote: bool) -> Vec<Block> {
    match node {
        Node::Paragraph { text } => {
            let events = parse_inline_events(text, refs);
            let (inline, content) = convert_inlines(&events, false);
            vec![Block::Paragraph { content, inline }]
        }
        Node::Heading(h) => {
            let events = parse_inline_events(&h.inline_src, refs);
            let (inline, _c) = convert_inlines(&events, false);
            let content = heading_title_from_events(&events);
            let anchor = slugify(&content);
            vec![Block::Heading {
                level: h.level,
                content,
                inline,
                anchor,
            }]
        }
        Node::Code { language, content } => vec![Block::Code {
            language: language.clone(),
            content: content.clone(),
            start_line: code_line,
            end_line: code_line,
        }],
        Node::Table {
            headers,
            alignments,
            rows,
        } => vec![convert_table(headers, alignments, rows, refs)],
        Node::List { ordered, items } => vec![convert_list(*ordered, items, refs, code_line, in_quote)],
        Node::HorizontalRule => vec![Block::HorizontalRule],
        Node::BlockQuote(children) => {
            let mut emitted: Vec<Block> = Vec::new();
            let mut stray_inline: Vec<Inline> = Vec::new();
            let mut stray_content = String::new();
            let mut quote_text = String::new();
            for child in children {
                match child {
                    Node::Paragraph { text } => {
                        let events = parse_inline_events(text, refs);
                        quote_text.push_str(&events_text_only(&events));
                        let (si, sc) = stray_inlines(&events, false);
                        stray_inline.extend(si);
                        stray_content.push_str(&sc);
                    }
                    Node::Heading(h) => {
                        let events = parse_inline_events(&h.inline_src, refs);
                        quote_text.push_str(&events_text_only(&events));
                        let (si, sc) = stray_inlines(&events, false);
                        stray_inline.extend(si);
                        stray_content.push_str(&sc);
                    }
                    Node::Code { .. } | Node::Table { .. } => {
                        emitted.extend(convert_node(child, refs, code_line, true));
                    }
                    Node::List { ordered, items } => {
                        for item in items {
                            for b in &item.blocks {
                                quote_text.push_str(&node_text_only(b, refs));
                            }
                        }
                        emitted.push(convert_list(*ordered, items, refs, code_line, true));
                    }
                    Node::BlockQuote(inner) => {
                        // flatten nested quotes into the text
                        for n in inner {
                            quote_text.push_str(&node_text_only(n, refs));
                        }
                        emitted.extend(
                            inner
                                .iter()
                                .filter(|n| matches!(n, Node::Code { .. }))
                                .flat_map(|n| convert_node(n, refs, code_line, true)),
                        );
                    }
                    Node::HorizontalRule => {}
                }
            }
            if !stray_inline.is_empty() {
                emitted.push(Block::Paragraph {
                    content: stray_content,
                    inline: stray_inline,
                });
            }
            let blocks = if quote_text.is_empty() {
                vec![]
            } else {
                vec![Block::Paragraph {
                    content: quote_text.clone(),
                    inline: vec![Inline::Text {
                        value: quote_text.clone(),
                    }],
                }]
            };
            emitted.push(Block::Blockquote {
                content: quote_text,
                blocks,
            });
            emitted
        }
    }
}

pub fn convert_nodes(nodes: &[Node], refs: &RefMap, code_line: usize) -> Vec<Block> {
    nodes
        .iter()
        .flat_map(|n| convert_node(n, refs, code_line, false))
        .collect()
}

// ---------- document ----------

#[derive(Clone, Debug)]
pub struct HeadingInfo {
    pub level: usize,
    pub text: String,
    pub slug: String,
    /// query line (1-based, with the leading-line quirk)
    pub line: usize,
    /// byte offset of heading start in effective source
    pub offset: usize,
    pub index: usize,
    pub content: String,
    pub raw_md: String,
}

#[derive(Clone, Debug)]
pub struct Section {
    pub level: usize,
    pub title: String,
    pub slug: String,
    pub pos_line: usize,
    pub pos_offset: usize,
    pub raw: String,
    pub blocks: Vec<Block>,
    pub children: Vec<Section>,
}

pub struct Document {
    pub source: String,
    pub sections: Vec<Section>,
    pub headings: Vec<HeadingInfo>,
    pub global_nodes: Vec<Node>,
    pub global_refs: RefMap,
}

fn flatten_heading_nodes<'a>(nodes: &'a [Node], out: &mut Vec<&'a HeadingNode>) {
    for n in nodes {
        match n {
            Node::Heading(h) => out.push(h),
            Node::BlockQuote(children) => flatten_heading_nodes(children, out),
            Node::List { items, .. } => {
                for item in items {
                    flatten_heading_nodes(&item.blocks, out);
                }
            }
            _ => {}
        }
    }
}

fn extract_raw(source: &str, start: usize) -> String {
    if start >= source.len() {
        return String::new();
    }
    let mut in_fence: Option<char> = None;
    let mut offset = start;
    let mut end = source.len();
    for seg in source[start..].split_inclusive('\n') {
        let mut text = seg.strip_suffix('\n').unwrap_or(seg);
        if text.ends_with('\r') {
            text = &text[..text.len() - 1];
        }
        let trimmed = text.trim_start();
        let fence_char = if trimmed.starts_with("```") {
            Some('`')
        } else if trimmed.starts_with("~~~") {
            Some('~')
        } else {
            None
        };
        if let Some(fc) = fence_char {
            match in_fence {
                None => in_fence = Some(fc),
                Some(open) if open == fc => in_fence = None,
                _ => {}
            }
        } else if in_fence.is_none() {
            let hashes = trimmed.chars().take_while(|&c| c == '#').count();
            if hashes >= 1 && hashes <= 6 {
                let after = &trimmed[hashes..];
                if after.is_empty() || after.starts_with([' ', '\t']) {
                    end = offset;
                    break;
                }
            }
        }
        offset += seg.len();
    }
    source[start..end].trim().to_string()
}

impl Document {
    pub fn parse(content: &str) -> Document {
        let has_heading = content
            .lines()
            .any(|l| l.trim_start().starts_with('#'));
        let effective: String = if has_heading {
            content.to_string()
        } else {
            format!("# Input\n\n{content}")
        };
        let lines = split_lines(&effective);
        let mut refs: RefMap = HashMap::new();
        let opts = BlockParseOptions {
            allow_metadata: true,
        };
        let nodes = parse_nodes(&lines, &mut refs, &opts);

        let mut heading_nodes: Vec<&HeadingNode> = Vec::new();
        flatten_heading_nodes(&nodes, &mut heading_nodes);

        // build heading infos
        struct HMeta {
            level: usize,
            title: String,
            slug: String,
            line: usize,
            doc_line: usize,
            doc_offset: usize,
            offset: usize,
            first_line_end: usize,
        }
        let mut metas: Vec<HMeta> = Vec::new();
        for hn in &heading_nodes {
            let events = parse_inline_events(&hn.inline_src, &refs);
            let title = heading_title_from_events(&events);
            let line = effective[..hn.offset.min(effective.len())].lines().count() + 1;
            let doc_line = line + 1;
            let has_newline = hn.first_line_end <= effective.len()
                && hn.first_line_end > 0
                && effective.as_bytes().get(hn.first_line_end - 1) == Some(&b'\n');
            let doc_offset = if has_newline {
                hn.first_line_end
            } else {
                hn.offset
            };
            metas.push(HMeta {
                level: hn.level,
                slug: slugify(&title),
                title,
                line,
                doc_line,
                doc_offset,
                offset: hn.offset,
                first_line_end: hn.first_line_end,
            });
        }

        let mut headings: Vec<HeadingInfo> = Vec::new();
        for (idx, m) in metas.iter().enumerate() {
            let end = metas[idx + 1..]
                .iter()
                .find(|n| n.level <= m.level)
                .map(|n| n.offset)
                .unwrap_or(effective.len());
            let raw_md = effective[m.offset..end.max(m.offset)].to_string();
            let content_start = m.first_line_end.min(end).max(m.offset);
            let content = effective[content_start..end.max(content_start)]
                .trim()
                .to_string();
            headings.push(HeadingInfo {
                level: m.level,
                text: m.title.clone(),
                slug: m.slug.clone(),
                line: m.line,
                offset: m.offset,
                index: idx,
                content,
                raw_md,
            });
        }

        // build flat sections then assemble the tree
        let mut flat: Vec<Section> = Vec::new();
        for m in &metas {
            let raw = extract_raw(&effective, m.first_line_end);
            let raw_lines = split_lines(&raw);
            let mut raw_refs: RefMap = HashMap::new();
            let raw_opts = BlockParseOptions {
                allow_metadata: false,
            };
            let raw_nodes = parse_nodes(&raw_lines, &mut raw_refs, &raw_opts);
            let blocks = convert_nodes(&raw_nodes, &raw_refs, m.doc_line);
            flat.push(Section {
                level: m.level,
                title: m.title.clone(),
                slug: m.slug.clone(),
                pos_line: m.doc_line,
                pos_offset: m.doc_offset,
                raw,
                blocks,
                children: vec![],
            });
        }
        let mut queue: std::collections::VecDeque<Section> = flat.into_iter().collect();
        fn build_level(
            queue: &mut std::collections::VecDeque<Section>,
            parent_level: usize,
        ) -> Vec<Section> {
            let mut siblings = Vec::new();
            while let Some(front) = queue.front() {
                if front.level <= parent_level {
                    break;
                }
                let mut sec = queue.pop_front().unwrap();
                let lvl = sec.level;
                sec.children = build_level(queue, lvl);
                siblings.push(sec);
            }
            siblings
        }
        let sections = build_level(&mut queue, 0);

        Document {
            source: effective,
            sections,
            headings,
            global_nodes: nodes,
            global_refs: refs,
        }
    }

    pub fn heading_count(&self) -> usize {
        self.headings.len()
    }
    pub fn word_count(&self) -> usize {
        count_words(&self.source)
    }
    pub fn max_depth(&self) -> usize {
        fn depth(secs: &[Section]) -> usize {
            if secs.is_empty() {
                return 0;
            }
            1 + secs.iter().map(|s| depth(&s.children)).max().unwrap_or(0)
        }
        depth(&self.sections)
    }

    pub fn flat_sections<'a>(&'a self, out: &mut Vec<&'a Section>) {
        fn walk<'a>(secs: &'a [Section], out: &mut Vec<&'a Section>) {
            for s in secs {
                out.push(s);
                walk(&s.children, out);
            }
        }
        walk(&self.sections, out);
    }

    pub fn to_json(&self) -> JsonValue {
        fn section_json(s: &Section) -> JsonValue {
            let mut map = Map::new();
            map.insert("id".into(), json!(s.slug));
            map.insert("level".into(), json!(s.level));
            map.insert("title".into(), json!(s.title));
            map.insert("slug".into(), json!(s.slug));
            map.insert(
                "position".into(),
                json!({"line": s.pos_line, "offset": s.pos_offset}),
            );
            let blocks: Vec<JsonValue> = s.blocks.iter().map(|b| b.to_json()).collect();
            map.insert(
                "content".into(),
                json!({"raw": s.raw, "blocks": blocks}),
            );
            let children: Vec<JsonValue> = s.children.iter().map(section_json).collect();
            map.insert("children".into(), JsonValue::Array(children));
            JsonValue::Object(map)
        }
        let sections: Vec<JsonValue> = self.sections.iter().map(section_json).collect();
        json!({
            "document": {
                "metadata": {
                    "source": JsonValue::Null,
                    "headingCount": self.heading_count(),
                    "maxDepth": self.max_depth(),
                    "wordCount": self.word_count()
                },
                "sections": sections
            }
        })
    }

    /// Section extraction for -s. None = not found. Some("") when the
    /// heading exists but its marker cannot be located in the source.
    pub fn extract_section(&self, name: &str) -> Option<String> {
        let target_idx = self
            .headings
            .iter()
            .position(|h| h.text.to_lowercase() == name.to_lowercase())?;
        let target = &self.headings[target_idx];
        let marker = format!("{} {}", "#".repeat(target.level), target.text);
        let Some(start) = self.source.find(&marker) else {
            return Some(String::new());
        };
        let end = match self.headings[target_idx + 1..]
            .iter()
            .find(|h| h.level <= target.level)
        {
            Some(next) => {
                let next_marker = format!("{} {}", "#".repeat(next.level), next.text);
                match self.source[start + 1..].find(&next_marker) {
                    Some(rel) => start + 1 + rel,
                    None => self.source.len(),
                }
            }
            None => self.source.len(),
        };
        Some(self.source[start..end].trim().to_string())
    }
}

/// Render the heading tree for --tree (CLI).
pub fn render_cli_tree(sections: &[Section]) -> String {
    let mut out = String::new();
    fn walk(secs: &[Section], prefix: &str, out: &mut String) {
        for (i, s) in secs.iter().enumerate() {
            let last = i + 1 == secs.len();
            let branch = if last { "└──" } else { "├──" };
            out.push_str(&format!(
                "{prefix}{branch}{} {}\n",
                "#".repeat(s.level),
                s.title
            ));
            let child_prefix = format!("{prefix}{}", if last { "   " } else { "│  " });
            walk(&s.children, &child_prefix, out);
        }
    }
    walk(sections, "", &mut out);
    out
}
