#[derive(Clone, Debug)]
pub struct QueryError {
    pub message: String,
    pub span: Option<(usize, usize)>,
    pub label: Option<String>,
    pub help: Option<String>,
    pub source: String,
    /// unknown-function style error (help block without diagnostic span)
    pub suggestion_style: bool,
}

impl QueryError {
    fn simple(message: String, source: &str) -> Self {
        QueryError {
            message,
            span: None,
            label: None,
            help: None,
            source: source.to_string(),
            suggestion_style: false,
        }
    }
    fn spanned(
        message: String,
        span: (usize, usize),
        label: &str,
        help: Option<String>,
        source: &str,
    ) -> Self {
        QueryError {
            message,
            span: Some(span),
            label: Some(label.to_string()),
            help,
            source: source.to_string(),
            suggestion_style: false,
        }
    }
    pub fn render(&self) -> String {
        let mut out = String::new();
        out.push_str(&format!("error: {}\n", self.message));
        if let Some((start, end)) = self.span {
            if !self.source.is_empty() {
                out.push_str("  --> query\n");
                out.push_str("  |\n");
                out.push_str(&format!("1 | {}\n", self.source));
                let caret_start = self.source[..start.min(self.source.len())].chars().count();
                let caret_len = self.source
                    [start.min(self.source.len())..end.min(self.source.len())]
                    .chars()
                    .count()
                    .max(1);
                out.push_str(&" ".repeat(4 + caret_start));
                out.push_str(&"^".repeat(caret_len));
                if let Some(label) = &self.label {
                    out.push_str(&format!("  {label}\n"));
                } else {
                    out.push('\n');
                }
                if let Some(help) = &self.help {
                    out.push_str(&format!("  = help: {help}\n"));
                }
            }
        } else if self.suggestion_style {
            if let Some(help) = &self.help {
                out.push_str("  |\n");
                out.push_str(&format!("  = help: {help}\n"));
            }
        }
        out.push('\n');
        out
    }
}

type QResult<T> = Result<T, QueryError>;

// ---------------- lexer ----------------

#[derive(Clone, Debug, PartialEq)]
enum TokenKind {
    Dot,
    Pipe,
    Comma,
    Colon,
    LBracket,
    RBracket,
    LParen,
    RParen,
    LBrace,
    RBrace,
    Gt,
    GtGt,
    Lt,
    GtEq,
    LtEq,
    EqEq,
    NotEq,
    Plus,
    Minus,
    Star,
    Slash,
    SlashSlash,
    Percent,
    Question,
    Ident(String),
    Number(f64),
    Str(String),
    True,
    False,
    Null,
    And,
    Or,
    Not,
    Eof,
}

impl TokenKind {
    fn describe(&self) -> String {
        match self {
            TokenKind::Ident(_) => "identifier".into(),
            TokenKind::Number(_) => "number".into(),
            TokenKind::Str(_) => "string".into(),
            TokenKind::Eof => "end of input".into(),
            TokenKind::Dot => "'.'".into(),
            TokenKind::Pipe => "'|'".into(),
            TokenKind::Comma => "','".into(),
            TokenKind::Colon => "':'".into(),
            TokenKind::LBracket => "'['".into(),
            TokenKind::RBracket => "']'".into(),
            TokenKind::LParen => "'('".into(),
            TokenKind::RParen => "')'".into(),
            TokenKind::LBrace => "'{'".into(),
            TokenKind::RBrace => "'}'".into(),
            TokenKind::Gt => "'>'".into(),
            TokenKind::GtGt => "'>>'".into(),
            TokenKind::Lt => "'<'".into(),
            TokenKind::GtEq => "'>='".into(),
            TokenKind::LtEq => "'<='".into(),
            TokenKind::EqEq => "'=='".into(),
            TokenKind::NotEq => "'!='".into(),
            TokenKind::Plus => "'+'".into(),
            TokenKind::Minus => "'-'".into(),
            TokenKind::Star => "'*'".into(),
            TokenKind::Slash => "'/'".into(),
            TokenKind::SlashSlash => "'//'".into(),
            TokenKind::Percent => "'%'".into(),
            TokenKind::Question => "'?'".into(),
            TokenKind::True => "'true'".into(),
            TokenKind::False => "'false'".into(),
            TokenKind::Null => "'null'".into(),
            TokenKind::And => "'and'".into(),
            TokenKind::Or => "'or'".into(),
            TokenKind::Not => "'not'".into(),
        }
    }
}

#[derive(Clone, Debug)]
struct Token {
    kind: TokenKind,
    start: usize,
    end: usize,
}

fn lex(source: &str) -> QResult<Vec<Token>> {
    let bytes: Vec<(usize, char)> = source.char_indices().collect();
    let mut tokens = Vec::new();
    let mut i = 0usize; // index into bytes vec
    let byte_pos = |i: usize| -> usize {
        if i < bytes.len() {
            bytes[i].0
        } else {
            source.len()
        }
    };
    while i < bytes.len() {
        let (bstart, c) = bytes[i];
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        let start = bstart;
        let mut push = |tokens: &mut Vec<Token>, kind: TokenKind, endb: usize| {
            tokens.push(Token {
                kind,
                start,
                end: endb,
            });
        };
        match c {
            '.' => {
                push(&mut tokens, TokenKind::Dot, start + 1);
                i += 1;
            }
            '|' => {
                push(&mut tokens, TokenKind::Pipe, start + 1);
                i += 1;
            }
            ',' => {
                push(&mut tokens, TokenKind::Comma, start + 1);
                i += 1;
            }
            ':' => {
                push(&mut tokens, TokenKind::Colon, start + 1);
                i += 1;
            }
            '[' => {
                push(&mut tokens, TokenKind::LBracket, start + 1);
                i += 1;
            }
            ']' => {
                push(&mut tokens, TokenKind::RBracket, start + 1);
                i += 1;
            }
            '(' => {
                push(&mut tokens, TokenKind::LParen, start + 1);
                i += 1;
            }
            ')' => {
                push(&mut tokens, TokenKind::RParen, start + 1);
                i += 1;
            }
            '{' => {
                push(&mut tokens, TokenKind::LBrace, start + 1);
                i += 1;
            }
            '}' => {
                push(&mut tokens, TokenKind::RBrace, start + 1);
                i += 1;
            }
            '+' => {
                push(&mut tokens, TokenKind::Plus, start + 1);
                i += 1;
            }
            '*' => {
                push(&mut tokens, TokenKind::Star, start + 1);
                i += 1;
            }
            '%' => {
                push(&mut tokens, TokenKind::Percent, start + 1);
                i += 1;
            }
            '?' => {
                push(&mut tokens, TokenKind::Question, start + 1);
                i += 1;
            }
            '>' => {
                if i + 1 < bytes.len() && bytes[i + 1].1 == '>' {
                    push(&mut tokens, TokenKind::GtGt, start + 2);
                    i += 2;
                } else if i + 1 < bytes.len() && bytes[i + 1].1 == '=' {
                    push(&mut tokens, TokenKind::GtEq, start + 2);
                    i += 2;
                } else {
                    push(&mut tokens, TokenKind::Gt, start + 1);
                    i += 1;
                }
            }
            '<' => {
                if i + 1 < bytes.len() && bytes[i + 1].1 == '=' {
                    push(&mut tokens, TokenKind::LtEq, start + 2);
                    i += 2;
                } else {
                    push(&mut tokens, TokenKind::Lt, start + 1);
                    i += 1;
                }
            }
            '/' => {
                if i + 1 < bytes.len() && bytes[i + 1].1 == '/' {
                    push(&mut tokens, TokenKind::SlashSlash, start + 2);
                    i += 2;
                } else {
                    push(&mut tokens, TokenKind::Slash, start + 1);
                    i += 1;
                }
            }
            '=' => {
                if i + 1 < bytes.len() && bytes[i + 1].1 == '=' {
                    push(&mut tokens, TokenKind::EqEq, start + 2);
                    i += 2;
                } else {
                    return Err(QueryError::spanned(
                        "Unexpected character '='".into(),
                        (start, start + 1),
                        "unexpected character",
                        Some("Use '==' for equality comparison".into()),
                        source,
                    ));
                }
            }
            '!' => {
                if i + 1 < bytes.len() && bytes[i + 1].1 == '=' {
                    push(&mut tokens, TokenKind::NotEq, start + 2);
                    i += 2;
                } else {
                    return Err(QueryError::spanned(
                        "Unexpected character '!'".into(),
                        (start, start + 1),
                        "unexpected character",
                        Some("Use 'not' for negation or '!=' for inequality".into()),
                        source,
                    ));
                }
            }
            '-' => {
                if i + 1 < bytes.len() && bytes[i + 1].1.is_ascii_digit() {
                    // negative number
                    let (tok, ni) = lex_number(source, &bytes, i);
                    tokens.push(tok);
                    i = ni;
                } else {
                    push(&mut tokens, TokenKind::Minus, start + 1);
                    i += 1;
                }
            }
            '"' | '\'' => {
                let quote = c;
                let mut out = String::new();
                let mut j = i + 1;
                let mut closed = false;
                while j < bytes.len() {
                    let (bp, ch) = bytes[j];
                    if ch == quote {
                        closed = true;
                        j += 1;
                        break;
                    }
                    if ch == '\\' {
                        if j + 1 >= bytes.len() {
                            j += 1;
                            break;
                        }
                        let (ep, esc) = bytes[j + 1];
                        let decoded = match esc {
                            'n' => '\n',
                            't' => '\t',
                            'r' => '\r',
                            '\\' => '\\',
                            '\'' => '\'',
                            '"' => '"',
                            _ => {
                                return Err(QueryError::spanned(
                                    format!("Invalid escape sequence '\\{esc}'"),
                                    (ep, ep + esc.len_utf8()),
                                    "invalid escape",
                                    None,
                                    source,
                                ));
                            }
                        };
                        let _ = bp;
                        out.push(decoded);
                        j += 2;
                        continue;
                    }
                    out.push(ch);
                    j += 1;
                }
                if !closed {
                    return Err(QueryError::spanned(
                        "Unterminated string literal".into(),
                        (start, source.len()),
                        "string not closed",
                        None,
                        source,
                    ));
                }
                push(&mut tokens, TokenKind::Str(out), byte_pos(j));
                i = j;
            }
            _ if c.is_ascii_digit() => {
                let (tok, ni) = lex_number(source, &bytes, i);
                tokens.push(tok);
                i = ni;
            }
            _ if c.is_alphabetic() || c == '_' => {
                let mut j = i;
                while j < bytes.len() && (bytes[j].1.is_alphanumeric() || bytes[j].1 == '_') {
                    j += 1;
                }
                let name = &source[start..byte_pos(j)];
                let kind = match name {
                    "true" => TokenKind::True,
                    "false" => TokenKind::False,
                    "null" => TokenKind::Null,
                    "and" => TokenKind::And,
                    "or" => TokenKind::Or,
                    "not" => TokenKind::Not,
                    _ => TokenKind::Ident(name.to_string()),
                };
                push(&mut tokens, kind, byte_pos(j));
                i = j;
            }
            _ => {
                return Err(QueryError::spanned(
                    format!("Unexpected character '{c}'"),
                    (start, start + c.len_utf8()),
                    "unexpected character",
                    None,
                    source,
                ));
            }
        }
    }
    tokens.push(Token {
        kind: TokenKind::Eof,
        start: source.len(),
        end: source.len(),
    });
    Ok(tokens)
}

fn lex_number(
    source: &str,
    bytes: &[(usize, char)],
    mut i: usize,
) -> (Token, usize) {
    let start = bytes[i].0;
    if bytes[i].1 == '-' {
        i += 1;
    }
    while i < bytes.len() && (bytes[i].1.is_ascii_digit() || bytes[i].1 == '.') {
        i += 1;
    }
    if i < bytes.len() && (bytes[i].1 == 'e' || bytes[i].1 == 'E') {
        i += 1;
        if i < bytes.len() && (bytes[i].1 == '+' || bytes[i].1 == '-') {
            i += 1;
        }
        while i < bytes.len() && (bytes[i].1.is_ascii_digit() || bytes[i].1 == '.') {
