// ---------------- parser ----------------

#[derive(Clone, Debug, PartialEq)]
enum SelectorKind {
    Headings(Option<usize>),
    Code,
    Link,
    Image,
    Table,
    List,
    Blockquote,
    Paragraph,
}

#[derive(Clone, Debug)]
enum Filter {
    All,
    Index(f64),
    Slice(Option<f64>, Option<f64>),
    Text(String),
    Exact(String),
}

#[derive(Clone, Debug)]
enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
    Alt,
}

#[derive(Clone, Debug)]
enum Expr {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Root,
    Selector {
        kind: SelectorKind,
        filter: Option<Filter>,
    },
    FieldAccess {
        object: Box<Expr>,
        field: String,
    },
    FunctionCall {
        name: String,
        args: Vec<Expr>,
    },
    Pipe(Box<Expr>, Box<Expr>),
    Multi(Vec<Expr>),
    ArrayConstruct(Vec<Expr>),
    ObjectConstruct(Vec<(String, Expr)>),
    Binary {
        op: BinOp,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    Hierarchy {
        left: Box<Expr>,
        right: Box<Expr>,
        descendant: bool,
    },
    Not(Box<Expr>),
    Neg(Box<Expr>),
    Index {
        object: Box<Expr>,
    },
    Paren(Box<Expr>),
}

struct Parser<'a> {
    tokens: Vec<Token>,
    pos: usize,
    source: &'a str,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> &Token {
        &self.tokens[self.pos]
    }
    fn peek2(&self) -> &Token {
        let idx = (self.pos + 1).min(self.tokens.len() - 1);
        &self.tokens[idx]
    }
    fn advance(&mut self) -> Token {
        let t = self.tokens[self.pos].clone();
        if self.pos + 1 < self.tokens.len() {
            self.pos += 1;
        }
        t
    }
    fn err_expected(&self, what: &str) -> QueryError {
        let t = self.peek();
        QueryError::spanned(
            format!("Expected {what}, found {}", t.kind.describe()),
            (t.start, t.end),
            "unexpected token",
            None,
            self.source,
        )
    }
    fn expect(&mut self, kind: &TokenKind, what: &str) -> QResult<Token> {
        if &self.peek().kind == kind {
            Ok(self.advance())
        } else {
            Err(self.err_expected(what))
        }
    }

    fn parse_query(&mut self) -> QResult<Expr> {
        let mut exprs = vec![self.parse_pipe()?];
        while self.peek().kind == TokenKind::Comma {
            self.advance();
            exprs.push(self.parse_pipe()?);
        }
        if self.peek().kind != TokenKind::Eof {
            return Err(self.err_expected("end of query"));
        }
        if exprs.len() == 1 {
            Ok(exprs.pop().unwrap())
        } else {
            Ok(Expr::Multi(exprs))
        }
    }

    fn parse_pipe(&mut self) -> QResult<Expr> {
        let mut left = self.parse_or()?;
        while self.peek().kind == TokenKind::Pipe {
            self.advance();
            let right = self.parse_or()?;
            left = Expr::Pipe(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_or(&mut self) -> QResult<Expr> {
        let mut left = self.parse_and()?;
        loop {
            let op = match self.peek().kind {
                TokenKind::Or => BinOp::Or,
                TokenKind::SlashSlash => BinOp::Alt,
                _ => break,
            };
            self.advance();
            let right = self.parse_and()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_and(&mut self) -> QResult<Expr> {
        let mut left = self.parse_comparison()?;
        while self.peek().kind == TokenKind::And {
            self.advance();
            let right = self.parse_comparison()?;
            left = Expr::Binary {
                op: BinOp::And,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_comparison(&mut self) -> QResult<Expr> {
        let mut left = self.parse_additive()?;
        loop {
            match self.peek().kind {
                TokenKind::GtGt => {
                    self.advance();
                    let right = self.parse_additive()?;
                    left = Expr::Hierarchy {
                        left: Box::new(left),
                        right: Box::new(right),
                        descendant: true,
                    };
                }
                TokenKind::Gt => {
                    // hierarchy if the RHS starts with '.'
                    if self.peek2().kind == TokenKind::Dot {
                        self.advance();
                        let right = self.parse_additive()?;
                        left = Expr::Hierarchy {
                            left: Box::new(left),
                            right: Box::new(right),
                            descendant: false,
                        };
                    } else {
                        self.advance();
                        let right = self.parse_additive()?;
                        left = Expr::Binary {
                            op: BinOp::Gt,
                            left: Box::new(left),
                            right: Box::new(right),
                        };
                    }
                }
                TokenKind::EqEq
                | TokenKind::NotEq
                | TokenKind::Lt
                | TokenKind::LtEq
                | TokenKind::GtEq => {
                    let op = match self.advance().kind {
                        TokenKind::EqEq => BinOp::Eq,
                        TokenKind::NotEq => BinOp::Ne,
                        TokenKind::Lt => BinOp::Lt,
                        TokenKind::LtEq => BinOp::Le,
                        _ => BinOp::Ge,
                    };
                    let right = self.parse_additive()?;
                    left = Expr::Binary {
                        op,
                        left: Box::new(left),
                        right: Box::new(right),
                    };
                }
                _ => break,
            }
        }
        Ok(left)
    }

    fn parse_additive(&mut self) -> QResult<Expr> {
        let mut left = self.parse_multiplicative()?;
        loop {
            let op = match self.peek().kind {
                TokenKind::Plus => BinOp::Add,
                TokenKind::Minus => BinOp::Sub,
                _ => break,
            };
            self.advance();
            let right = self.parse_multiplicative()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> QResult<Expr> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek().kind {
                TokenKind::Star => BinOp::Mul,
                TokenKind::Slash => BinOp::Div,
                TokenKind::Percent => BinOp::Mod,
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> QResult<Expr> {
        match self.peek().kind {
            TokenKind::Not => {
                self.advance();
                let inner = self.parse_unary()?;
                Ok(Expr::Not(Box::new(inner)))
            }
            TokenKind::Minus => {
                self.advance();
                let inner = self.parse_unary()?;
                Ok(Expr::Neg(Box::new(inner)))
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> QResult<Expr> {
        let (mut expr, mut can_filter) = self.parse_primary()?;
        loop {
            match self.peek().kind {
                TokenKind::Dot => {
                    self.advance();
                    let t = self.peek().clone();
                    match &t.kind {
                        TokenKind::Ident(name) => {
                            let name = name.clone();
                            self.advance();
                            expr = Expr::FieldAccess {
                                object: Box::new(expr),
                                field: name,
                            };
                            can_filter = false;
                        }
                        _ => return Err(self.err_expected("identifier")),
                    }
                }
                TokenKind::LBracket => {
                    if can_filter {
                        if let Expr::Selector { filter, .. } = &mut expr {
                            let f = self.parse_selector_filter()?;
                            *filter = Some(f);
                        }
                        can_filter = false;
                    } else {
                        self.parse_index_bracket()?;
                        expr = Expr::Index {
                            object: Box::new(expr),
                        };
                    }
                }
                _ => break,
            }
        }
        Ok(expr)
    }

    /// Parse a selector filter: cursor is at '['.
    fn parse_selector_filter(&mut self) -> QResult<Filter> {
        let open = self.advance(); // '['
        let f = self.parse_filter_body(true, open.start)?;
        Ok(f)
    }

    /// Parse a regular index bracket (only index/slice allowed).
    fn parse_index_bracket(&mut self) -> QResult<()> {
        let open = self.advance(); // '['
        self.parse_filter_body(false, open.start)?;
        Ok(())
    }

    fn invalid_filter(&self, msg: &str, start: usize, end: usize) -> QueryError {
        QueryError::spanned(
            format!("Invalid filter: {msg}"),
            (start, end),
            "invalid filter",
            None,
            self.source,
        )
    }

    fn parse_filter_body(&mut self, allow_filter: bool, bracket_start: usize) -> QResult<Filter> {
        // empty []
        if self.peek().kind == TokenKind::RBracket {
            self.advance();
            return Ok(Filter::All);
        }
        // slice starting with ':'
        if self.peek().kind == TokenKind::Colon {
            self.advance();
            let endv = match self.peek().kind {
                TokenKind::Number(n) => {
                    self.advance();
                    Some(n)
                }
                _ => None,
            };
            self.expect(&TokenKind::RBracket, "']'")?;
            return Ok(Filter::Slice(None, endv));
        }
        let t = self.peek().clone();
        match &t.kind {
            TokenKind::Number(n) => {
                let n = *n;
                self.advance();
                if self.peek().kind == TokenKind::Colon {
                    self.advance();
                    let endv = match self.peek().kind {
                        TokenKind::Number(m) => {
                            self.advance();
                            Some(m)
                        }
                        _ => None,
                    };
                    self.expect(&TokenKind::RBracket, "']'")?;
                    Ok(Filter::Slice(Some(n), endv))
                } else {
                    self.expect(&TokenKind::RBracket, "']'")?;
                    Ok(Filter::Index(n))
                }
            }
            TokenKind::Ident(name) => {
                let name = name.clone();
                let tok = self.advance();
                if !allow_filter {
                    // span covers the whole bracket content through ']'
                    // find closing bracket end if present
                    let end = if self.peek().kind == TokenKind::RBracket {
                        self.peek().end
                    } else {
                        tok.end
                    };
                    return Err(self.invalid_filter(
                        "expected index, got filter",
                        bracket_start,
                        end,
                    ));
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Filter::Text(name))
            }
            TokenKind::Str(s) => {
                let s = s.clone();
                let tok = self.advance();
                if !allow_filter {
                    let end = if self.peek().kind == TokenKind::RBracket {
                        self.peek().end
                    } else {
                        tok.end
                    };
                    return Err(self.invalid_filter(
                        "expected index, got filter",
                        bracket_start,
                        end,
                    ));
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Filter::Exact(s))
            }
            TokenKind::Minus => {
                // '-' not followed by a digit (those lex as negative numbers)
                let tok = self.advance();
                let at = self.peek();
                Err(self.invalid_filter(
                    "expected filter pattern or index",
                    at.start,
                    at.start,
                ))
                .also(|_| {
                    let _ = tok;
                })
            }
            TokenKind::Eof => Err(self.invalid_filter(
                "expected filter pattern or index",
                t.start,
                t.start,
            )),
            TokenKind::Dot => Err(self.invalid_filter(
                "expected filter pattern or index",
                t.start,
                t.start,
            )),
            _ => Err(self.invalid_filter(
                "expected filter pattern or index",
                t.start,
                t.end,
            )),
        }
    }

    fn parse_primary(&mut self) -> QResult<(Expr, bool)> {
        let t = self.peek().clone();
        match &t.kind {
            TokenKind::Number(n) => {
                let n = *n;
                self.advance();
                Ok((Expr::Number(n), false))
            }
            TokenKind::Str(s) => {
                let s = s.clone();
                self.advance();
                Ok((Expr::Str(s), false))
            }
            TokenKind::True => {
                self.advance();
                Ok((Expr::Bool(true), false))
            }
            TokenKind::False => {
                self.advance();
                Ok((Expr::Bool(false), false))
            }
            TokenKind::Null => {
                self.advance();
                Ok((Expr::Null, false))
            }
            TokenKind::Dot => {
                self.advance();
                let next = self.peek().clone();
                match &next.kind {
                    TokenKind::Ident(name) => {
                        let name = name.clone();
                        self.advance();
                        if let Some(kind) = selector_kind(&name) {
                            Ok((
                                Expr::Selector {
                                    kind,
                                    filter: None,
                                },
                                true,
                            ))
                        } else {
                            Ok((
                                Expr::FieldAccess {
                                    object: Box::new(Expr::Root),
                                    field: name,
                                },
                                false,
                            ))
                        }
                    }
                    TokenKind::Eof
                    | TokenKind::Pipe
                    | TokenKind::Comma
                    | TokenKind::RParen
                    | TokenKind::RBracket
                    | TokenKind::Gt
                    | TokenKind::GtGt => Ok((Expr::Root, false)),
                    _ => Err(self.err_expected("identifier")),
                }
            }
            TokenKind::Ident(name) => {
                let name = name.clone();
                self.advance();
                let mut args = Vec::new();
                if self.peek().kind == TokenKind::LParen {
                    self.advance();
                    if self.peek().kind != TokenKind::RParen {
                        loop {
                            args.push(self.parse_pipe()?);
                            if self.peek().kind == TokenKind::Comma {
                                self.advance();
                                continue;
                            }
                            break;
                        }
                    }
                    self.expect(&TokenKind::RParen, "')'")?;
                }
                Ok((
                    Expr::FunctionCall { name, args },
                    false,
                ))
            }
            TokenKind::LParen => {
                self.advance();
                let inner = self.parse_pipe()?;
                self.expect(&TokenKind::RParen, "')'")?;
                Ok((Expr::Paren(Box::new(inner)), false))
            }
            TokenKind::LBracket => {
                self.advance();
                let mut elems = Vec::new();
                if self.peek().kind != TokenKind::RBracket {
                    loop {
                        elems.push(self.parse_pipe()?);
                        if self.peek().kind == TokenKind::Comma {
                            self.advance();
                            continue;
                        }
                        break;
                    }
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok((Expr::ArrayConstruct(elems), false))
            }
            TokenKind::LBrace => {
                self.advance();
                let mut pairs = Vec::new();
                if self.peek().kind != TokenKind::RBrace {
                    loop {
                        let kt = self.peek().clone();
                        let key = match &kt.kind {
                            TokenKind::Ident(n) => {
                                let n = n.clone();
                                self.advance();
                                n
                            }
                            TokenKind::Str(s) => {
                                let s = s.clone();
                                self.advance();
                                s
                            }
                            _ => {
                                return Err(self.err_expected("one of identifier, string"));
                            }
                        };
                        self.expect(&TokenKind::Colon, "':'")?;
                        let value = self.parse_pipe()?;
                        pairs.push((key, value));
                        if self.peek().kind == TokenKind::Comma {
                            self.advance();
                            continue;
                        }
                        break;
                    }
                }
                self.expect(&TokenKind::RBrace, "'}'")?;
                Ok((Expr::ObjectConstruct(pairs), false))
            }
            _ => Err(self.err_expected("expression")),
        }
    }
}

trait Also {
    fn also<F: FnOnce(&Self)>(self, f: F) -> Self
    where
        Self: Sized,
    {
        f(&self);
        self
    }
}
impl Also for QueryError {}

fn selector_kind(name: &str) -> Option<SelectorKind> {
    Some(match name {
        "h" | "heading" | "headings" | "header" | "headers" => SelectorKind::Headings(None),
        "h1" => SelectorKind::Headings(Some(1)),
        "h2" => SelectorKind::Headings(Some(2)),
        "h3" => SelectorKind::Headings(Some(3)),
        "h4" => SelectorKind::Headings(Some(4)),
        "h5" => SelectorKind::Headings(Some(5)),
        "h6" => SelectorKind::Headings(Some(6)),
        "code" | "codeblock" | "codeblocks" | "pre" => SelectorKind::Code,
        "link" | "links" | "a" => SelectorKind::Link,
        "img" | "image" | "images" => SelectorKind::Image,
        "table" | "tables" => SelectorKind::Table,
        "list" | "lists" | "ul" | "ol" => SelectorKind::List,
        "blockquote" | "blockquotes" | "quote" | "quotes" => SelectorKind::Blockquote,
        "p" | "para" | "paragraph" | "paragraphs" => SelectorKind::Paragraph,
        _ => return None,
    })
}

pub fn parse_query_str(source: &str) -> QResult<Expr> {
    let tokens = lex(source)?;
    let mut parser = Parser {
        tokens,
        pos: 0,
        source,
    };
    parser.parse_query()
}
