pub fn values_equal(a: &Value, b: &Value) -> bool {
    if let (Value::String(_), _) | (_, Value::String(_)) = (a, b) {
        return a.to_text() == b.to_text();
    }
    a == b
}

pub fn compare_values(a: &Value, b: &Value) -> Option<Ordering> {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.partial_cmp(y),
        (Value::String(x), Value::String(y)) => Some(x.cmp(y)),
        _ => None,
    }
}

fn object_insert(pairs: &mut Vec<(String, Value)>, key: String, value: Value) {
    if let Some(existing) = pairs.iter_mut().find(|(k, _)| *k == key) {
        existing.1 = value;
    } else {
        pairs.push((key, value));
    }
}

fn collapse_stream(v: Vec<Value>) -> Value {
    match v.len() {
        0 => Value::Null,
        1 => v.into_iter().next().unwrap(),
        _ => Value::Array(v),
    }
}

fn first_or_null(v: &[Value]) -> Value {
