fn link_type_of(url: &str) -> LinkType {
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") {
        LinkType::External
    } else if url.starts_with('#') {
        LinkType::Anchor
    } else {
        LinkType::Relative
    }
}

fn collect_links_from_events(
    events: &[InlineEvent],
    out: &mut Vec<Value>,
    source: &str,
    cursor: &mut usize,
) {
    let mut i = 0;
    while i < events.len() {
        if let InlineEvent::StartLink { dest, .. } = &events[i] {
            let mut text = String::new();
            let mut j = i + 1;
            let mut depth = 1;
            while j < events.len() {
                match &events[j] {
                    InlineEvent::StartLink { .. } => depth += 1,
                    InlineEvent::EndLink => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    InlineEvent::Text(t) => text.push_str(t),
                    InlineEvent::Code(v) => text.push_str(v),
                    InlineEvent::SoftBreak => text.push(' '),
                    InlineEvent::HardBreak => text.push('\n'),
                    _ => {}
                }
                j += 1;
            }
            // find an approximate source offset for this link
            let offset = {
                let search_from = (*cursor).min(source.len());
                let is_auto = text == *dest || dest.strip_prefix("mailto:") == Some(&text);
                let needle = if is_auto { "<" } else { "[" };
                match source[search_from..].find(needle) {
                    Some(rel) => {
                        let at = search_from + rel;
                        *cursor = at + 1;
                        at
                    }
                    None => *cursor,
                }
            };
            out.push(Value::Link(LinkValue {
                text,
                url: dest.clone(),
                link_type: link_type_of(dest),
                offset,
            }));
            i = j + 1;
        } else {
            i += 1;
        }
    }
}

