            heading_title_from_events(&events)
        }
        _ => String::new(),
    };
    ListItemValue {
        content,
        checked: item.checked,
    }
}

fn extract_from_nodes(
    nodes: &[Node],
    doc: &Document,
    codes: &mut Vec<Value>,
    links: &mut Vec<Value>,
    tables: &mut Vec<Value>,
    lists: &mut Vec<Value>,
    cursor: &mut usize,
) {
    for node in nodes {
        match node {
            Node::Heading(h) => {
                let events = parse_inline_events(&h.inline_src, &doc.global_refs);
                collect_links_from_events(&events, links, &doc.source, cursor);
            }
            Node::Paragraph { text } => {
                let events = parse_inline_events(text, &doc.global_refs);
                collect_links_from_events(&events, links, &doc.source, cursor);
            }
            Node::Code { language, content } => {
                codes.push(Value::Code(CodeValue {
                    language: language.clone(),
                    content: content.clone(),
                    start_line: 1,
                    end_line: 1,
                }));
            }
            Node::Table {
                headers,
                alignments,
                rows,
            } => {
                let conv_headers: Vec<String> = headers
                    .iter()
                    .map(|h| {
                        let ev = parse_inline_events(h, &doc.global_refs);
                        collect_links_from_events(&ev, links, &doc.source, cursor);
                        convert_inlines(&ev, false).1
                    })
                    .collect();
                let conv_rows: Vec<Vec<String>> = rows
                    .iter()
                    .map(|r| {
                        r.iter()
                            .map(|c| {
                                let ev = parse_inline_events(c, &doc.global_refs);
                                collect_links_from_events(&ev, links, &doc.source, cursor);
                                convert_inlines(&ev, false).1
                            })
                            .collect()
                    })
                    .collect();
                tables.push(Value::Table(TableValue {
                    headers: conv_headers,
                    rows: conv_rows,
                    alignments: alignments.clone(),
                }));
            }
            Node::List { ordered, items } => {
                lists.push(Value::List(ListValue {
                    ordered: *ordered,
                    items: items.iter().map(|it| list_item_value(it, doc)).collect(),
                }));
                for item in items {
                    extract_from_nodes(&item.blocks, doc, codes, links, tables, lists, cursor);
                }
            }
            Node::BlockQuote(children) => {
                extract_from_nodes(children, doc, codes, links, tables, lists, cursor);
            }
            Node::HorizontalRule => {}
        }
    }
}

pub fn extract_elements(doc: &Document) -> Elements {
    let headings: Vec<Value> = doc
        .headings
        .iter()
        .map(|h| {
            Value::Heading(HeadingValue {
                level: h.level,
                text: h.text.clone(),
                offset: h.offset,
                line: h.line,
                content: h.content.clone(),
                raw_md: h.raw_md.clone(),
                index: h.index,
            })
        })
        .collect();
    let mut codes = Vec::new();
    let mut links = Vec::new();
    let mut tables = Vec::new();
    let mut lists = Vec::new();
    let mut cursor = 0usize;
    extract_from_nodes(
        &doc.global_nodes,
        doc,
        &mut codes,
        &mut links,
        &mut tables,
        &mut lists,
        &mut cursor,
    );
    Elements {
        headings,
        codes,
        links,
        tables,
        lists,
    }
}
