// ---------------- values ----------------

#[derive(Clone, Debug, PartialEq)]
pub struct HeadingValue {
    pub level: usize,
    pub text: String,
    pub offset: usize,
    pub line: usize,
    pub content: String,
    pub raw_md: String,
    pub index: usize,
}
#[derive(Clone, Debug, PartialEq)]
pub struct CodeValue {
    pub language: Option<String>,
    pub content: String,
    pub start_line: usize,
    pub end_line: usize,
}
#[derive(Clone, Debug, PartialEq)]
pub enum LinkType {
    External,
    Anchor,
    Relative,
}
impl LinkType {
    pub fn as_str(&self) -> &'static str {
        match self {
            LinkType::External => "external",
            LinkType::Anchor => "anchor",
            LinkType::Relative => "relative",
        }
    }
}
#[derive(Clone, Debug, PartialEq)]
pub struct LinkValue {
    pub text: String,
    pub url: String,
    pub link_type: LinkType,
    pub offset: usize,
}
#[derive(Clone, Debug, PartialEq)]
pub struct ImageValue {
    pub alt: String,
    pub src: String,
}
#[derive(Clone, Debug, PartialEq)]
pub struct TableValue {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<String>>,
    pub alignments: Vec<String>,
}
#[derive(Clone, Debug, PartialEq)]
pub struct ListItemValue {
    pub content: String,
    pub checked: Option<bool>,
}
#[derive(Clone, Debug, PartialEq)]
pub struct ListValue {
    pub ordered: bool,
    pub items: Vec<ListItemValue>,
}
#[derive(Clone, Debug, PartialEq)]
pub struct DocumentValue {
    pub content: String,
    pub heading_count: usize,
    pub word_count: usize,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
    Document(DocumentValue),
    Heading(HeadingValue),
    Code(CodeValue),
    Link(LinkValue),
    Image(ImageValue),
    Table(TableValue),
    List(ListValue),
    BlockQuote(String),
}

pub fn format_number(n: f64) -> String {
    if n.is_nan() {
        return "NaN".to_string();
    }
    if n.is_infinite() {
        return if n > 0.0 { "inf".into() } else { "-inf".into() };
    }
    if n.fract() == 0.0 {
        format!("{n:.0}")
    } else {
        format!("{n}")
    }
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Null => "null",
            Value::Bool(_) => "boolean",
            Value::Number(_) => "number",
            Value::String(_) => "string",
            Value::Array(_) => "array",
            Value::Object(_) => "object",
            Value::Document(_) => "document",
            Value::Heading(_) => "heading",
            Value::Code(_) => "code",
            Value::Link(_) => "link",
            Value::Image(_) => "image",
            Value::Table(_) => "table",
            Value::List(_) => "list",
            Value::BlockQuote(_) => "blockquote",
        }
    }

    pub fn to_text(&self) -> String {
        match self {
            Value::Null => String::new(),
            Value::Bool(b) => b.to_string(),
            Value::Number(n) => format_number(*n),
            Value::String(s) => s.clone(),
            Value::Array(items) => items
                .iter()
                .map(|v| v.to_text())
                .collect::<Vec<_>>()
                .join("\n"),
            Value::Object(_) => {
                serde_json::to_string(&self.to_json()).unwrap_or_default()
            }
            Value::Document(d) => d.content.clone(),
            Value::Heading(h) => h.text.clone(),
            Value::Code(c) => c.content.clone(),
            Value::Link(l) => l.text.clone(),
            Value::Image(im) => im.alt.clone(),
            Value::Table(t) => format!("Table({}x{})", t.headers.len(), t.rows.len()),
            Value::List(l) => l
                .items
                .iter()
                .map(|i| i.content.clone())
                .collect::<Vec<_>>()
                .join("\n"),
            Value::BlockQuote(c) => c.clone(),
        }
    }

    pub fn to_plain(&self) -> String {
        match self {
            Value::Document(d) => {
                format!("Document: {} headings, {} words", d.heading_count, d.word_count)
            }
            Value::Heading(h) => format!("{} {}", "#".repeat(h.level), h.text),
            Value::Code(c) => {
                format!("```{}\n{}\n```", c.language.clone().unwrap_or_default(), c.content)
            }
            Value::Link(l) => format!("[{}]({})", l.text, l.url),
            Value::Image(im) => format!("![{}]({})", im.alt, im.src),
            Value::Table(t) => {
                let mut out = String::new();
                out.push_str(&format!("| {} |\n", t.headers.join(" | ")));
                let seps: Vec<&str> = t.headers.iter().map(|_| "---").collect();
                out.push_str(&format!("| {} |", seps.join(" | ")));
                for row in &t.rows {
                    out.push_str(&format!("\n| {} |", row.join(" | ")));
                }
                out
            }
            Value::List(l) => {
                let mut lines = Vec::new();
                for (i, item) in l.items.iter().enumerate() {
                    if l.ordered {
                        lines.push(format!("{}. {}", i + 1, item.content));
                    } else {
                        match item.checked {
                            Some(true) => lines.push(format!("- [x] {}", item.content)),
                            Some(false) => lines.push(format!("- [ ] {}", item.content)),
                            None => lines.push(format!("- {}", item.content)),
                        }
                    }
                }
                lines.join("\n")
            }
            Value::Array(items) => items
                .iter()
                .map(|v| v.to_plain())
                .collect::<Vec<_>>()
                .join("\n"),
            Value::Object(pairs) => pairs
                .iter()
                .map(|(k, v)| format!("{k}: {}", v.to_plain()))
                .collect::<Vec<_>>()
                .join("\n"),
            _ => self.to_text(),
        }
    }

    pub fn to_md(&self) -> String {
        match self {
            Value::Heading(h) => h.raw_md.clone(),
            Value::Code(_) | Value::Link(_) | Value::Image(_) | Value::Table(_) | Value::List(_) => {
                self.to_plain()
            }
            _ => self.to_plain(),
        }
    }

    pub fn to_json(&self) -> JsonValue {
        match self {
            Value::Null => JsonValue::Null,
            Value::Bool(b) => json!(*b),
            Value::Number(n) => serde_json::Number::from_f64(*n)
                .map(JsonValue::Number)
                .unwrap_or(JsonValue::Null),
            Value::String(s) => json!(s),
            Value::Array(items) => {
                JsonValue::Array(items.iter().map(|v| v.to_json()).collect())
            }
            Value::Object(pairs) => {
                let mut map = serde_json::Map::new();
                for (k, v) in pairs {
                    map.insert(k.clone(), v.to_json());
                }
                JsonValue::Object(map)
            }
            Value::Document(d) => json!({
                "type": "document",
                "heading_count": d.heading_count,
                "word_count": d.word_count
            }),
            Value::Heading(h) => json!({
                "type": "heading",
                "level": h.level,
                "text": h.text,
                "line": h.line
            }),
            Value::Code(c) => json!({
                "type": "code",
                "language": c.language,
                "content": c.content,
                "start_line": c.start_line,
                "end_line": c.end_line
            }),
            Value::Link(l) => json!({
                "type": "link",
                "text": l.text,
                "url": l.url,
                "link_type": l.link_type.as_str()
            }),
            Value::Image(im) => json!({
                "type": "image",
                "alt": im.alt,
                "src": im.src
            }),
            Value::Table(t) => json!({
                "type": "table",
                "headers": t.headers,
                "rows": t.rows
            }),
            Value::List(l) => json!({
                "type": "list",
                "ordered": l.ordered,
                "items": l.items.iter().map(|i| json!({"content": i.content, "checked": i.checked})).collect::<Vec<_>>()
            }),
            Value::BlockQuote(c) => json!({
                "type": "blockquote",
                "content": c
            }),
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Null => false,
            Value::Bool(b) => *b,
            Value::Number(n) => *n != 0.0,
            Value::String(s) => !s.is_empty(),
            Value::Array(a) => !a.is_empty(),
            Value::Object(o) => !o.is_empty(),
            _ => true,
        }
    }
    pub fn is_empty(&self) -> bool {
        match self {
            Value::Null => true,
            Value::String(s) => s.is_empty(),
            Value::Array(a) => a.is_empty(),
            Value::Object(o) => o.is_empty(),
            _ => false,
        }
    }
    pub fn to_number(&self) -> f64 {
        match self {
            Value::Number(n) => *n,
            Value::String(s) => s.parse().unwrap_or(0.0),
            Value::Bool(b) => {
                if *b {
                    1.0
                } else {
                    0.0
                }
            }
            _ => 0.0,
        }
    }
    pub fn debug_repr(&self) -> String {
        match self {
            Value::Null => "Null".into(),
            Value::Bool(b) => format!("Bool({b})"),
            Value::Number(n) => format!("Number({n:?})"),
            Value::String(s) => format!("String({s:?})"),
            Value::Array(items) => {
                let inner: Vec<String> = items.iter().map(|v| v.debug_repr()).collect();
                format!("Array([{}])", inner.join(", "))
            }
            Value::Object(pairs) => {
                let inner: Vec<String> = pairs
                    .iter()
                    .map(|(k, v)| format!("{k:?}: {}", v.debug_repr()))
                    .collect();
                format!("Object({{{}}})", inner.join(", "))
            }
            Value::Document(d) => format!(
                "Document(DocumentValue {{ content: {:?}, heading_count: {}, word_count: {} }})",
                d.content, d.heading_count, d.word_count
            ),
            Value::Heading(h) => format!(
                "Heading(HeadingValue {{ level: {}, text: {:?}, offset: {}, line: {}, content: {:?}, raw_md: {:?}, index: {} }})",
                h.level, h.text, h.offset, h.line, h.content, h.raw_md, h.index
            ),
            Value::Code(c) => format!(
                "Code(CodeValue {{ language: {}, content: {:?}, start_line: {}, end_line: {} }})",
                match &c.language {
                    Some(l) => format!("Some({l:?})"),
                    None => "None".into(),
                },
                c.content,
                c.start_line,
                c.end_line
            ),
            Value::Link(l) => format!(
                "Link(LinkValue {{ text: {:?}, url: {:?}, link_type: {}, offset: {} }})",
                l.text,
                l.url,
                match l.link_type {
                    LinkType::External => "External",
                    LinkType::Anchor => "Anchor",
                    LinkType::Relative => "Relative",
                },
                l.offset
            ),
            Value::Image(im) => format!(
                "Image(ImageValue {{ alt: {:?}, src: {:?} }})",
                im.alt, im.src
            ),
            Value::Table(t) => format!(
                "Table(TableValue {{ headers: {:?}, rows: {:?}, alignments: {:?} }})",
                t.headers, t.rows, t.alignments
            ),
            Value::List(l) => {
                let items: Vec<String> = l
                    .items
                    .iter()
                    .map(|i| {
                        format!(
                            "ListItemValue {{ content: {:?}, checked: {} }}",
                            i.content,
                            match i.checked {
                                Some(b) => format!("Some({b})"),
                                None => "None".into(),
                            }
                        )
                    })
                    .collect();
                format!(
                    "List(ListValue {{ ordered: {}, items: [{}] }})",
                    l.ordered,
                    items.join(", ")
                )
            }
            Value::BlockQuote(c) => format!("BlockQuote({c:?})"),
        }
    }
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    if let (Value::String(_), _) | (_, Value::String(_)) = (a, b) {
        return a.to_text() == b.to_text();
    }
    a == b
}

pub fn compare_values(a: &Value, b: &Value) -> Option<Ordering> {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.partial_cmp(y),
        (Value::String(x), Value::String(y)) => Some(x.cmp(y)),
        _ => None,
    }
}

fn object_insert(pairs: &mut Vec<(String, Value)>, key: String, value: Value) {
    if let Some(existing) = pairs.iter_mut().find(|(k, _)| *k == key) {
        existing.1 = value;
    } else {
        pairs.push((key, value));
    }
}

fn collapse_stream(v: Vec<Value>) -> Value {
    match v.len() {
        0 => Value::Null,
        1 => v.into_iter().next().unwrap(),
        _ => Value::Array(v),
    }
}

fn first_or_null(v: &[Value]) -> Value {
    v.first().cloned().unwrap_or(Value::Null)
}

// ---------------- element extraction ----------------

pub struct Elements {
    pub headings: Vec<Value>,
    pub codes: Vec<Value>,
    pub links: Vec<Value>,
    pub tables: Vec<Value>,
    pub lists: Vec<Value>,
}

fn link_type_of(url: &str) -> LinkType {
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") {
        LinkType::External
    } else if url.starts_with('#') {
        LinkType::Anchor
    } else {
        LinkType::Relative
    }
}

fn collect_links_from_events(
    events: &[InlineEvent],
    out: &mut Vec<Value>,
    source: &str,
    cursor: &mut usize,
) {
    let mut i = 0;
    while i < events.len() {
        if let InlineEvent::StartLink { dest, .. } = &events[i] {
            let mut text = String::new();
            let mut j = i + 1;
            let mut depth = 1;
            while j < events.len() {
                match &events[j] {
                    InlineEvent::StartLink { .. } => depth += 1,
                    InlineEvent::EndLink => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    InlineEvent::Text(t) => text.push_str(t),
                    InlineEvent::Code(v) => text.push_str(v),
                    InlineEvent::SoftBreak => text.push(' '),
                    InlineEvent::HardBreak => text.push('\n'),
                    _ => {}
                }
                j += 1;
            }
            // find an approximate source offset for this link
            let offset = {
                let search_from = (*cursor).min(source.len());
                let is_auto = text == *dest || dest.strip_prefix("mailto:") == Some(&text);
                let needle = if is_auto { "<" } else { "[" };
                match source[search_from..].find(needle) {
                    Some(rel) => {
                        let at = search_from + rel;
                        *cursor = at + 1;
                        at
                    }
                    None => *cursor,
                }
            };
            out.push(Value::Link(LinkValue {
                text,
                url: dest.clone(),
                link_type: link_type_of(dest),
                offset,
            }));
            i = j + 1;
        } else {
            i += 1;
        }
    }
}

fn list_item_value(item: &ListItemNode, doc: &Document) -> ListItemValue {
    let content = match item.blocks.first() {
        Some(Node::Paragraph { text }) => {
            let events = parse_inline_events(text, &doc.global_refs);
            convert_inlines(&events, true).1
        }
        Some(Node::Heading(h)) => {
            let events = parse_inline_events(&h.inline_src, &doc.global_refs);
            heading_title_from_events(&events)
        }
        _ => String::new(),
    };
    ListItemValue {
        content,
        checked: item.checked,
    }
}

fn extract_from_nodes(
    nodes: &[Node],
    doc: &Document,
    codes: &mut Vec<Value>,
    links: &mut Vec<Value>,
    tables: &mut Vec<Value>,
    lists: &mut Vec<Value>,
    cursor: &mut usize,
) {
    for node in nodes {
        match node {
            Node::Heading(h) => {
                let events = parse_inline_events(&h.inline_src, &doc.global_refs);
                collect_links_from_events(&events, links, &doc.source, cursor);
            }
            Node::Paragraph { text } => {
                let events = parse_inline_events(text, &doc.global_refs);
                collect_links_from_events(&events, links, &doc.source, cursor);
            }
            Node::Code { language, content } => {
                codes.push(Value::Code(CodeValue {
                    language: language.clone(),
                    content: content.clone(),
                    start_line: 1,
                    end_line: 1,
                }));
            }
            Node::Table {
                headers,
                alignments,
                rows,
            } => {
                let conv_headers: Vec<String> = headers
                    .iter()
                    .map(|h| {
                        let ev = parse_inline_events(h, &doc.global_refs);
                        collect_links_from_events(&ev, links, &doc.source, cursor);
                        convert_inlines(&ev, false).1
                    })
                    .collect();
                let conv_rows: Vec<Vec<String>> = rows
                    .iter()
                    .map(|r| {
                        r.iter()
                            .map(|c| {
                                let ev = parse_inline_events(c, &doc.global_refs);
                                collect_links_from_events(&ev, links, &doc.source, cursor);
                                convert_inlines(&ev, false).1
                            })
                            .collect()
                    })
                    .collect();
                tables.push(Value::Table(TableValue {
                    headers: conv_headers,
                    rows: conv_rows,
                    alignments: alignments.clone(),
                }));
            }
            Node::List { ordered, items } => {
                lists.push(Value::List(ListValue {
                    ordered: *ordered,
                    items: items.iter().map(|it| list_item_value(it, doc)).collect(),
                }));
                for item in items {
                    extract_from_nodes(&item.blocks, doc, codes, links, tables, lists, cursor);
                }
            }
            Node::BlockQuote(children) => {
                extract_from_nodes(children, doc, codes, links, tables, lists, cursor);
            }
            Node::HorizontalRule => {}
        }
    }
}

pub fn extract_elements(doc: &Document) -> Elements {
    let headings: Vec<Value> = doc
        .headings
        .iter()
        .map(|h| {
            Value::Heading(HeadingValue {
                level: h.level,
                text: h.text.clone(),
                offset: h.offset,
                line: h.line,
                content: h.content.clone(),
                raw_md: h.raw_md.clone(),
                index: h.index,
            })
        })
        .collect();
    let mut codes = Vec::new();
    let mut links = Vec::new();
    let mut tables = Vec::new();
    let mut lists = Vec::new();
    let mut cursor = 0usize;
    extract_from_nodes(
        &doc.global_nodes,
        doc,
        &mut codes,
        &mut links,
        &mut tables,
        &mut lists,
        &mut cursor,
    );
    Elements {
        headings,
        codes,
        links,
        tables,
        lists,
    }
}
