// ---------------- evaluator ----------------

pub struct Engine<'a> {
    doc: &'a Document,
    elements: Elements,
    source: String,
}

impl<'a> Engine<'a> {
    pub fn new(doc: &'a Document, source: &str) -> Self {
        Engine {
            doc,
            elements: extract_elements(doc),
            source: source.to_string(),
        }
    }
    fn err(&self, message: String) -> QueryError {
        QueryError::simple(message, &self.source)
    }
    pub fn run(&self, expr: &Expr) -> QResult<Vec<Value>> {
        let root = Value::Document(DocumentValue {
            content: self.doc.source.clone(),
            heading_count: self.doc.heading_count(),
            word_count: self.doc.word_count(),
        });
        self.eval(expr, &root)
    }

    fn eval(&self, expr: &Expr, input: &Value) -> QResult<Vec<Value>> {
        match expr {
            Expr::Null => Ok(vec![Value::Null]),
            Expr::Bool(b) => Ok(vec![Value::Bool(*b)]),
            Expr::Number(n) => Ok(vec![Value::Number(*n)]),
            Expr::Str(s) => Ok(vec![Value::String(s.clone())]),
            Expr::Root => Ok(vec![input.clone()]),
            Expr::Paren(inner) => self.eval(inner, input),
            Expr::Multi(exprs) => {
                let mut out = Vec::new();
                for e in exprs {
                    out.extend(self.eval(e, input)?);
                }
                Ok(out)
            }
            Expr::Selector { kind, filter } => {
                let mut items = self.select(kind);
                if let Some(f) = filter {
                    items = apply_filter(items, f);
                }
                Ok(items)
            }
            Expr::FieldAccess { field, .. } => {
                // NB: the object expression is not evaluated.
                let v = self.get_property(input, field)?;
                Ok(vec![v])
            }
            Expr::Index { object } => self.eval(object, input),
            Expr::FunctionCall { name, args } => self.eval_function(name, args, input),
            Expr::Pipe(left, right) => {
                let mut out = Vec::new();
                for v in self.eval(left, input)? {
                    out.extend(self.eval(right, &v)?);
                }
                Ok(out)
            }
            Expr::ArrayConstruct(elems) => {
                let mut items = Vec::new();
                for e in elems {
                    items.extend(self.eval(e, input)?);
                }
                Ok(vec![Value::Array(items)])
            }
            Expr::ObjectConstruct(pairs) => {
                let mut obj: Vec<(String, Value)> = Vec::new();
                for (k, e) in pairs {
                    let vs = self.eval(e, input)?;
                    object_insert(&mut obj, k.clone(), collapse_stream(vs));
                }
                Ok(vec![Value::Object(obj)])
            }
            Expr::Not(inner) => {
                let vs = self.eval(inner, input)?;
                let truthy = vs.first().map(|v| v.is_truthy()).unwrap_or(false);
                Ok(vec![Value::Bool(!truthy)])
            }
            Expr::Neg(inner) => {
                let vs = self.eval(inner, input)?;
                let v = first_or_null(&vs);
                Ok(vec![Value::Number(-v.to_number())])
            }
            Expr::Hierarchy {
                left,
                right,
                descendant,
            } => {
                let parents = self.eval(left, input)?;
                let children = self.eval(right, input)?;
                let mut out = Vec::new();
                for p in &parents {
                    let Value::Heading(ph) = p else { continue };
                    for c in &children {
                        match c {
                            Value::Heading(ch) => {
                                let ok = if *descendant {
                                    self.is_descendant(ph.index, ch.index)
                                } else {
                                    self.parent_index(ch.index) == Some(ph.index)
                                };
                                if ok {
                                    out.push(c.clone());
                                }
                            }
                            Value::Code(_) => out.push(c.clone()),
                            _ => {}
                        }
                    }
                }
                Ok(out)
            }
            Expr::Binary { op, left, right } => {
                if let BinOp::Alt = op {
                    let l = self.eval(left, input)?;
                    if l.is_empty() || l.iter().all(|v| !v.is_truthy()) {
                        return self.eval(right, input);
                    }
                    return Ok(l);
                }
                let l = self.eval(left, input)?;
                let r = self.eval(right, input)?;
                let lv = first_or_null(&l);
                let rv = first_or_null(&r);
                let result = self.apply_binary(op, &lv, &rv)?;
                Ok(vec![result])
            }
        }
    }

    fn parent_index(&self, idx: usize) -> Option<usize> {
        let headings = &self.doc.headings;
        if idx >= headings.len() {
            return None;
        }
        let level = headings[idx].level;
        let mut i = idx;
        while i > 0 {
            i -= 1;
            if headings[i].level < level {
                return Some(headings[i].index);
            }
        }
        None
    }
    fn is_descendant(&self, ancestor: usize, idx: usize) -> bool {
        let mut cur = self.parent_index(idx);
        while let Some(p) = cur {
            if p == ancestor {
                return true;
            }
            cur = self.parent_index(p);
        }
        false
    }

    fn select(&self, kind: &SelectorKind) -> Vec<Value> {
        match kind {
            SelectorKind::Headings(level) => self
                .elements
                .headings
                .iter()
                .filter(|v| match (v, level) {
                    (Value::Heading(h), Some(l)) => h.level == *l,
                    (_, None) => true,
                    _ => false,
                })
                .cloned()
                .collect(),
            SelectorKind::Code => self.elements.codes.clone(),
            SelectorKind::Link => self.elements.links.clone(),
            SelectorKind::Table => self.elements.tables.clone(),
            SelectorKind::List => self.elements.lists.clone(),
            SelectorKind::Image | SelectorKind::Blockquote | SelectorKind::Paragraph => vec![],
        }
    }

    fn get_property(&self, value: &Value, name: &str) -> QResult<Value> {
        let not_found = || {
            self.err(format!(
                "Property '{name}' not found on {}",
                value.type_name()
            ))
        };
        match value {
            Value::Document(d) => match name {
                "text" | "content" => Ok(Value::String(d.content.clone())),
                "heading_count" | "headings" => {
                    Ok(Value::Number(d.heading_count as f64))
                }
                "word_count" | "words" => Ok(Value::Number(d.word_count as f64)),
                _ => Err(not_found()),
            },
            Value::Heading(h) => match name {
                "text" => Ok(Value::String(h.text.clone())),
                "level" => Ok(Value::Number(h.level as f64)),
                "line" => Ok(Value::Number(h.line as f64)),
                "content" => Ok(Value::String(h.content.clone())),
                "md" => Ok(Value::String(h.raw_md.clone())),
                "slug" => Ok(Value::String(slugify(&h.text))),
                _ => Err(not_found()),
            },
            Value::Code(c) => match name {
                "text" | "content" => Ok(Value::String(c.content.clone())),
                "lang" | "language" => Ok(match &c.language {
                    Some(l) => Value::String(l.clone()),
                    None => Value::Null,
                }),
                "start_line" => Ok(Value::Number(c.start_line as f64)),
                "end_line" => Ok(Value::Number(c.end_line as f64)),
                _ => Err(not_found()),
            },
            Value::Link(l) => match name {
                "text" => Ok(Value::String(l.text.clone())),
                "url" => Ok(Value::String(l.url.clone())),
                "type" => Ok(Value::String(l.link_type.as_str().to_string())),
                _ => Err(not_found()),
            },
            Value::Image(im) => match name {
                "alt" | "text" => Ok(Value::String(im.alt.clone())),
                "src" | "url" => Ok(Value::String(im.src.clone())),
                _ => Err(not_found()),
            },
            Value::Table(t) => match name {
                "headers" => Ok(Value::Array(
                    t.headers.iter().map(|h| Value::String(h.clone())).collect(),
                )),
                "rows" => Ok(Value::Array(
                    t.rows
                        .iter()
                        .map(|r| {
                            Value::Array(
                                r.iter().map(|c| Value::String(c.clone())).collect(),
                            )
                        })
                        .collect(),
                )),
                _ => Err(not_found()),
            },
            Value::List(l) => match name {
                "items" => Ok(Value::Array(
                    l.items
                        .iter()
                        .map(|i| Value::String(i.content.clone()))
                        .collect(),
                )),
                "ordered" => Ok(Value::Bool(l.ordered)),
                "count" | "length" => Ok(Value::Number(l.items.len() as f64)),
                _ => Err(not_found()),
            },
            Value::BlockQuote(c) => match name {
                "text" | "content" => Ok(Value::String(c.clone())),
                _ => Err(not_found()),
            },
            Value::Object(pairs) => match pairs.iter().find(|(k, _)| k == name) {
                Some((_, v)) => Ok(v.clone()),
                None => Err(not_found()),
            },
            _ => Err(not_found()),
        }
    }

    fn apply_binary(&self, op: &BinOp, a: &Value, b: &Value) -> QResult<Value> {
        match op {
            BinOp::And => Ok(Value::Bool(a.is_truthy() && b.is_truthy())),
            BinOp::Or => Ok(Value::Bool(a.is_truthy() || b.is_truthy())),
            BinOp::Alt => unreachable!(),
            BinOp::Eq => Ok(Value::Bool(values_equal(a, b))),
            BinOp::Ne => Ok(Value::Bool(!values_equal(a, b))),
            BinOp::Lt => Ok(Value::Bool(compare_values(a, b) == Some(Ordering::Less))),
            BinOp::Gt => Ok(Value::Bool(
                compare_values(a, b) == Some(Ordering::Greater),
            )),
            BinOp::Le => Ok(Value::Bool(
                compare_values(a, b) != Some(Ordering::Greater),
            )),
            BinOp::Ge => Ok(Value::Bool(
                compare_values(a, b) != Some(Ordering::Less),
            )),
            BinOp::Add => match (a, b) {
                (Value::Number(x), Value::Number(y)) => Ok(Value::Number(x + y)),
                (Value::Array(x), Value::Array(y)) => {
                    let mut items = x.clone();
                    items.extend(y.iter().cloned());
                    Ok(Value::Array(items))
                }
                _ => Ok(Value::String(format!("{}{}", a.to_text(), b.to_text()))),
            },
            BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => match (a, b) {
                (Value::Number(x), Value::Number(y)) => match op {
                    BinOp::Sub => Ok(Value::Number(x - y)),
                    BinOp::Mul => Ok(Value::Number(x * y)),
                    BinOp::Div => {
                        if *y == 0.0 {
                            Err(self.err("Division by zero".into()))
                        } else {
                            Ok(Value::Number(x / y))
                        }
                    }
                    BinOp::Mod => {
                        if *y == 0.0 {
                            Err(self.err("Division by zero".into()))
                        } else {
                            Ok(Value::Number(x % y))
                        }
                    }
                    _ => unreachable!(),
                },
                _ => Ok(Value::Null),
            },
        }
    }

    fn eval_function(&self, name: &str, args: &[Expr], input: &Value) -> QResult<Vec<Value>> {
        if !KNOWN_FUNCTIONS.contains(&name) {
            return Err(unknown_function_error(name, &self.source));
        }
        match name {
            "select" | "where" | "filter" => {
                if args.is_empty() {
                    return Err(self.err(format!(
                        "Function '{name}' expects 1..=1 arguments, got 0"
                    )));
                }
                let vs = self.eval(&args[0], input)?;
                if args.len() != 1 {
                    return Err(self.err(format!(
                        "Function '{name}' expects 1..=1 arguments, got {}",
                        args.len()
                    )));
                }
                let truthy = vs.first().map(|v| v.is_truthy()).unwrap_or(false);
                if truthy {
                    Ok(vec![input.clone()])
                } else {
                    Ok(vec![])
                }
            }
            "any" | "all" => {
                if args.is_empty() {
                    return Err(self.err(format!(
                        "Function '{name}' expects 1..=1 arguments, got 0"
                    )));
                }
                let is_any = name == "any";
                let result = match input {
                    Value::Array(items) => {
                        if is_any {
                            let mut found = false;
                            for _item in items {
                                let vs = self.eval(&args[0], input)?;
                                if !vs.is_empty() {
                                    found = true;
                                    break;
                                }
                            }
                            found
                        } else {
                            let mut all = true;
                            for _item in items {
                                let vs = self.eval(&args[0], input)?;
                                if vs.is_empty() {
                                    all = false;
                                    break;
                                }
                            }
                            all
                        }
                    }
                    _ => {
                        let vs = self.eval(&args[0], input)?;
                        if is_any {
                            vs.iter().any(|v| v.is_truthy())
                        } else {
                            vs.iter().all(|v| v.is_truthy())
                        }
                    }
                };
                if args.len() != 1 {
                    return Err(self.err(format!(
                        "Function '{name}' expects 1..=1 arguments, got {}",
                        args.len()
                    )));
                }
                Ok(vec![Value::Bool(result)])
            }
            _ => {
                // eagerly evaluate arguments
                let mut arg_values = Vec::new();
                for a in args {
                    let vs = self.eval(a, input)?;
                    arg_values.push(collapse_stream(vs));
                }
                let expected = expected_args(name);
                if arg_values.len() != expected {
                    return Err(self.err(format!(
                        "Function '{name}' expects {expected}..={expected} arguments, got {}",
                        arg_values.len()
                    )));
                }
                self.apply_function(name, &arg_values, input)
            }
        }
    }

    fn apply_function(
        &self,
        name: &str,
        args: &[Value],
        input: &Value,
    ) -> QResult<Vec<Value>> {
        let text = input.to_text();
        let result: Vec<Value> = match name {
            "count" | "length" | "len" | "size" => {
                let n = match input {
                    Value::Array(a) => a.len(),
                    Value::String(s) => s.len(),
                    Value::Object(o) => o.len(),
                    Value::List(l) => l.items.len(),
                    _ => 1,
                };
                vec![Value::Number(n as f64)]
            }
            "first" | "head" => match input {
                Value::Array(a) => match a.first() {
                    Some(v) => vec![v.clone()],
                    None => vec![],
                },
                Value::String(s) => match s.chars().next() {
                    Some(c) => vec![Value::String(c.to_string())],
                    None => vec![],
                },
                _ => vec![input.clone()],
            },
            "last" => match input {
                Value::Array(a) => match a.last() {
                    Some(v) => vec![v.clone()],
                    None => vec![],
                },
                Value::String(s) => match s.chars().next_back() {
                    Some(c) => vec![Value::String(c.to_string())],
                    None => vec![],
                },
                _ => vec![input.clone()],
            },
            "reverse" => match input {
                Value::Array(a) => {
                    let mut items = a.clone();
                    items.reverse();
                    vec![Value::Array(items)]
                }
                Value::String(s) => {
                    vec![Value::String(s.chars().rev().collect())]
                }
                _ => vec![input.clone()],
            },
            "sort" => match input {
                Value::Array(a) => {
                    let mut items = a.clone();
                    items.sort_by_cached_key(|v| v.to_text());
                    vec![Value::Array(items)]
                }
                _ => vec![input.clone()],
            },
            "unique" => match input {
                Value::Array(a) => {
                    let mut out: Vec<Value> = Vec::new();
                    for v in a {
                        if !out.contains(v) {
                            out.push(v.clone());
                        }
                    }
                    vec![Value::Array(out)]
                }
                _ => vec![input.clone()],
            },
            "flatten" => match input {
                Value::Array(a) => {
                    let mut out = Vec::new();
                    for v in a {
                        match v {
                            Value::Array(inner) => out.extend(inner.iter().cloned()),
                            other => out.push(other.clone()),
                        }
                    }
                    vec![Value::Array(out)]
                }
                _ => vec![input.clone()],
            },
            "min" | "max" => {
                let nums: Vec<f64> = match input {
                    Value::Array(a) => a
                        .iter()
                        .filter_map(|v| match v {
                            Value::Number(n) => Some(*n),
                            _ => None,
                        })
                        .collect(),
                    Value::Number(n) => vec![*n],
                    _ => vec![],
                };
                if nums.is_empty() {
                    vec![Value::Null]
                } else if name == "min" {
                    vec![Value::Number(
                        nums.into_iter().fold(f64::INFINITY, f64::min),
                    )]
                } else {
                    vec![Value::Number(
                        nums.into_iter().fold(f64::NEG_INFINITY, f64::max),
                    )]
                }
            }
            "add" => match input {
                Value::Array(a) => {
                    if a.is_empty() {
                        vec![Value::Number(-0.0)]
                    } else if a.iter().all(|v| matches!(v, Value::Number(_))) {
                        let sum: f64 = a
                            .iter()
                            .map(|v| match v {
                                Value::Number(n) => *n,
                                _ => 0.0,
                            })
                            .sum();
                        vec![Value::Number(sum)]
                    } else {
                        vec![Value::String(
                            a.iter().map(|v| v.to_text()).collect::<String>(),
                        )]
                    }
                }
                _ => vec![input.clone()],
            },
            "text" => vec![Value::String(text)],
            "upper" => vec![Value::String(text.to_uppercase())],
            "lower" => vec![Value::String(text.to_lowercase())],
            "trim" => vec![Value::String(text.trim().to_string())],
            "slugify" => vec![Value::String(slugify(&text))],
            "lines" => vec![Value::Number(text.lines().count() as f64)],
            "words" => vec![Value::Number(text.split_whitespace().count() as f64)],
            "chars" => vec![Value::Number(text.chars().count() as f64)],
            "content" => vec![Value::String(match input {
                Value::Heading(h) => h.content.clone(),
                Value::Document(d) => d.content.clone(),
                _ => text,
            })],
            "md" => vec![Value::String(match input {
                Value::Heading(h) => h.raw_md.clone(),
                Value::Document(d) => d.content.clone(),
                _ => text,
            })],
            "url" | "href" | "src" => vec![match input {
                Value::Link(l) => Value::String(l.url.clone()),
                Value::Image(im) => Value::String(im.src.clone()),
                _ => Value::Null,
            }],
            "lang" => vec![match input {
                Value::Code(c) => match &c.language {
                    Some(l) => Value::String(l.clone()),
                    None => Value::Null,
                },
                _ => Value::Null,
            }],
            "stats" => vec![self.stats_value()],
            "levels" => vec![self.levels_value()],
            "langs" => vec![self.langs_value()],
            "types" => vec![self.types_value()],
            "keys" => vec![Value::Array(match input {
                Value::Array(a) => (0..a.len()).map(|i| Value::Number(i as f64)).collect(),
                Value::Object(o) => o
                    .iter()
                    .map(|(k, _)| Value::String(k.clone()))
                    .collect(),
                _ => vec![],
            })],
            "values" => vec![Value::Array(match input {
                Value::Array(a) => a.clone(),
                Value::Object(o) => o.iter().map(|(_, v)| v.clone()).collect(),
                _ => vec![],
            })],
            "empty" => vec![Value::Bool(input.is_empty())],
            "debug" => {
                eprintln!("[DEBUG] {}", input.debug_repr());
                vec![input.clone()]
            }
            "type" => vec![Value::String(input.type_name().to_string())],
            "limit" | "take" => {
                let n = arg_usize(&args[0]);
                match input {
                    Value::Array(a) => {
                        vec![Value::Array(a.iter().take(n).cloned().collect())]
                    }
                    Value::String(s) => {
                        vec![Value::String(s.chars().take(n).collect())]
                    }
                    _ => vec![input.clone()],
                }
            }
            "skip" | "drop" => {
                let n = arg_usize(&args[0]);
                match input {
                    Value::Array(a) => {
                        vec![Value::Array(a.iter().skip(n).cloned().collect())]
                    }
                    Value::String(s) => {
                        vec![Value::String(s.chars().skip(n).collect())]
                    }
                    _ => vec![input.clone()],
                }
            }
            "nth" => {
                let n = arg_i64(&args[0]);
                match input {
                    Value::Array(a) => match nth_index(n, a.len()) {
                        Some(i) => vec![a[i].clone()],
                        None => vec![],
                    },
                    Value::String(s) => {
                        let chars: Vec<char> = s.chars().collect();
                        match nth_index(n, chars.len()) {
                            Some(i) => vec![Value::String(chars[i].to_string())],
                            None => vec![],
                        }
                    }
                    _ => vec![],
                }
            }
            "sort_by" => match input {
                Value::Array(a) => {
                    let key = args[0].to_text();
                    let mut items = a.clone();
                    items.sort_by_cached_key(|v| sort_key(v, &key).to_text());
                    vec![Value::Array(items)]
                }
                _ => vec![input.clone()],
            },
            "group_by" => match input {
                Value::Array(a) => {
                    let key = args[0].to_text();
                    let mut groups: Vec<(String, Value)> = Vec::new();
                    for item in a {
                        let gk = group_key(item, &key);
                        match groups.iter_mut().find(|(k, _)| *k == gk) {
                            Some((_, Value::Array(arr))) => arr.push(item.clone()),
                            _ => groups.push((gk, Value::Array(vec![item.clone()]))),
                        }
                    }
                    vec![Value::Object(groups)]
                }
                _ => vec![input.clone()],
            },
            "split" => {
                let sep = args[0].to_text();
                vec![Value::Array(
                    text.split(&sep)
                        .map(|s| Value::String(s.to_string()))
                        .collect(),
                )]
            }
            "join" => {
                let sep = args[0].to_text();
                match input {
                    Value::Array(a) => vec![Value::String(
                        a.iter()
                            .map(|v| v.to_text())
                            .collect::<Vec<_>>()
                            .join(&sep),
                    )],
                    _ => vec![Value::String(text)],
                }
            }
            "replace" => {
                vec![Value::String(
                    text.replace(&args[0].to_text(), &args[1].to_text()),
                )]
            }
            "contains" | "includes" => {
                let needle = args[0].to_text().to_lowercase();
                vec![Value::Bool(text.to_lowercase().contains(&needle))]
            }
            "startswith" => {
                let needle = args[0].to_text().to_lowercase();
                vec![Value::Bool(text.to_lowercase().starts_with(&needle))]
            }
            "endswith" => {
                let needle = args[0].to_text().to_lowercase();
                vec![Value::Bool(text.to_lowercase().ends_with(&needle))]
            }
            "matches" => {
                let pat = args[0].to_text();
                let ok = Regex::new(&pat).map(|re| re.is_match(&text)).unwrap_or(false);
                vec![Value::Bool(ok)]
            }
            "has" => {
                let key = args[0].to_text();
                vec![Value::Bool(match input {
                    Value::Object(o) => o.iter().any(|(k, _)| *k == key),
                    _ => false,
                })]
            }
            _ => unreachable!(),
        };
        Ok(result)
    }

    fn stats_value(&self) -> Value {
        let e = &self.elements;
        Value::Object(vec![
            ("headings".into(), Value::Number(e.headings.len() as f64)),
            (
                "code_blocks".into(),
                Value::Number(e.codes.len() as f64),
            ),
            ("links".into(), Value::Number(e.links.len() as f64)),
            ("images".into(), Value::Number(0.0)),
            ("tables".into(), Value::Number(e.tables.len() as f64)),
            ("lists".into(), Value::Number(e.lists.len() as f64)),
            (
                "words".into(),
                Value::Number(self.doc.word_count() as f64),
            ),
        ])
    }
    fn levels_value(&self) -> Value {
        let mut pairs = Vec::new();
        for level in 1..=6usize {
            let count = self
                .doc
                .headings
                .iter()
                .filter(|h| h.level == level)
                .count();
            if count > 0 {
                pairs.push((format!("h{level}"), Value::Number(count as f64)));
            }
        }
        Value::Object(pairs)
    }
    fn langs_value(&self) -> Value {
        let mut map: HashMap<String, f64> = HashMap::new();
        for c in &self.elements.codes {
            if let Value::Code(cv) = c {
                let key = cv.language.clone().unwrap_or_else(|| "none".to_string());
                *map.entry(key).or_insert(0.0) += 1.0;
            }
        }
        Value::Object(
            map.into_iter()
                .map(|(k, v)| (k, Value::Number(v)))
                .collect(),
        )
    }
    fn types_value(&self) -> Value {
        let mut map: HashMap<String, f64> = HashMap::new();
        for l in &self.elements.links {
            if let Value::Link(lv) = l {
                *map.entry(lv.link_type.as_str().to_string()).or_insert(0.0) += 1.0;
            }
        }
        Value::Object(
            map.into_iter()
                .map(|(k, v)| (k, Value::Number(v)))
                .collect(),
        )
    }
}

fn sort_key(v: &Value, key: &str) -> Value {
    match v {
        Value::Object(o) => o
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, val)| val.clone())
            .unwrap_or(Value::Null),
        Value::Heading(h) if key == "level" => Value::Number(h.level as f64),
        _ => Value::String(v.to_text()),
    }
}

fn group_key(v: &Value, key: &str) -> String {
    match v {
        Value::Heading(h) => format!("h{}", h.level),
        Value::Code(c) => c.language.clone().unwrap_or_else(|| "none".to_string()),
        Value::Link(l) => l.text.clone(),
        Value::Object(o) => o
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, val)| val.to_text())
            .unwrap_or_default(),
        _ => v.to_text(),
    }
}

fn arg_usize(v: &Value) -> usize {
    match v {
        Value::Number(n) => {
            if *n <= 0.0 {
                0
            } else {
                *n as usize
            }
        }
        _ => 0,
    }
}
fn arg_i64(v: &Value) -> i64 {
    match v {
        Value::Number(n) => *n as i64,
        _ => 0,
    }
}
fn nth_index(n: i64, len: usize) -> Option<usize> {
    let idx = if n < 0 {
        (len as i64 + n).max(0)
    } else {
        n
    };
    if idx < 0 || (idx as usize) >= len {
        None
    } else {
        Some(idx as usize)
    }
}

fn apply_filter(items: Vec<Value>, filter: &Filter) -> Vec<Value> {
    match filter {
        Filter::All => items,
        Filter::Index(n) => {
            let len = items.len() as i64;
            let mut idx = *n as i64;
            if idx < 0 {
                idx += len;
            }
            if idx >= 0 && idx < len {
                vec![items[idx as usize].clone()]
            } else {
                vec![]
            }
        }
        Filter::Slice(start, end) => {
            let len = items.len() as i64;
            let norm = |v: Option<f64>, default: i64| -> i64 {
                match v {
                    None => default,
                    Some(x) => {
                        let mut i = x as i64;
                        if i < 0 {
                            i += len;
                        }
                        i.clamp(0, len)
                    }
                }
            };
            let s = norm(*start, 0);
            let e = norm(*end, len);
            if s >= e {
                vec![]
            } else {
                items[s as usize..e as usize].to_vec()
            }
        }
        Filter::Text(pat) => items
            .into_iter()
            .filter(|v| {
                if let Value::Link(l) = v {
                    if pat == "external" || pat == "anchor" || pat == "relative" {
                        return l.link_type.as_str() == pat;
                    }
                }
                v.to_text().to_lowercase().contains(&pat.to_lowercase())
            })
            .collect(),
        Filter::Exact(pat) => items
            .into_iter()
            .filter(|v| v.to_text().to_lowercase() == pat.to_lowercase())
            .collect(),
    }
}

const KNOWN_FUNCTIONS: &[&str] = &[
    "count", "length", "len", "size", "first", "last", "head", "limit", "take", "skip", "drop",
    "nth", "reverse", "sort", "sort_by", "unique", "flatten", "group_by", "min", "max", "add",
    "text", "upper", "lower", "trim", "split", "join", "replace", "slugify", "lines", "words",
    "chars", "select", "where", "filter", "contains", "includes", "startswith", "endswith",
    "matches", "any", "all", "not", "content", "md", "url", "href", "src", "lang", "stats",
    "levels", "langs", "types", "keys", "values", "has", "empty", "debug", "type",
];

fn expected_args(name: &str) -> usize {
    match name {
        "limit" | "take" | "skip" | "drop" | "nth" | "sort_by" | "group_by" | "split"
        | "join" | "select" | "where" | "filter" | "contains" | "includes" | "startswith"
        | "endswith" | "matches" | "any" | "all" | "has" => 1,
        "replace" => 2,
        _ => 0,
    }
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![i];
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur.push(
                (prev[j] + 1)
                    .min(cur[j - 1] + 1)
                    .min(prev[j - 1] + cost),
            );
        }
        prev = cur;
    }
    prev[b.len()]
}

fn unknown_function_error(name: &str, source: &str) -> QueryError {
    let mut cands: Vec<(usize, &str)> = KNOWN_FUNCTIONS
        .iter()
        .map(|&f| (levenshtein(name, f), f))
        .filter(|(d, _)| *d <= 2)
        .collect();
    cands.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(b.1)));
    cands.truncate(3);
    let mut err = QueryError::simple(format!("Unknown function '{name}'"), source);
    if !cands.is_empty() {
        let names: Vec<String> = cands.iter().map(|(_, f)| format!("'{f}'")).collect();
        err.help = Some(format!("did you mean {}?", names.join(" or ")));
        err.suggestion_style = true;
    }
    err
}
