// ---------------- output formatting ----------------

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum QueryOutput {
    Plain,
    Json,
    JsonPretty,
    Jsonl,
    Md,
    Tree,
}

impl QueryOutput {
