// ---------------- output formatting ----------------

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum QueryOutput {
    Plain,
    Json,
    JsonPretty,
    Jsonl,
    Md,
    Tree,
}

impl QueryOutput {
    pub fn parse(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "plain" => Some(QueryOutput::Plain),
            "json" => Some(QueryOutput::Json),
            "json-pretty" => Some(QueryOutput::JsonPretty),
            "jsonl" => Some(QueryOutput::Jsonl),
            "md" | "markdown" => Some(QueryOutput::Md),
            "tree" => Some(QueryOutput::Tree),
            _ => None,
        }
    }
}

pub fn format_results(results: &[Value], fmt: QueryOutput) -> String {
    if results.is_empty() {
        return String::new();
    }
    match fmt {
        QueryOutput::Plain => {
            let mut out = String::new();
            for v in results {
                out.push_str(&v.to_plain());
                out.push('\n');
            }
            out
        }
        QueryOutput::Json => {
            let v = aggregate_json(results);
            format!("{}\n", serde_json::to_string(&v).unwrap_or_default())
        }
        QueryOutput::JsonPretty => {
            let v = aggregate_json(results);
            format!(
                "{}\n",
                serde_json::to_string_pretty(&v).unwrap_or_default()
            )
        }
        QueryOutput::Jsonl => {
            let mut out = String::new();
            for v in results {
                out.push_str(&serde_json::to_string(&v.to_json()).unwrap_or_default());
                out.push('\n');
            }
            out
        }
        QueryOutput::Md => {
            if results.len() == 1 {
                format!("{}\n", results[0].to_md())
            } else {
                let parts: Vec<String> = results.iter().map(|v| v.to_md()).collect();
                format!("{}\n", parts.join("\n\n"))
            }
        }
        QueryOutput::Tree => {
            let lines = tree_lines(results, "");
            format!("{}\n\n", lines.join("\n"))
        }
    }
}

fn aggregate_json(results: &[Value]) -> JsonValue {
    if results.len() == 1 {
        results[0].to_json()
    } else {
        JsonValue::Array(results.iter().map(|v| v.to_json()).collect())
    }
}

fn tree_text(v: &Value) -> String {
    match v {
        Value::Heading(_) => v.to_plain(),
        Value::Code(c) => c.content.clone(),
        Value::Link(l) => l.text.clone(),
        Value::Image(im) => im.alt.clone(),
        Value::Table(_) => v.to_text(),
        Value::List(_) => v.to_text(),
        Value::Document(d) => d.content.clone(),
        _ => v.to_plain(),
    }
}

fn tree_lines(values: &[Value], prefix: &str) -> Vec<String> {
    let mut lines = Vec::new();
    for (i, v) in values.iter().enumerate() {
        let last = i + 1 == values.len();
        let branch = if last { "└──" } else { "├──" };
        let child_prefix = format!("{prefix}{}", if last { "   " } else { "│  " });
        match v {
            Value::Array(items) => {
                lines.push(format!("{prefix}{branch}["));
                lines.extend(tree_lines(items, &child_prefix));
                lines.push(format!("{child_prefix}]"));
            }
            Value::Object(pairs) => {
                lines.push(format!("{prefix}{branch}{{"));
                for (k, val) in pairs {
                    if matches!(val, Value::Array(_) | Value::Object(_)) {
                        lines.push(format!("{child_prefix}{k}: "));
                        lines.extend(tree_lines(
                            std::slice::from_ref(val),
                            &format!("{child_prefix}  "),
                        ));
                    } else {
                        lines.push(format!("{child_prefix}{k}: {}", val.to_plain()));
                    }
                }
                lines.push(format!("{child_prefix}}}"));
            }
            _ => {
                lines.push(format!("{prefix}{branch}{}", tree_text(v)));
            }
        }
    }
    lines
}

/// Entry point used by main: parse + evaluate, returning result values.
pub fn run_query(doc: &Document, query: &str) -> QResult<Vec<Value>> {
    let expr = parse_query_str(query)?;
    let engine = Engine::new(doc, query);
    engine.run(&expr)
}
