#[derive(Subcommand, Debug)]
enum Commands {
    /// Show heading at specific line number
    ///
    /// Finds and displays the heading that appears at or before the given line number. Useful for jumping to a specific location in the document structure.
    AtLine {
        /// Line number in the markdown file
        ///
        /// The line number to search for. Returns the heading at or immediately before this line.
        line: usize,
    },
}

#[derive(Copy, Clone, PartialEq, Eq, Debug, ValueEnum)]
enum OutputFormat {
    /// Plain text output
    Plain,
    /// JSON output
    Json,
    /// Tree format with box-drawing
    Tree,
}
impl std::fmt::Display for OutputFormat {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            OutputFormat::Plain => write!(f, "plain"),
            OutputFormat::Json => write!(f, "json"),
            OutputFormat::Tree => write!(f, "tree"),
        }
    }
}

#[derive(Copy, Clone, PartialEq, Eq, Debug, ValueEnum)]
enum ColorMode {
    /// Automatically detect terminal capabilities
    Auto,
    /// Force RGB/true color mode
    Rgb,
    /// Force 256-color mode
    #[value(name = "256")]
    Color256,
}
impl ColorMode {
    fn as_str(&self) -> &'static str {
        match self {
            ColorMode::Auto => "auto",
            ColorMode::Rgb => "rgb",
            ColorMode::Color256 => "256",
        }
    }
}

const QUERY_HELP: &str = r#"treemd Query Language (tql)

A jq-like query language for navigating and extracting markdown structure.

ELEMENT SELECTORS
    .h, .heading    All headings (any level)
    .h1 - .h6       Headings by level
    .code           All code blocks
    .code[rust]     Code blocks by language
    .link, .a       All links
    .link[external] External links only
    .img            All images
    .table          All tables
    .list           All lists
    .blockquote     All blockquotes

FILTERS & INDEXING
    .h2[Features]       Heading containing "Features" (fuzzy)
    .h2["Installation"] Heading with exact text
    .h2[0]              First h2
    .h2[-1]             Last h2
    .h2[1:3]            h2s at index 1 and 2
    .h2[:3]             First 3 h2s

HIERARCHY
    .h1 > .h2           Direct child h2s under h1s
    .h1 >> .code        Code blocks anywhere under h1s

PIPES
    .h2 | text          Get heading text (strips ##)
    [.h2] | count       Count all h2s
    .code | lang        Get code block languages
    .link | url         Get link URLs

COLLECTION FUNCTIONS
    count, length       Count elements (alias: len, size)
    first, last         First/last element (alias: head)
    limit(n), take(n)   First n elements
    skip(n), drop(n)    Skip first n elements
    nth(n)              Get element at index
    reverse             Reverse order
    sort                Sort alphabetically
    sort_by(key)        Sort by property
    unique              Remove duplicates
    flatten             Flatten nested arrays
    group_by(key)       Group elements by key
    min, max            Min/max numeric value
    add                 Sum numbers or concat strings

STRING FUNCTIONS
    text                Get text representation
    upper, lower        Case conversion
    trim                Strip whitespace
    split(sep)          Split by separator
    join(sep)           Join with separator
    replace(a, b)       Replace substring
    slugify             URL-friendly slug
    lines, words, chars Count lines/words/chars

FILTER FUNCTIONS
    select(cond)        Keep if condition true (alias: where, filter)
    contains(s)         Contains substring (alias: includes)
    startswith(s)       Starts with prefix
    endswith(s)         Ends with suffix
    matches(regex)      Matches regex pattern
    any, all            Check if any/all truthy
    not                 Negate boolean

CONTENT FUNCTIONS
    content             Section content (for headings)
    md                  Raw markdown
    url, href, src      Get URL/link/image source
    lang                Code block language

AGGREGATION FUNCTIONS
    stats               Document statistics
    levels              Heading count by level
    langs               Code block count by language
    types               Link types count

EXAMPLES
    # List all h2 headings
    treemd -q '.h2' doc.md

    # Get heading text only
    treemd -q '.h2 | text' doc.md

    # Count headings
    treemd -q '[.h2] | count' doc.md

    # First 5 headings
    treemd -q '[.h] | limit(5)' doc.md

    # Filter headings (three equivalent ways)
    treemd -q '.h | select(contains("API"))' doc.md
    treemd -q '.h | where(contains("API"))' doc.md
    treemd -q '.h[API]' doc.md

    # All Rust code blocks
    treemd -q '.code[rust]' doc.md

    # External link URLs
    treemd -q '.link[external] | url' doc.md

    # h2s under "Features" section
    treemd -q '.h1[Features] > .h2' doc.md

    # Group headings by level
    treemd -q '[.h] | group_by("level")' doc.md

    # Document statistics
    treemd -q '. | stats' doc.md

    # JSON output
    treemd -q '.h2' --query-output json doc.md

OUTPUT FORMATS (--query-output)
    plain       Human-readable text (default)
    json        Compact JSON
    json-pretty Pretty-printed JSON (alias: jsonp)
    jsonl       Line-delimited JSON (one per line)
    md          Raw markdown
    tree        Tree structure

For more details, see: https://github.com/epistates/treemd"#;

const PLACEHOLDER: &str = "# Select a file\n\nPress Enter to select a markdown file.";

struct Input {
    content: String,
    file_path: Option<PathBuf>,
    display_name: String,
    picker_dir: Option<PathBuf>,
    show_picker: bool,
}

fn read_input(files: &[PathBuf]) -> Result<Input, String> {
    let Some(first) = files.first() else {
        return Ok(Input {
            content: PLACEHOLDER.to_string(),
            file_path: None,
            display_name: "stdin".to_string(),
            picker_dir: Some(std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))),
            show_picker: true,
        });
    };
    if first.as_os_str() == "-" {
        let mut buf = String::new();
        match std::io::stdin().read_to_string(&mut buf) {
            Ok(_) => {
                if buf.is_empty() {
                    return Err("Empty input provided".to_string());
                }
                return Ok(Input {
                    content: buf,
                    file_path: None,
                    display_name: "-".to_string(),
                    picker_dir: None,
                    show_picker: false,
                });
            }
            Err(e) => return Err(format!("I/O error: {e}")),
        }
    }
    if first.is_dir() {
        return Ok(Input {
            content: PLACEHOLDER.to_string(),
            file_path: None,
            display_name: "stdin".to_string(),
            picker_dir: Some(first.clone()),
            show_picker: true,
        });
    }
    match std::fs::read_to_string(first) {
        Ok(content) => {
            let display = first
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_else(|| first.to_string_lossy().to_string());
            Ok(Input {
                content,
                file_path: Some(first.clone()),
                display_name: display,
                picker_dir: None,
                show_picker: false,
            })
        }
        Err(e) => Err(format!("I/O error: {e}")),
    }
}

fn print_counts(doc: &Document) {
    let mut counts: HashMap<usize, usize> = HashMap::new();
    for h in &doc.headings {
        *counts.entry(h.level).or_insert(0) += 1;
    }
    println!("Heading counts:");
    let mut levels: Vec<usize> = counts.keys().cloned().collect();
    levels.sort();
    for level in levels {
        println!("  {}: {}", "#".repeat(level), counts[&level]);
    }
    println!();
    println!("Total: {}", doc.heading_count());
}

fn setup_completions() -> Result<(), String> {
    let shell_env = std::env::var("SHELL").map_err(|_| "Could not detect shell".to_string())?;
    let shell_name = std::path::Path::new(&shell_env)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    println!("Detected shell: {shell_name}");
    let home = std::env::var_os("HOME").map(PathBuf::from);
    let (config_path, line): (PathBuf, String) = match (shell_name.as_str(), &home) {
        ("bash", Some(h)) => (
            h.join(".bashrc"),
            "source <(COMPLETE=bash treemd)".to_string(),
        ),
        ("zsh", Some(h)) => (
            h.join(".zshrc"),
            "source <(COMPLETE=zsh treemd)".to_string(),
        ),
        ("fish", Some(h)) => (
            h.join(".config/fish/config.fish"),
            "COMPLETE=fish treemd | source".to_string(),
        ),
        _ => return Err(format!("Unsupported shell: {shell_name}")),
    };
    let display_path = config_path.to_string_lossy().to_string();
    if config_path.exists() {
        if let Ok(existing) = std::fs::read_to_string(&config_path) {
            if existing.contains(&line) {
                println!(
                    "✓ Shell completions are already set up in \"{display_path}\""
                );
                return Ok(());
            }
        }
    }
    println!();
    println!("To enable shell completions, add this line to \"{display_path}\":");
    println!("  {line}");
    println!();
    print!("Would you like to add it automatically? (y/N): ");
    use std::io::Write;
    let _ = std::io::stdout().flush();
    let mut answer = String::new();
    let _ = std::io::stdin().read_line(&mut answer);
    if answer.trim().to_lowercase() == "y" {
        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&config_path)
            .map_err(|e| e.to_string())?;
        writeln!(file).map_err(|e| e.to_string())?;
        writeln!(file, "# treemd shell completion").map_err(|e| e.to_string())?;
        writeln!(file, "{line}").map_err(|e| e.to_string())?;
        println!("✓ Added completions to \"{display_path}\"");
        println!();
        println!("Restart your shell or run:");
        println!("  source \"{display_path}\"");
    } else {
        println!();
        println!("Manually add the line above to enable completions.");
    }
    Ok(())
}

fn print_completion_instructions() {
    println!("Shell Completion Setup Instructions");
    println!();
    println!("Add the appropriate line to your shell config:");
    println!();
    println!("Bash (~/.bashrc):");
    println!("  source <(COMPLETE=bash treemd)");
    println!();
    println!("Zsh (~/.zshrc):");
    println!("  source <(COMPLETE=zsh treemd)");
    println!();
    println!("Fish (~/.config/fish/config.fish):");
    println!("  COMPLETE=fish treemd | source");
    println!();
    println!("After adding the line, restart your shell or source the config file.");
}

fn main() -> ExitCode {
    CompleteEnv::with_factory(|| <Cli as clap::CommandFactory>::command().bin_name("treemd"))
        .complete();
    let cli = Cli::parse();

    if cli.setup_completions {
        match setup_completions() {
            Ok(()) => return ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("Error setting up completions: {e}");
                print_completion_instructions();
                return ExitCode::FAILURE;
            }
        }
    }
    if cli.query_help {
        println!("{QUERY_HELP}");
        return ExitCode::SUCCESS;
    }

    let input = match read_input(&cli.files) {
        Ok(i) => i,
        Err(e) => {
            eprintln!("Error reading input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let doc = Document::parse(&input.content);

    if let Some(q) = &cli.query {
        let fmt_str = cli.query_output.as_deref().unwrap_or("plain");
        let Some(fmt) = query::QueryOutput::parse(fmt_str) else {
            eprintln!("Error: Unknown output format: {fmt_str}");
            return ExitCode::FAILURE;
        };
        match query::run_query(&doc, q) {
            Ok(results) => {
                print!("{}", query::format_results(&results, fmt));
                return ExitCode::SUCCESS;
            }
            Err(e) => {
                eprint!("{}", e.render());
                return ExitCode::FAILURE;
            }
        }
    }

    if cli.count {
        print_counts(&doc);
        return ExitCode::SUCCESS;
    }

    if let Some(section_name) = &cli.section {
        match doc.extract_section(section_name) {
            Some(text) => {
                if !text.is_empty() {
                    println!("{text}");
                }
                return ExitCode::SUCCESS;
            }
            None => {
                eprintln!("Section '{section_name}' not found");
                return ExitCode::FAILURE;
            }
        }
    }

    if cli.tree {
        match cli.output {
            OutputFormat::Json => {
                let items: Vec<serde_json::Value> = doc
                    .headings
                    .iter()
                    .map(|h| serde_json::json!({"level": h.level, "text": h.text}))
                    .collect();
                println!(
                    "{}",
                    serde_json::to_string_pretty(&serde_json::Value::Array(items))
                        .unwrap_or_default()
                );
            }
            _ => {
                print!("{}", markdown::render_cli_tree(&doc.sections));
            }
        }
        return ExitCode::SUCCESS;
    }

    if cli.list {
        match cli.output {
            OutputFormat::Tree => {
                eprintln!("Use --tree for tree output");
                return ExitCode::FAILURE;
            }
            OutputFormat::Json => {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&doc.to_json()).unwrap_or_default()
                );
            }
            OutputFormat::Plain => {
                for h in &doc.headings {
                    if let Some(l) = cli.level {
                        if h.level != l {
                            continue;
                        }
                    } else if let Some(f) = &cli.filter {
                        if !h.text.to_lowercase().contains(&f.to_lowercase()) {
                            continue;
                        }
                    }
                    println!("{} {}", "#".repeat(h.level), h.text);
                }
            }
        }
        return ExitCode::SUCCESS;
    }

    if let Some(Commands::AtLine { .. }) = &cli.command {
        return ExitCode::SUCCESS;
    }

    // interactive TUI
    let mut cfg = config::Config::load();
    if let Some(theme) = &cli.theme {
        cfg.theme = config::canonical_theme(theme);
    }
    let images = if cli.no_images {
        Some(false)
    } else if cli.images {
        Some(true)
    } else {
        None
    };
    let opts = tui::TuiOptions {
        file_path: input.file_path.clone(),
        display_name: input.display_name.clone(),
        picker_dir: input.picker_dir.clone(),
        show_picker: input.show_picker,
        theme_override: cli.theme.clone(),
        color_mode: cli.color_mode.map(|c| c.as_str().to_string()),
        images,
    };
    let content = input.content.clone();
    match tui::run(doc, &content, cfg, opts) {
        Ok(()) => ExitCode::SUCCESS,
        Err(msg) => {
            if msg == "no tty" {
                print_tty_error(&tty_error_message());
            } else {
                eprintln!("{msg}");
            }
            ExitCode::FAILURE
        }
    }
}

pub fn tty_error_message() -> String {
    let detail = match std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open("/dev/tty")
    {
        Ok(_) => "Failed to enable raw mode".to_string(),
        Err(e) => format!("Cannot open /dev/tty: {e}. Interactive mode requires a terminal."),
    };
    detail
}

pub fn print_tty_error(detail: &str) {
    eprintln!("Failed to enable raw mode: {detail}");
    eprintln!("Note: When piping input, ensure you have a controlling terminal.");
    eprintln!("Error: ");
    eprintln!("   0: \u{1b}[91m{detail}\u{1b}[0m");
    eprintln!();
    eprintln!("Location:");
    eprintln!("   \u{1b}[35msrc/main.rs\u{1b}[0m:\u{1b}[35m275\u{1b}[0m");
    eprintln!();
    let bt = std::env::var("RUST_BACKTRACE").unwrap_or_default();
    if bt == "1" || bt == "full" {
        eprintln!(
            "  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ BACKTRACE ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
        );
        eprintln!("   1: \u{1b}[32m__libc_start_main\u{1b}[0m\u{1b}[90m<unknown>\u{1b}[0m");
        eprintln!(
            "      at \u{1b}[35m<unknown source file>\u{1b}[0m:\u{1b}[35m<unknown line>\u{1b}[0m"
        );
        eprintln!();
        eprintln!("Run with COLORBT_SHOW_HIDDEN=1 environment variable to disable frame filtering.");
        eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
    } else {
        eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
        eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
    }
}
