fn try_parse_emphasis(
    p: &mut InlineParser,
    start: usize,
    end: usize,
    marker: char,
    run: usize,
) -> Option<usize> {
    let text = p.text;
    // Find a closing run, skipping balanced nested runs of the other
    // strength (a ** pair inside a * span and vice versa).
    let find_closer = |want: usize, open_end: usize| -> Option<(usize, usize, usize)> {
        // returns (close_start, close_end, close_run)
        let mut i = open_end;
        let mut nested_other = 0usize;
        while i < end {
            let c = char_at(text, i).unwrap();
            if c == '\\' {
                i += 1 + char_at(text, i + 1).map(|n| n.len_utf8()).unwrap_or(0);
                continue;
            }
            if c == '`' {
                let r = count_run(text, i, '`');
                if let Some((_, after)) = find_code_span(text, i, r, end) {
                    i = after;
                    continue;
                }
                i += r;
                continue;
            }
            if c == marker {
                let crun = count_run(text, i, marker);
                let run_start = i;
                let run_end = i + crun * marker.len_utf8();
                let can_open = is_left_flanking(text, run_start, run_end);
                let can_close = is_right_flanking(text, run_start, run_end);
                // Nested span of the other strength: a run that can open a
                // strong span while we look for an em close (or vice versa).
                if want == 1 && crun >= 2 {
                    if nested_other == 0 && can_open && !can_close {
                        nested_other = 1;
                        i = run_end;
                        continue;
                    }
                    if nested_other > 0 && can_close {
                        nested_other -= 1;
                        i = run_end;
                        continue;
                    }
                }
                if crun >= want && can_close {
                    if marker == '_' {
                        if let Some(nc) = char_at(text, run_end) {
                            if nc.is_alphanumeric() {
                                i = run_end;
                                continue;
                            }
                        }
                    }
                    return Some((run_start, run_end, crun));
                }
                i = run_end;
                continue;
            }
            i += c.len_utf8();
        }
        None
    };

    // Triple (or more) runs: strong+em when both sides have >= 3.
    if run >= 3 {
        let open_end = start + 3 * marker.len_utf8();
        if is_left_flanking(text, start, open_end) {
            if let Some((close_start, _close_end, crun)) = find_closer(2, open_end) {
                if crun >= 3 {
                    let close_end = close_start + 3 * marker.len_utf8();
                    p.flush();
                    // surplus opening markers beyond 3 are literal text after the span-open
                    p.events.push(InlineEvent::StartStrong);
                    p.events.push(InlineEvent::StartEm);
                    parse_inline_range(p, open_end, close_start + (crun - 3) * marker.len_utf8());
                    p.flush();
                    p.events.push(InlineEvent::EndEm);
                    p.events.push(InlineEvent::EndStrong);
                    return Some(close_end);
                }
            }
        }
    }

    for want in if run >= 2 { vec![2usize, 1] } else { vec![1usize] } {
        let open_end = start + want * marker.len_utf8();
        if !is_left_flanking(text, start, open_end) {
            continue;
        }
        if marker == '_' {
            if let Some(pc) = prev_char(text, start) {
                if pc.is_alphanumeric() {
                    continue;
                }
            }
        }
        if let Some((close_start, _close_end, crun)) = find_closer(want, open_end) {
            if close_start <= open_end {
                continue;
            }
            // Use the *last* `want` markers of the closing run, so any
            // surplus close markers form part of the content's trailing
            // delimiter handling on the next pass is avoided; simpler:
            // consume want from the start of the closing run and leave
            // the remainder for the outer loop.
            let content_end = close_start;
            let after = close_start + want * marker.len_utf8();
            let _ = crun;
            p.flush();
            if run > want {
                // surplus opening markers are literal text before the span
                let extra: String = std::iter::repeat(marker).take(run - want).collect();
                p.events.push(InlineEvent::Text(extra));
            }
            if want == 2 {
                p.events.push(InlineEvent::StartStrong);
            } else {
                p.events.push(InlineEvent::StartEm);
            }
            parse_inline_range(p, open_end, content_end);
            p.flush();
            if want == 2 {
                p.events.push(InlineEvent::EndStrong);
            } else {
                p.events.push(InlineEvent::EndEm);
            }
            return Some(after);
        }
    }
    None
}

