/// Split image sequences out of an event stream.
/// Returns (filtered events, extracted (alt, src) pairs, index after last image end
/// in the *original* event list).
fn extract_image_events(
    events: &[InlineEvent],
) -> (Vec<InlineEvent>, Vec<(String, String)>, Option<usize>) {
    let mut filtered = Vec::new();
    let mut images = Vec::new();
    let mut last_end: Option<usize> = None;
    let mut i = 0;
    while i < events.len() {
        if let InlineEvent::StartImage { doc_url, .. } = &events[i] {
            let mut alt_events = Vec::new();
            let mut j = i + 1;
            let mut depth = 1;
            while j < events.len() {
                match &events[j] {
                    InlineEvent::StartImage { .. } => depth += 1,
                    InlineEvent::EndImage => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    e => alt_events.push(e.clone()),
                }
                j += 1;
            }
            let alt = events_text_only(&alt_events);
            images.push((alt, doc_url.clone()));
            last_end = Some((j + 1).min(events.len()));
            i = (j + 1).min(events.len());
            continue;
        }
        filtered.push(events[i].clone());
        i += 1;
    }
    // `last_end` indexes the original list; callers that need the tail of
    // the original stream should slice the original events with it.
    (filtered, images, last_end)
}

fn convert_list(
    ordered: bool,
    items: &[ListItemNode],
    refs: &RefMap,
    code_line: usize,
    in_quote: bool,
    loose: bool,
) -> (Block, Vec<Block>) {
    let mut extracted: Vec<Block> = Vec::new();
    let mut out_items: Vec<ListItem> = Vec::new();

    for item in items {
        // Headings escape the list (they are emitted before it).
        let mut filtered: Vec<&Node> = Vec::new();
        for b in &item.blocks {
            if let Node::Heading(h) = b {
                if !in_quote {
                    let events = parse_inline_events(&h.inline_src, refs);
                    let (inline, _c) = convert_inlines(&events, false);
                    let content = heading_title_from_events(&events);
                    extracted.push(Block::Heading {
                        level: h.level,
                        anchor: slugify(&content),
                        content,
                        inline,
                    });
                    continue;
                }
            }
            filtered.push(b);
        }
        if filtered.is_empty() {
            out_items.push(ListItem {
                checked: item.checked,
                content: String::new(),
                inline: vec![],
                blocks: vec![],
            });
            continue;
        }

        let mut content = String::new();
        let mut inline: Vec<Inline> = Vec::new();
        let mut rest_start = 0usize;

        if let Node::Paragraph { text } = filtered[0] {
            rest_start = 1;
            let events = parse_inline_events(text, refs);
            if in_quote {
                let (il, c) = stray_inlines(&events, true);
                inline = il;
                content = c;
            } else {
                let (filtered_events, images, last_end) = extract_image_events(&events);
                for (alt, src) in &images {
                    extracted.push(Block::Image {
                        alt: alt.clone(),
                        src: src.clone(),
                        title: None,
                    });
                }
                if images.is_empty() {
                    let (il, c) = convert_inlines_ex(&events, true, !loose);
                    inline = il;
                    content = c;
                } else {
                    let after = last_end.unwrap_or(events.len());
                    let tail = &events[after..];
                    let has_tail = tail.iter().any(|e| {
                        !matches!(
                            e,
                            InlineEvent::EndStrong
                                | InlineEvent::EndEm
                                | InlineEvent::EndStrike
                        )
                    });
                    content = convert_inlines_ex(tail, true, !loose).1;
                    inline = if has_tail {
                        convert_inlines_ex(&filtered_events, true, !loose).0
                    } else {
                        Vec::new()
                    };
                }
                if loose {
                    // Text from later paragraphs leaks into the item inline.
                    for b in &filtered[1..] {
                        if let Node::Paragraph { text } = b {
                            let ev = parse_inline_events(text, refs);
                            let (more, _) = convert_inlines_ex(&ev, true, false);
                            inline.extend(more);
                        }
                    }
                }
            }
        } else if let Node::Heading(h) = filtered[0] {
            // only reachable in_quote (otherwise headings were extracted)
            rest_start = 1;
            let events = parse_inline_events(&h.inline_src, refs);
            let (il, _c) = stray_inlines(&events, true);
            inline = il;
            content = String::new();
        }

        // Convert the remaining blocks, extracting tables and flattening
        // nested lists into this item.
        let mut rest: Vec<Block> = Vec::new();
        for node in &filtered[rest_start..] {
            for b in convert_node(node, refs, code_line, in_quote) {
                match b {
                    Block::Table { .. } => extracted.push(b),
                    Block::List {
                        items: sub_items, ..
                    } => {
                        for sub in sub_items {
                            if !content.is_empty() {
                                content.push_str("\n  ");
                            } else {
                                content.push_str("  ");
                            }
                            content.push_str(&sub.content);
                            inline.extend(sub.inline);
                            rest.extend(sub.blocks);
                        }
                    }
                    other => rest.push(other),
                }
            }
        }

        out_items.push(ListItem {
            checked: item.checked,
            content,
            inline,
            blocks: rest,
        });
    }
    (
        Block::List {
            ordered,
            items: out_items,
        },
        extracted,
    )
}

/// The content string of a list item as used by the query engine.
pub fn list_item_content(item: &ListItemNode, refs: &RefMap, loose: bool) -> String {
    let filtered: Vec<&Node> = item
        .blocks
        .iter()
        .filter(|b| !matches!(b, Node::Heading(_)))
        .collect();
    let mut content = String::new();
    let mut rest_start = 0usize;
    if let Some(Node::Paragraph { text }) = filtered.first() {
        rest_start = 1;
        let events = parse_inline_events(text, refs);
        let (_f, images, last_end) = extract_image_events(&events);
        if images.is_empty() {
            content = convert_inlines_ex(&events, true, !loose).1;
        } else {
            let after = last_end.unwrap_or(events.len());
            content = convert_inlines_ex(&events[after..], true, !loose).1;
        }
    }
    for node in &filtered[rest_start..] {
        if let Node::List {
            items: sub_items,
            loose: sub_loose,
            ..
        } = node
        {
            for sub in *sub_items {
                if !content.is_empty() {
                    content.push_str("\n  ");
                } else {
                    content.push_str("  ");
                }
                content.push_str(&list_item_content(sub, refs, *sub_loose));
            }
        }
    }
    content
}

