//! Minimal shell quoting: the subset of the shlex API used by clap_complete.
use std::borrow::Cow;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum QuoteError {
    Nul,
}

impl std::fmt::Display for QuoteError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            QuoteError::Nul => f.write_str("cannot shell-quote string containing nul byte"),
        }
    }
}

impl std::error::Error for QuoteError {}

pub fn try_quote(in_str: &str) -> Result<Cow<'_, str>, QuoteError> {
    if in_str.contains('\0') {
        return Err(QuoteError::Nul);
    }
    if in_str.is_empty() {
        return Ok(Cow::Owned("''".to_string()));
    }
    let safe = in_str
        .bytes()
        .all(|b| b.is_ascii_alphanumeric() || b"@%_+=:,./-".contains(&b));
    if safe {
        return Ok(Cow::Borrowed(in_str));
    }
    let mut out = String::with_capacity(in_str.len() + 2);
    out.push('\'');
    for c in in_str.chars() {
        if c == '\'' {
            out.push_str("'\"'\"'");
        } else {
            out.push(c);
        }
    }
    out.push('\'');
    Ok(Cow::Owned(out))
}
