fn complete_markdown_files(current: &std::ffi::OsStr) -> Vec<CompletionCandidate> {
    let current = current.to_string_lossy();
    let path = std::path::Path::new(current.as_ref());
    let (search_dir, prefix, display_base): (PathBuf, String, PathBuf) =
        if current.ends_with('/') {
            (path.to_path_buf(), String::new(), path.to_path_buf())
        } else {
            match (path.parent(), path.file_name()) {
