                    fname.to_string_lossy().to_string(),
                    parent.to_path_buf(),
                ),
                (_, Some(fname)) => (
                    PathBuf::from("."),
                    fname.to_string_lossy().to_string(),
                    PathBuf::new(),
                ),
                _ => (PathBuf::from("."), String::new(), PathBuf::new()),
            }
        };
    let mut entries: Vec<(bool, String)> = Vec::new();
    if let Ok(read) = std::fs::read_dir(&search_dir) {
        for entry in read.filter_map(|e| e.ok()) {
            let name = entry.file_name().to_string_lossy().to_string();
            if !name.starts_with(&prefix) {
                continue;
            }
            let p = entry.path();
            let is_dir = p.is_dir();
            let wanted = is_dir
                || p.extension()
                    .map(|e| e == "md" || e == "markdown")
                    .unwrap_or(false);
            if wanted {
                entries.push((is_dir, name));
            }
        }
    }
    entries.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    entries
        .into_iter()
        .map(|(is_dir, name)| {
            let hidden = name.starts_with('.');
            let mut shown = if display_base.as_os_str().is_empty()
                || display_base == PathBuf::from(".")
            {
                PathBuf::from(&name)
            } else {
                display_base.join(&name)
            };
            if is_dir {
                shown.push("");
            }
            CompletionCandidate::new(shown.as_os_str().to_owned()).hide(hidden)
        })
        .collect()
}'''
