// ---------------- screen buffer ----------------

#[derive(Clone)]
struct Cell {
    text: String,
    style: Style,
    width: usize,
}
struct Buffer {
    w: usize,
    h: usize,
    cells: Vec<Cell>,
    default_style: Style,
}
impl Buffer {
    fn new(w: usize, h: usize, style: Style) -> Self {
        Buffer {
            w,
            h,
            cells: vec![
                Cell {
                    text: " ".into(),
                    style,
                    width: 1
                };
                w.saturating_mul(h)
            ],
            default_style: style,
        }
    }
    fn set(&mut self, x: usize, y: usize, text: &str, style: Style) {
        if x >= self.w || y >= self.h {
            return;
        }
        let width = UnicodeWidthChar::width(text.chars().next().unwrap_or(' ')).unwrap_or(0);
        let width = if width == 0 { 1 } else { width };
        let idx = y * self.w + x;
        self.cells[idx] = Cell {
            text: text.to_string(),
            style,
            width,
        };
        if width == 2 && x + 1 < self.w {
            self.cells[idx + 1] = Cell {
                text: String::new(),
                style,
                width: 0,
            };
        }
    }
    fn draw_text(&mut self, mut x: usize, y: usize, text: &str, style: Style) -> usize {
        for ch in text.chars() {
            if x >= self.w {
                break;
            }
            if ch == '\n' {
                break;
            }
            let wdt = UnicodeWidthChar::width(ch).unwrap_or(0);
            if wdt == 0 {
                // combining character: append to previous cell if possible
                if x > 0 {
                    let idx = y * self.w + x - 1;
                    self.cells[idx].text.push(ch);
                }
                continue;
            }
            self.set(x, y, &ch.to_string(), style);
            x += wdt;
        }
        x
    }
    fn draw_text_clipped(
        &mut self,
        x: usize,
        y: usize,
        max_x: usize,
        text: &str,
        style: Style,
    ) -> usize {
        let mut cx = x;
        for ch in text.chars() {
            if cx >= max_x || cx >= self.w {
                break;
            }
            let wdt = UnicodeWidthChar::width(ch).unwrap_or(0);
            if wdt == 0 {
                continue;
            }
            if cx + wdt > max_x {
                break;
            }
            self.set(cx, y, &ch.to_string(), style);
            cx += wdt;
        }
        cx
    }
    fn fill_rect(&mut self, x: usize, y: usize, w: usize, h: usize, style: Style) {
        for yy in y..(y + h).min(self.h) {
            for xx in x..(x + w).min(self.w) {
                self.set(xx, yy, " ", style);
            }
        }
    }
    fn border(
        &mut self,
        x: usize,
        y: usize,
        w: usize,
        h: usize,
        style: Style,
        title: Option<&str>,
    ) {
        if w < 2 || h < 2 || x >= self.w || y >= self.h {
            return;
        }
        let x2 = (x + w - 1).min(self.w - 1);
        let y2 = (y + h - 1).min(self.h - 1);
        for xx in x..=x2 {
            self.set(xx, y, "─", style);
            self.set(xx, y2, "─", style);
        }
        for yy in y..=y2 {
            self.set(x, yy, "│", style);
            self.set(x2, yy, "│", style);
        }
        self.set(x, y, "┌", style);
        self.set(x2, y, "┐", style);
        self.set(x, y2, "└", style);
        self.set(x2, y2, "┘", style);
        if let Some(t) = title {
            self.draw_text_clipped(x + 1, y, x2, t, style);
        }
    }
    fn render(&self, rgb_mode: bool) -> String {
        let mut out = String::new();
        out.push_str("\x1b[H");
        let mut current: Option<Style> = None;
        for y in 0..self.h {
            for x in 0..self.w {
                let cell = &self.cells[y * self.w + x];
                if cell.width == 0 {
                    continue;
                }
                if current != Some(cell.style) {
                    out.push_str("\x1b[0m");
                    out.push_str(&style_code(cell.style, rgb_mode));
                    current = Some(cell.style);
                }
                out.push_str(&cell.text);
            }
            if y + 1 < self.h {
                out.push_str("\r\n");
            }
        }
        out.push_str("\x1b[0m");
        out
    }
}

fn color_code(c: Color, is_fg: bool, rgb_mode: bool) -> String {
    let base = if is_fg { 38 } else { 48 };
    match c {
        Color::Idx(n) => format!("{base};5;{n}"),
        Color::Rgb(r, g, b) => {
            if rgb_mode {
                format!("{base};2;{r};{g};{b}")
            } else {
                format!("{base};5;{}", rgb_to_256(r, g, b))
            }
        }
    }
}
fn rgb_to_256(r: u8, g: u8, b: u8) -> u8 {
    let q = |v: u8| -> u8 {
        if v < 48 {
            0
        } else if v < 115 {
            1
        } else {
            (v - 35) / 40
        }
    };
    16 + 36 * q(r) + 6 * q(g) + q(b)
}
fn style_code(s: Style, rgb_mode: bool) -> String {
    let mut codes: Vec<String> = Vec::new();
    if s.bold {
        codes.push("1".into());
    }
    if s.italic {
        codes.push("3".into());
    }
    if s.underline {
        codes.push("4".into());
    }
    if s.strike {
        codes.push("9".into());
    }
    codes.push(color_code(s.fg, true, rgb_mode));
    codes.push(color_code(s.bg, false, rgb_mode));
    format!("\x1b[{}m", codes.join(";"))
}

fn text_width(s: &str) -> usize {
    s.chars()
        .map(|c| UnicodeWidthChar::width(c).unwrap_or(0))
        .sum()
}

// ---------------- terminal ----------------

#[derive(Clone, Debug, PartialEq)]
enum Key {
    Char(char),
    Enter,
    Esc,
    Tab,
    BackTab,
    Backspace,
    Delete,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    Ctrl(char),
    Alt(char),
    Unknown,
}

struct Terminal {
    tty: File,
    orig: libc::termios,
}

impl Terminal {
    fn open() -> Result<Terminal, String> {
        let tty = OpenOptions::new()
            .read(true)
            .write(true)
            .open("/dev/tty")
            .map_err(|e| {
                format!("Cannot open /dev/tty: {e}. Interactive mode requires a terminal.")
            })?;
        let fd = tty.as_raw_fd();
        let mut orig: libc::termios = unsafe { std::mem::zeroed() };
        if unsafe { libc::tcgetattr(fd, &mut orig) } != 0 {
            return Err(format!(
                "Cannot open /dev/tty: {}. Interactive mode requires a terminal.",
                std::io::Error::last_os_error()
            ));
        }
        let mut raw = orig;
        unsafe { libc::cfmakeraw(&mut raw) };
        if unsafe { libc::tcsetattr(fd, libc::TCSANOW, &raw) } != 0 {
            return Err(format!(
                "Cannot open /dev/tty: {}. Interactive mode requires a terminal.",
                std::io::Error::last_os_error()
            ));
        }
        Ok(Terminal { tty, orig })
    }
    fn enter(&mut self) {
        let _ = self.tty.write_all(b"\x1b[?1049h\x1b[?25l\x1b[2J\x1b[H");
        let _ = self.tty.flush();
    }
    fn leave(&mut self) {
        let _ = self.tty.write_all(b"\x1b[0m\x1b[?25h\x1b[?1049l");
        let _ = self.tty.flush();
        unsafe {
            libc::tcsetattr(self.tty.as_raw_fd(), libc::TCSANOW, &self.orig);
        }
    }
    fn suspend(&mut self) {
        let _ = self.tty.write_all(b"\x1b[0m\x1b[?25h\x1b[?1049l");
        let _ = self.tty.flush();
        unsafe {
            libc::tcsetattr(self.tty.as_raw_fd(), libc::TCSANOW, &self.orig);
        }
    }
    fn resume(&mut self) {
        let fd = self.tty.as_raw_fd();
        let mut raw = self.orig;
        unsafe { libc::cfmakeraw(&mut raw) };
        unsafe { libc::tcsetattr(fd, libc::TCSANOW, &raw) };
        self.enter();
    }
    fn size(&self) -> (usize, usize) {
        let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
        let r = unsafe {
            libc::ioctl(
                self.tty.as_raw_fd(),
                libc::TIOCGWINSZ,
                &mut ws as *mut libc::winsize,
            )
        };
        if r == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
            (ws.ws_col as usize, ws.ws_row as usize)
        } else {
            (80, 24)
        }
    }
    fn draw(&mut self, buf: &Buffer, rgb_mode: bool) {
        let frame = buf.render(rgb_mode);
        let _ = self.tty.write_all(frame.as_bytes());
        let _ = self.tty.flush();
    }
    fn poll_byte(&mut self, timeout_ms: i32) -> Option<u8> {
        let fd = self.tty.as_raw_fd();
        let mut pfd = libc::pollfd {
            fd,
            events: libc::POLLIN,
            revents: 0,
        };
        let r = unsafe { libc::poll(&mut pfd, 1, timeout_ms) };
        if r <= 0 || (pfd.revents & libc::POLLIN) == 0 {
            return None;
        }
        let mut buf = [0u8; 1];
        match self.tty.read(&mut buf) {
            Ok(1) => Some(buf[0]),
            _ => None,
        }
    }
    fn read_byte(&mut self) -> Option<u8> {
        loop {
            match self.poll_byte(100) {
                Some(b) => return Some(b),
                None => {
                    if RESIZED.swap(false, std::sync::atomic::Ordering::SeqCst) {
                        return None;
                    }
                }
            }
        }
    }
    fn read_key(&mut self) -> Option<Key> {
        let b = self.read_byte()?;
        match b {
            0x1b => {
                let Some(b2) = self.poll_byte(25) else {
                    return Some(Key::Esc);
                };
                match b2 {
                    b'[' => {
                        let mut seq = Vec::new();
                        loop {
                            let Some(c) = self.poll_byte(25) else { break };
                            seq.push(c);
                            if (0x40..=0x7e).contains(&c) {
                                break;
                            }
                            if seq.len() > 16 {
                                break;
                            }
                        }
                        let final_b = seq.last().copied().unwrap_or(b' ');
                        let params = &seq[..seq.len().saturating_sub(1)];
                        Some(match final_b {
                            b'A' => Key::Up,
                            b'B' => Key::Down,
                            b'C' => Key::Right,
                            b'D' => Key::Left,
                            b'H' => Key::Home,
                            b'F' => Key::End,
                            b'Z' => Key::BackTab,
                            b'~' => match params.first() {
                                Some(b'1') | Some(b'7') => Key::Home,
                                Some(b'4') | Some(b'8') => Key::End,
                                Some(b'5') => Key::PageUp,
                                Some(b'6') => Key::PageDown,
                                Some(b'3') => Key::Delete,
                                Some(b'2') => Key::Unknown,
                                _ => Key::Unknown,
                            },
                            _ => Key::Unknown,
                        })
                    }
                    b'O' => match self.poll_byte(25) {
                        Some(b'A') => Some(Key::Up),
                        Some(b'B') => Some(Key::Down),
                        Some(b'C') => Some(Key::Right),
                        Some(b'D') => Some(Key::Left),
                        Some(b'H') => Some(Key::Home),
                        Some(b'F') => Some(Key::End),
                        _ => Some(Key::Unknown),
                    },
                    _ => {
                        // alt + char (decode utf8 if needed)
                        if b2 < 0x80 {
                            Some(Key::Alt(b2 as char))
                        } else {
                            Some(Key::Unknown)
                        }
                    }
                }
            }
            b'\r' | b'\n' => Some(Key::Enter),
            b'\t' => Some(Key::Tab),
            0x7f | 0x08 => Some(Key::Backspace),
            0x00 => Some(Key::Ctrl(' ')),
            0x01..=0x1a => Some(Key::Ctrl((b'a' + b - 1) as char)),
            _ if b < 0x80 => Some(Key::Char(b as char)),
            _ => {
                // UTF-8 sequence
                let len = if b >= 0xf0 {
                    3
                } else if b >= 0xe0 {
                    2
                } else {
                    1
                };
                let mut bytes = vec![b];
                for _ in 0..len {
                    match self.poll_byte(25) {
                        Some(x) => bytes.push(x),
                        None => break,
                    }
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => s.chars().next().map(Key::Char).or(Some(Key::Unknown)),
                    Err(_) => Some(Key::Unknown),
                }
            }
        }
    }
}

static RESIZED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
extern "C" fn on_winch(_sig: i32) {
    RESIZED.store(true, std::sync::atomic::Ordering::SeqCst);
}
