// ---------------- rendered content ----------------

#[derive(Clone)]
struct RSpan {
    text: String,
    style: Style,
    elem: Option<usize>,
}
#[derive(Clone, Default)]
struct RLine {
    spans: Vec<RSpan>,
}
impl RLine {
    fn plain(&self) -> String {
        self.spans.iter().map(|s| s.text.as_str()).collect()
    }
    fn is_blank(&self) -> bool {
        self.plain().trim().is_empty()
    }
}

#[derive(Clone, Debug)]
enum ElemKind {
    Link { text: String, url: String },
    Checkbox {
        section_path: Vec<usize>,
        block_idx: usize,
        item_idx: usize,
        checked: bool,
        global_idx: usize,
    },
    Code { content: String },
    Table {
        section_path: Vec<usize>,
        block_idx: usize,
        global_idx: usize,
    },
}
impl ElemKind {
    fn label(&self) -> &'static str {
        match self {
            ElemKind::Link { .. } => "Link",
            ElemKind::Checkbox { .. } => "Checkbox",
            ElemKind::Code { .. } => "Code",
            ElemKind::Table { .. } => "Table",
        }
    }
}
#[derive(Clone, Debug)]
struct Element {
    kind: ElemKind,
    start_line: usize,
    end_line: usize,
}

struct RenderCtx {
    width: usize,
    theme: Theme,
    current_element: Option<usize>,
    elements: Vec<Element>,
    in_interactive: bool,
    images_enabled: bool,
    table_cell: Option<(usize, usize, usize, bool)>, // element idx, row, col, in table mode
    checkbox_map: HashMap<(Vec<usize>, usize, usize), usize>,
    table_map: HashMap<(Vec<usize>, usize), usize>,
}

impl RenderCtx {
    fn add_element(&mut self, kind: ElemKind, start_line: usize) -> usize {
        let idx = self.elements.len();
        self.elements.push(Element {
            kind,
            start_line,
            end_line: start_line,
        });
        idx
    }
}

fn inlines_to_spans(
    inlines: &[Inline],
    base: Style,
    ctx: &mut RenderCtx,
) -> Vec<RSpan> {
    let theme = ctx.theme;
    let mut out: Vec<RSpan> = Vec::new();
    for inl in inlines {
        match inl {
            Inline::Text { value } => out.push(RSpan {
                text: value.clone(),
                style: base,
                elem: None,
            }),
            Inline::Strong { value } => out.push(RSpan {
                text: value.clone(),
                style: Style::new(theme.strong, base.bg).bold(),
                elem: None,
            }),
            Inline::Emphasis { value } => out.push(RSpan {
                text: value.clone(),
                style: Style::new(theme.emphasis, base.bg).italic(),
                elem: None,
            }),
            Inline::Strikethrough { value } => {
                let mut st = Style::new(idx(245), base.bg);
                st.strike = true;
                out.push(RSpan {
                    text: value.clone(),
                    style: st,
                    elem: None,
                })
            }
            Inline::Code { value } => out.push(RSpan {
                text: value.clone(),
                style: Style::new(theme.code_fg, theme.code_bg),
                elem: None,
            }),
            Inline::Link { text, url, .. } => {
                let id = ctx.add_element(
                    ElemKind::Link {
                        text: text.clone(),
                        url: url.clone(),
                    },
                    0,
                );
                if ctx.in_interactive && ctx.current_element == Some(id) {
                    out.push(RSpan {
                        text: "▸ ".to_string(),
                        style: Style::new(theme.accent, base.bg).bold(),
                        elem: Some(id),
                    });
                }
                out.push(RSpan {
                    text: text.clone(),
                    style: Style::new(theme.link, base.bg).underline(),
                    elem: Some(id),
                });
            }
            Inline::Image { alt, .. } => {
                if ctx.images_enabled {
                    out.push(RSpan {
                        text: alt.clone(),
                        style: Style::new(theme.dim, base.bg).italic(),
                        elem: None,
                    });
                }
            }
        }
    }
    out
}

#[derive(Clone)]
struct CharCell {
    ch: char,
    style: Style,
    elem: Option<usize>,
}

fn spans_to_lines(
    spans: &[RSpan],
    width: usize,
    first_prefix: &str,
    first_style: Style,
    cont_prefix: &str,
) -> Vec<RLine> {
    if width == 0 {
        return vec![];
    }
    // flatten into chars, keeping explicit newlines
    let mut chars: Vec<CharCell> = Vec::new();
    for sp in spans {
        for ch in sp.text.chars() {
            chars.push(CharCell {
                ch,
                style: sp.style,
                elem: sp.elem,
            });
        }
    }
    let mut lines: Vec<RLine> = Vec::new();
    let mut logical_start = 0usize;
    let mut first = true;
    loop {
        let mut logical_end = logical_start;
        while logical_end < chars.len() && chars[logical_end].ch != '\n' {
            logical_end += 1;
        }
        let logical = &chars[logical_start..logical_end];
        // word-wrap this logical line
        let mut idx = 0usize;
        // skip leading spaces at start of a logical line unless it is all spaces
        // (code lines pass their own spans per line; paragraphs are trimmed)
        let mut produced_any = false;
        loop {
            let prefix = if first && !produced_any {
                first_prefix
            } else if produced_any {
                cont_prefix
            } else {
                first_prefix
            };
            let prefix_w = text_width(prefix);
            let avail = width.saturating_sub(prefix_w).max(1);
            // skip spaces at the start of a wrapped continuation
            if produced_any {
                while idx < logical.len() && logical[idx].ch == ' ' {
                    idx += 1;
                }
            }
            if idx >= logical.len() {
                if !produced_any {
                    // an empty logical line
                    let mut line = RLine::default();
                    if !prefix.is_empty() {
                        line.spans.push(RSpan {
                            text: prefix.to_string(),
                            style: first_style,
                            elem: None,
                        });
                    }
                    lines.push(line);
                }
                break;
            }
            // find how much fits
            let mut end = idx;
            let mut w = 0usize;
            let mut last_space: Option<usize> = None;
            while end < logical.len() {
                let cw = UnicodeWidthChar::width(logical[end].ch).unwrap_or(0);
                if logical[end].ch == ' ' {
                    last_space = Some(end);
                }
                if w + cw > avail {
                    break;
                }
                w += cw;
                end += 1;
            }
            let mut line_end = end;
            let mut next_idx = end;
            if end < logical.len() {
                if let Some(sp) = last_space {
                    if sp > idx {
                        line_end = sp;
                        next_idx = sp + 1;
                    }
                }
            }
            // trim trailing spaces in the visible line
            let mut vis_end = line_end;
            while vis_end > idx && logical[vis_end - 1].ch == ' ' {
                vis_end -= 1;
            }
            let mut line = RLine::default();
            if !prefix.is_empty() {
                line.spans.push(RSpan {
                    text: prefix.to_string(),
                    style: first_style,
                    elem: None,
                });
            }
            // group consecutive chars with same style+elem
            let mut cur: Option<RSpan> = None;
            for cc in &logical[idx..vis_end] {
                match &mut cur {
                    Some(s) if s.style == cc.style && s.elem == cc.elem => s.text.push(cc.ch),
                    _ => {
                        if let Some(s) = cur.take() {
                            line.spans.push(s);
                        }
                        cur = Some(RSpan {
                            text: cc.ch.to_string(),
                            style: cc.style,
                            elem: cc.elem,
                        });
                    }
                }
            }
            if let Some(s) = cur {
                line.spans.push(s);
            }
            lines.push(line);
            produced_any = true;
            idx = next_idx;
            if idx >= logical.len() {
                break;
            }
        }
        first = false;
        if logical_end >= chars.len() {
            break;
        }
        logical_start = logical_end + 1;
    }
    if lines.is_empty() {
        lines.push(RLine::default());
    }
    lines
}

fn register_line_elements(lines: &[RLine], base: usize, ctx: &mut RenderCtx) {
    for (off, line) in lines.iter().enumerate() {
        for sp in &line.spans {
            if let Some(eid) = sp.elem {
                if eid < ctx.elements.len() {
                    let e = &mut ctx.elements[eid];
                    if e.start_line == 0 || e.start_line > base + off {
                        e.start_line = base + off;
                    }
                    e.end_line = base + off;
                }
            }
        }
    }
}
