fn render_table_lines(
    headers: &[String],
    rows: &[Vec<String>],
    theme: Theme,
    indent: &str,
    first_prefix: Option<&str>,
    selected_cell: Option<(usize, usize, bool)>, // row (0=header), col, in table mode
) -> Vec<RLine> {
    let cols = headers.len();
    if cols == 0 {
        return vec![];
    }
    let mut widths: Vec<usize> = headers.iter().map(|h| text_width(h)).collect();
    for row in rows {
        for (i, cell) in row.iter().enumerate() {
            if i < cols {
                widths[i] = widths[i].max(text_width(cell));
            }
        }
    }
    let border_style = Style::new(theme.dim, theme.bg);
    let cell_style = Style::new(theme.fg, theme.bg);
    let header_style = Style::new(theme.fg, theme.bg).bold();
    let sel_style = Style::new(theme.selection_fg, theme.selection_bg);

    let make_border = |left: &str, mid: &str, right: &str| -> String {
        let mut s = String::from(left);
        for (i, w) in widths.iter().enumerate() {
            s.push_str(&"─".repeat(w + 2));
            if i + 1 < cols {
                s.push_str(mid);
            }
        }
        s.push_str(right);
        s
    };
    let mut raw_lines: Vec<(String, Option<usize>)> = Vec::new(); // (text, row idx)
    raw_lines.push((make_border("┌", "┬", "┐"), None));
    raw_lines.push((String::new(), Some(0))); // header placeholder
    raw_lines.push((make_border("├", "┼", "┤"), None));
    for r in 0..rows.len() {
        raw_lines.push((String::new(), Some(r + 1)));
    }
    raw_lines.push((make_border("└", "┴", "┘"), None));

    let mut lines = Vec::new();
    for (li, (text, row_idx)) in raw_lines.iter().enumerate() {
        let mut line = RLine::default();
        let selected_row_here = selected_cell
            .map(|(r, _c, in_table)| in_table && Some(r) == *row_idx)
            .unwrap_or(false);
        let prefix = if li == 0 {
            if let Some(fp) = first_prefix {
                fp.to_string()
            } else {
                indent.to_string()
            }
        } else if selected_row_here {
            "→ ".to_string()
        } else {
            indent.to_string()
        };
        if !prefix.is_empty() {
            line.spans.push(RSpan {
                text: prefix,
                style: Style::new(theme.accent, theme.bg),
                elem: None,
            });
        }
        match row_idx {
            None => {
                line.spans.push(RSpan {
                    text: text.clone(),
                    style: border_style,
                    elem: None,
                });
            }
            Some(r) => {
                line.spans.push(RSpan {
                    text: "│".into(),
                    style: border_style,
                    elem: None,
                });
                for c in 0..cols {
                    let cell_text = if *r == 0 {
                        headers.get(c).cloned().unwrap_or_default()
                    } else {
                        rows.get(*r - 1)
                            .and_then(|row| row.get(c))
                            .cloned()
                            .unwrap_or_default()
                    };
                    let is_sel = selected_cell
                        .map(|(sr, sc, in_table)| in_table && sr == *r && sc == c)
                        .unwrap_or(false);
                    let st = if is_sel {
                        sel_style
                    } else if *r == 0 {
                        header_style
                    } else {
                        cell_style
                    };
                    let padded = format!(
                        " {}{} ",
                        cell_text,
                        " ".repeat(widths[c].saturating_sub(text_width(&cell_text)))
                    );
                    line.spans.push(RSpan {
                        text: padded,
                        style: st,
                        elem: None,
                    });
                    line.spans.push(RSpan {
                        text: "│".into(),
                        style: border_style,
                        elem: None,
                    });
                }
            }
        }
        lines.push(line);
    }
    lines
}

fn render_block(
    block: &Block,
    section_path: &[usize],
    block_idx: usize,
    ctx: &mut RenderCtx,
    out: &mut Vec<RLine>,
) {
    let theme = ctx.theme;
    let base = Style::new(theme.fg, theme.bg);
    match block {
        Block::Paragraph { inline, .. } => {
            let elem_before = ctx.elements.len();
            let spans = inlines_to_spans(inline, base, ctx);
            let first_prefix = if ctx.in_interactive
                && spans
                    .iter()
                    .any(|s| s.elem.is_some() && s.elem == ctx.current_element)
            {
                "→ "
            } else {
                ""
            };
            let lines = spans_to_lines(&spans, ctx.width, first_prefix, base, "");
            register_line_elements(&lines, out.len(), ctx);
            let _ = elem_before;
            out.extend(lines);
        }
        Block::Heading {
            level,
            inline,
            content,
            ..
        } => {
            let hstyle = Style::new(
                theme.heading[(*level).clamp(1, 6) - 1],
                theme.bg,
            )
            .bold();
            let spans = if inline.is_empty() {
                vec![RSpan {
                    text: content.clone(),
                    style: hstyle,
                    elem: None,
                }]
            } else {
                inlines_to_spans(inline, hstyle, ctx)
            };
            let lines = spans_to_lines(&spans, ctx.width, "", hstyle, "");
            register_line_elements(&lines, out.len(), ctx);
            out.extend(lines);
        }
        Block::Code {
            language,
            content,
            ..
        } => {
            let eid = ctx.add_element(
                ElemKind::Code {
                    content: content.clone(),
                },
                out.len(),
            );
            ctx.elements[eid].placed = true;
            let is_current = ctx.in_interactive && ctx.current_element == Some(eid);
            let fence = format!("```{}", language.clone().unwrap_or_default());
            let code_style = Style::new(theme.code_fg, theme.bg);
            let mut all: Vec<RLine> = Vec::new();
            let first_prefix = if is_current { "→ " } else { "" };
            all.extend(spans_to_lines(
                &[RSpan {
                    text: fence,
                    style: Style::new(theme.dim, theme.bg).italic(),
                    elem: None,
                }],
                ctx.width,
                first_prefix,
                Style::new(theme.accent, theme.bg),
                "",
            ));
            for cl in content.split('\n') {
                all.extend(spans_to_lines(
                    &[RSpan {
                        text: cl.to_string(),
                        style: code_style,
                        elem: None,
                    }],
                    ctx.width,
                    "",
                    code_style,
                    "",
                ));
            }
            all.extend(spans_to_lines(
                &[RSpan {
                    text: "```".into(),
                    style: Style::new(theme.dim, theme.bg).italic(),
                    elem: None,
                }],
                ctx.width,
                "",
                code_style,
                "",
            ));
            ctx.elements[eid].end_line = out.len() + all.len().saturating_sub(1);
            out.extend(all);
        }
        Block::Table { headers, rows, .. } => {
            let global_idx = ctx
                .table_map
                .get(&(section_path.to_vec(), block_idx))
                .copied()
                .unwrap_or(0);
            let eid = ctx.add_element(
                ElemKind::Table {
                    section_path: section_path.to_vec(),
                    block_idx,
                    global_idx,
                },
                out.len(),
            );
            ctx.elements[eid].placed = true;
            let is_current = ctx.current_element == Some(eid);
            let (sel_cell, indent, first_prefix) = match ctx.table_cell {
                Some((teid, r, c, in_table)) if teid == eid && in_table => {
                    (Some((r, c, true)), "  ", None)
                }
                _ if ctx.in_interactive && is_current => (None, "  ", Some("→ ")),
                _ => (None, "", None),
            };
            let lines = render_table_lines(headers, rows, theme, indent, first_prefix, sel_cell);
            ctx.elements[eid].end_line = out.len() + lines.len().saturating_sub(1);
            out.extend(lines);
        }
        Block::List { ordered, items } => {
            for (idx, item) in items.iter().enumerate() {
                render_list_item(item, *ordered, idx, section_path, block_idx, ctx, out);
            }
        }
        Block::Blockquote { blocks, .. } => {
            for b in blocks {
                if let Block::Paragraph { inline, .. } = b {
                    let qstyle = Style::new(theme.quote, theme.bg).italic();
                    let spans = inlines_to_spans(inline, qstyle, ctx);
                    let lines = spans_to_lines(
                        &spans,
                        ctx.width,
                        "│ ",
                        qstyle,
                        "│ ",
                    );
                    register_line_elements(&lines, out.len(), ctx);
                    out.extend(lines);
                } else {
                    render_block(b, section_path, block_idx, ctx, out);
                }
            }
        }
        Block::HorizontalRule => {
            out.push(RLine {
                spans: vec![RSpan {
                    text: "─".repeat(ctx.width),
                    style: Style::new(theme.dim, theme.bg),
                    elem: None,
                }],
            });
        }
        Block::Image { alt, .. } => {
            if ctx.images_enabled {
                out.push(RLine {
                    spans: vec![RSpan {
                        text: format!("[Image: {alt}]"),
                        style: Style::new(theme.dim, theme.bg).italic(),
                        elem: None,
                    }],
                });
            }
        }
    }
}

fn render_list_item(
    item: &ListItem,
    ordered: bool,
    idx: usize,
    section_path: &[usize],
    block_idx: usize,
    ctx: &mut RenderCtx,
    out: &mut Vec<RLine>,
) {
    let theme = ctx.theme;
    let base = Style::new(theme.fg, theme.bg);
    let checkbox_eid = if let Some(checked) = item.checked {
        let global_idx = ctx
            .checkbox_map
            .get(&(section_path.to_vec(), block_idx, idx))
            .copied()
            .unwrap_or(0);
        let eid = ctx.add_element(
            ElemKind::Checkbox {
                section_path: section_path.to_vec(),
                block_idx,
                item_idx: idx,
                checked,
                global_idx,
            },
            out.len(),
        );
        ctx.elements[eid].placed = true;
        Some(eid)
    } else {
        None
    };
    let is_current = ctx.in_interactive && checkbox_eid.is_some() && ctx.current_element == checkbox_eid;
    let marker = if ordered {
        format!("{}. ", idx + 1)
    } else {
        match item.checked {
            Some(true) => "☑ ".to_string(),
            Some(false) => "☐ ".to_string(),
            None => "• ".to_string(),
        }
    };
    let marker_style = Style::new(theme.accent, theme.bg);
    if item.content.contains('\n') {
        // flattened nested content: render segments as separate lines
        let segments: Vec<&str> = item.content.split('\n').collect();
        for (si, seg) in segments.iter().enumerate() {
            let mut line = RLine::default();
            if si == 0 {
                if is_current {
                    line.spans.push(RSpan {
                        text: "→ ".into(),
                        style: marker_style,
                        elem: checkbox_eid,
                    });
                } else {
                    line.spans.push(RSpan {
                        text: "  ".into(),
                        style: base,
                        elem: None,
                    });
                }
                line.spans.push(RSpan {
                    text: marker.clone(),
                    style: marker_style,
                    elem: checkbox_eid,
                });
                line.spans.push(RSpan {
                    text: seg.trim_start().to_string(),
                    style: base,
                    elem: None,
                });
            } else {
                line.spans.push(RSpan {
                    text: seg.to_string(),
                    style: base,
                    elem: None,
                });
            }
            out.push(line);
        }
    } else {
        let spans = inlines_to_spans(&item.inline, base, ctx);
        let has_current_link = ctx.in_interactive
            && spans
                .iter()
                .any(|s| s.elem.is_some() && s.elem == ctx.current_element);
        let prefix_text = if is_current || has_current_link {
            "→ ".to_string()
        } else {
            "  ".to_string()
        };
        let mut full: Vec<RSpan> = vec![
            RSpan {
                text: prefix_text,
                style: marker_style,
                elem: checkbox_eid,
            },
            RSpan {
                text: marker,
                style: marker_style,
                elem: checkbox_eid,
            },
        ];
        full.extend(spans);
        let lines = spans_to_lines(&full, ctx.width, "", base, "");
        register_line_elements(&lines, out.len(), ctx);
        if let Some(eid) = checkbox_eid {
            ctx.elements[eid].start_line = out.len();
            ctx.elements[eid].end_line = out.len() + lines.len().saturating_sub(1);
            ctx.elements[eid].placed = true;
        }
        out.extend(lines);
    }
    for b in &item.blocks {
        render_block(b, section_path, block_idx, ctx, out);
        out.push(RLine::default());
    }
    // trim trailing separator added for nested blocks
    if !item.blocks.is_empty() {
        while out.last().map(|l| l.is_blank()).unwrap_or(false) {
            out.pop();
        }
    }
}
