                    &self.doc.sections,
                    &mut Vec::new(),
                    0,
                    &search.query.to_lowercase(),
                    &mut out,
                );
                return out;
            }
        }
        let mut out = Vec::new();
        self.collect_entries(&self.doc.sections, &mut Vec::new(), 0, &mut out);
