    fn collect_filtered_entries(
        &self,
        secs: &[Section],
        path: &mut Vec<usize>,
        depth: usize,
        query: &str,
        out: &mut Vec<OutlineEntry>,
    ) -> bool {
        let mut any = false;
        for (i, sec) in secs.iter().enumerate() {
            path.push(i);
            let hidx = self.heading_index_for_path(path);
            let matches = sec.title.to_lowercase().contains(query);
            let mut child_out: Vec<OutlineEntry> = Vec::new();
            let child_any =
                self.collect_filtered_entries(&sec.children, path, depth + 1, query, &mut child_out);
            if matches {
                any = true;
                if let Some(hidx) = hidx {
                    out.push(OutlineEntry {
                        heading: Some(hidx),
                        depth,
                        has_children: !sec.children.is_empty(),
                    });
                    if !self.collapsed.contains(&hidx) {
                        out.extend(child_out);
                    }
                }
            } else if child_any {
                any = true;
                out.extend(child_out);
            }
            path.pop();
        }
        any
    }
    fn collect_todo_entries(
        &self,
        secs: &[Section],
        path: &mut Vec<usize>,
        depth: usize,
        out: &mut Vec<OutlineEntry>,
    ) {
        for (i, sec) in secs.iter().enumerate() {
