                        depth,
                        has_children: !sec.children.is_empty(),
                    });
                    if !self.collapsed.contains(&hidx) {
                        self.collect_todo_entries(&sec.children, path, depth + 1, out);
                    }
                }
            }
            path.pop();
        }
    }
    fn heading_index_for_path(&self, path: &[usize]) -> Option<usize> {
        // Headings are stored in document (preorder) order; compute the
        // preorder index of the section at `path`.
        fn walk(
            secs: &[Section],
            path: &[usize],
            depth: usize,
            counter: &mut usize,
        ) -> Option<usize> {
            for (i, sec) in secs.iter().enumerate() {
                let my = *counter;
                *counter += 1;
                if depth < path.len() && path[depth] == i {
                    if depth + 1 == path.len() {
                        return Some(my);
                    }
                    return walk(&sec.children, path, depth + 1, counter);
                }
                // skip subtree: advance counter over descendants
                fn count_subtree(sec: &Section, counter: &mut usize) {
                    for c in &sec.children {
                        *counter += 1;
                        count_subtree(c, counter);
                    }
                }
                count_subtree(sec, counter);
            }
            None
        }
        walk(&self.doc.sections, path, 0, &mut 0)
    }
    fn section_path_for_heading(&self, target: usize) -> Option<Vec<usize>> {
        fn walk(
            secs: &[Section],
            target: usize,
            counter: &mut usize,
            path: &mut Vec<usize>,
        ) -> Option<Vec<usize>> {
            for (i, sec) in secs.iter().enumerate() {
                let my = *counter;
                *counter += 1;
                path.push(i);
                if my == target {
                    return Some(path.clone());
                }
                if let Some(found) = walk(&sec.children, target, counter, path) {
                    return Some(found);
                }
                path.pop();
            }
            None
        }
        walk(&self.doc.sections, target, &mut 0, &mut Vec::new())
    }
    fn section_at_path<'b>(&'b self, path: &[usize]) -> Option<&'b Section> {
        let mut secs = &self.doc.sections;
        let mut found = None;
        for &i in path {
            found = secs.get(i);
            secs = &found?.children;
        }
        found
    }
    fn section_at_path_mut<'b>(
        doc: &'b mut Document,
        path: &[usize],
    ) -> Option<&'b mut Section> {
        fn step<'b>(secs: &'b mut [Section], path: &[usize]) -> Option<&'b mut Section> {
            if path.is_empty() {
                return None;
            }
            let sec = secs.get_mut(path[0])?;
            if path.len() == 1 {
                Some(sec)
            } else {
                step(&mut sec.children, &path[1..])
            }
        }
        step(&mut doc.sections, path)
    }
}

fn section_has_open_todo(sec: &Section) -> bool {
    fn blocks_have(blocks: &[Block]) -> bool {
        for b in blocks {
            match b {
                Block::List { items, .. } => {
                    for it in items {
                        if it.checked == Some(false) {
                            return true;
                        }
                        if blocks_have(&it.blocks) {
                            return true;
                        }
                    }
                }
                Block::Blockquote { blocks, .. } => {
                    if blocks_have(blocks) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        false
    }
    blocks_have(&sec.blocks)
}
fn section_subtree_has_open_todo(sec: &Section) -> bool {
    section_has_open_todo(sec) || sec.children.iter().any(section_subtree_has_open_todo)
}

fn build_global_maps(
    doc: &Document,
) -> (
    HashMap<(Vec<usize>, usize, usize), usize>,
    HashMap<(Vec<usize>, usize), usize>,
) {
    fn walk_block(
        block: &Block,
        path: &[usize],
        bi: usize,
        cb: &mut usize,
        tb: &mut usize,
        cmap: &mut HashMap<(Vec<usize>, usize, usize), usize>,
        tmap: &mut HashMap<(Vec<usize>, usize), usize>,
    ) {
        match block {
            Block::List { items, .. } => {
                for (ii, item) in items.iter().enumerate() {
                    if item.checked.is_some() {
                        cmap.insert((path.to_vec(), bi, ii), *cb);
                        *cb += 1;
                    }
                    for b in &item.blocks {
                        walk_block(b, path, bi, cb, tb, cmap, tmap);
                    }
                }
            }
            Block::Table { .. } => {
                tmap.insert((path.to_vec(), bi), *tb);
                *tb += 1;
            }
            Block::Blockquote { blocks, .. } => {
                for b in blocks {
                    walk_block(b, path, bi, cb, tb, cmap, tmap);
                }
            }
            _ => {}
        }
    }
    fn walk_secs(
        secs: &[Section],
        path: &mut Vec<usize>,
        cb: &mut usize,
        tb: &mut usize,
        cmap: &mut HashMap<(Vec<usize>, usize, usize), usize>,
        tmap: &mut HashMap<(Vec<usize>, usize), usize>,
    ) {
        for (i, sec) in secs.iter().enumerate() {
            path.push(i);
            for (bi, b) in sec.blocks.iter().enumerate() {
                walk_block(b, path, bi, cb, tb, cmap, tmap);
            }
            walk_secs(&sec.children, path, cb, tb, cmap, tmap);
            path.pop();
        }
    }
    let mut cmap = HashMap::new();
    let mut tmap = HashMap::new();
    walk_secs(
        &doc.sections,
        &mut Vec::new(),
        &mut 0,
        &mut 0,
        &mut cmap,
        &mut tmap,
    );
    (cmap, tmap)
}
