            secs: &[Section],
            target: usize,
            counter: &mut usize,
            path: &mut Vec<usize>,
        ) -> Option<Vec<usize>> {
            for (i, sec) in secs.iter().enumerate() {
                let my = *counter;
                *counter += 1;
                path.push(i);
                if my == target {
                    return Some(path.clone());
                }
                if let Some(found) = walk(&sec.children, target, counter, path) {
