fn section_has_open_todo(sec: &Section) -> bool {
    fn blocks_have(blocks: &[Block]) -> bool {
        for b in blocks {
            match b {
                Block::List { items, .. } => {
                    for it in items {
                        if it.checked == Some(false) {
                            return true;
                        }
                        if blocks_have(&it.blocks) {
                            return true;
                        }
                    }
                }
                Block::Blockquote { blocks, .. } => {
                    if blocks_have(blocks) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        false
    }
    blocks_have(&sec.blocks)
}
fn section_subtree_has_open_todo(sec: &Section) -> bool {
    section_has_open_todo(sec) || sec.children.iter().any(section_subtree_has_open_todo)
}

fn build_global_maps(
    doc: &Document,
) -> (
    HashMap<(Vec<usize>, usize, usize), usize>,
    HashMap<(Vec<usize>, usize), usize>,
) {
    fn walk_block(
        block: &Block,
        path: &[usize],
        bi: usize,
        cb: &mut usize,
        tb: &mut usize,
        cmap: &mut HashMap<(Vec<usize>, usize, usize), usize>,
        tmap: &mut HashMap<(Vec<usize>, usize), usize>,
    ) {
        match block {
            Block::List { items, .. } => {
                for (ii, item) in items.iter().enumerate() {
                    if item.checked.is_some() {
                        cmap.insert((path.to_vec(), bi, ii), *cb);
                        *cb += 1;
                    }
                    for b in &item.blocks {
                        walk_block(b, path, bi, cb, tb, cmap, tmap);
                    }
                }
            }
            Block::Table { .. } => {
                tmap.insert((path.to_vec(), bi), *tb);
                *tb += 1;
            }
            Block::Blockquote { blocks, .. } => {
                for b in blocks {
                    walk_block(b, path, bi, cb, tb, cmap, tmap);
                }
            }
            _ => {}
        }
    }
    fn walk_secs(
        secs: &[Section],
        path: &mut Vec<usize>,
        cb: &mut usize,
        tb: &mut usize,
        cmap: &mut HashMap<(Vec<usize>, usize, usize), usize>,
        tmap: &mut HashMap<(Vec<usize>, usize), usize>,
    ) {
        for (i, sec) in secs.iter().enumerate() {
            path.push(i);
            for (bi, b) in sec.blocks.iter().enumerate() {
                walk_block(b, path, bi, cb, tb, cmap, tmap);
            }
            walk_secs(&sec.children, path, cb, tb, cmap, tmap);
            path.pop();
        }
    }
    let mut cmap = HashMap::new();
    let mut tmap = HashMap::new();
    walk_secs(
        &doc.sections,
        &mut Vec::new(),
        &mut 0,
        &mut 0,
        &mut cmap,
        &mut tmap,
    );
    (cmap, tmap)
}
