fn scrollbar_cells(track: usize, content_len: usize, viewport: usize, pos: usize) -> Vec<char> {
    if track == 0 {
        return vec![];
    }
    if track == 1 {
        return vec!['█'];
    }
    let mut cells = vec!['║'; track];
    cells[0] = '↑';
    cells[track - 1] = '↓';
    if track <= 2 {
        return cells;
    }
    let area = track - 2;
    let (thumb_len, thumb_start) = if content_len <= viewport || content_len == 0 {
        (area, 0)
    } else {
        let len = ((area * viewport) / content_len).max(1).min(area);
        let max_scroll = content_len - viewport;
        let start = if max_scroll == 0 {
            0
        } else {
            ((area - len) * pos.min(max_scroll)) / max_scroll
        };
        (len, start)
    };
    for i in 0..thumb_len {
        cells[1 + thumb_start + i] = '█';
    }
    cells
}

struct SearchMatch {
    line: usize,
    start: usize, // char index
    end: usize,
}

fn find_content_matches(lines: &[RLine], query: &str) -> Vec<SearchMatch> {
    if query.is_empty() {
        return vec![];
    }
    let q = query.to_lowercase();
    let mut out = Vec::new();
    for (li, line) in lines.iter().enumerate() {
        let plain = line.plain().to_lowercase();
        let mut search_from = 0usize;
        while let Some(rel) = plain[search_from..].find(&q) {
            let byte_start = search_from + rel;
            let char_start = plain[..byte_start].chars().count();
            let char_end = char_start + q.chars().count();
            out.push(SearchMatch {
                line: li,
                start: char_start,
                end: char_end,
            });
            search_from = byte_start + q.len().max(1);
            if search_from >= plain.len() {
                break;
            }
        }
    }
    out
}

