impl App {
    fn draw(&mut self, term: &mut Terminal) {
        let (w, h) = term.size();
        if w == 0 || h == 0 {
            return;
        }
        let theme = self.theme;
        let bg_style = Style::new(theme.fg, theme.bg);
        let mut buf = Buffer::new(w, h, bg_style);
        let rgb_mode = self.color_mode == "rgb";

        // Title + separator
        let title = format!(
            "treemd - {} - {} headings",
            self.display_name,
            self.heading_count()
        );
        buf.draw_text(
            0,
            0,
            &title,
            Style::new(theme.accent, theme.bg).bold(),
        );
        if h > 1 {
            buf.draw_text(0, 1, &"─".repeat(w), Style::new(theme.dim, theme.bg));
        }

        let search_h = if self.search.is_some() { 3 } else { 0 };
        let main_y = 2 + search_h;
        let main_h = h.saturating_sub(main_y + 2);
        if let Some(search) = &self.search {
            let (box_title, label) = match search.kind {
                SearchKind::Content => (
                    " Content Search (Tab: switch to Outline) ",
                    "Find:",
                ),
                SearchKind::Outline => (
                    " Outline Search (Tab: switch to Content) ",
                    "Filter:",
                ),
            };
            let border_style = Style::new(theme.dim, theme.bg);
            buf.border(0, 2, w, 3, border_style, Some(box_title));
            let mut line = format!("{label} ");
            line.push_str(&search.query);
            if search.editing {
                line.push('_');
            }
            if search.kind == SearchKind::Content && !search.query.is_empty() {
                let matches = find_content_matches(&self.last_content_lines, &search.query);
                let cur = if matches.is_empty() {
                    0
                } else {
                    search.current_match + 1
                };
                line.push_str(&format!(" [{cur}/{}]", matches.len()));
            }
            line.push_str(if search.editing {
                "  (Esc, Ctrl+U)"
            } else {
                "  (Esc, Tab, /: edit)"
            });
            if h > 3 {
                buf.draw_text_clipped(1, 3, w.saturating_sub(1), &line, bg_style);
            }
        }

        let entries = self.last_outline_entries.clone();
        let outline_w = if self.outline_visible {
            (w * self.outline_width as usize / 100).min(w)
        } else {
            0
        };
        let content_x = if self.outline_visible { outline_w } else { 0 };
        let content_w = w - content_x;

        // outline panel
        if self.outline_visible && outline_w >= 2 && main_h >= 2 {
            let focused = self.focus == Focus::Outline
                && self.interactive.is_none()
                && self.link_mode.is_none()
                && self.table_mode.is_none();
            let border = if focused {
                Style::new(theme.border_focus, theme.bg)
            } else {
                Style::new(theme.border, theme.bg)
            };
            buf.border(0, main_y, outline_w, main_h, border, Some(" Outline "));
            let inner_w = outline_w.saturating_sub(2);
            let inner_h = main_h.saturating_sub(2);
            for row in 0..inner_h {
                let idx = self.outline_scroll + row;
                let y = main_y + 1 + row;
                let Some(entry) = entries.get(idx) else { break };
                let selected = idx == self.selected;
                let style = if selected {
                    Style::new(theme.selection_fg, theme.selection_bg).bold()
                } else {
                    bg_style
                };
                if selected {
                    buf.fill_rect(1, y, outline_w.saturating_sub(2), 1, style);
                }
                let mut fx = 1usize;
                if selected {
                    fx = buf.draw_text_clipped(fx, y, outline_w - 1, "►", style);
                } else {
                    fx += 1;
                }
                // position: one space after cursor, then depth*2, then
                // expand icon (2 cols) or spaces, then heading text
                let heading_col = 2 + entry.depth * 2 + 2; // relative to inner x=0 => screen = 1+heading_col-1
                // screen column for icon:
                let icon_x = 1 + (heading_col - 2);
                let label: String;
                let hstyle;
                match entry.heading {
                    Some(hidx) => {
                        let info = &self.doc.headings[hidx];
                        let bookmarked = self.bookmark == Some(hidx);
                        label = format!(
                            "{}{} {}",
                            if bookmarked { "⚑ " } else { "" },
                            "#".repeat(info.level),
                            info.text
                        );
                        hstyle = if selected {
                            style
                        } else {
                            Style::new(theme.heading[info.level.clamp(1, 6) - 1], theme.bg)
                        };
                        if entry.has_children {
                            let icon = if self.collapsed.contains(&hidx) {
                                "▶"
                            } else {
                                "▼"
                            };
                            buf.draw_text_clipped(
                                icon_x,
                                y,
                                outline_w - 1,
                                icon,
                                if selected { style } else { bg_style },
                            );
                        }
                    }
                    None => {
                        label = "📄 (Document)".to_string();
                        hstyle = if selected { style } else { bg_style };
                        buf.draw_text_clipped(
                            icon_x,
                            y,
                            outline_w - 1,
                            "▼",
                            if selected { style } else { bg_style },
                        );
                    }
                }
                let label_x = 1 + heading_col;
                if entry.heading.is_none() {
                    buf.draw_text_clipped(label_x, y, outline_w - 1, &label, hstyle);
                } else {
                    buf.draw_text_clipped(label_x, y, outline_w - 1, &label, hstyle);
                }
                let _ = fx;
                let _ = inner_w;
            }
            // scrollbar
            if inner_h > 0 && outline_w >= 3 {
                let cells = scrollbar_cells(inner_h, entries.len(), inner_h, self.outline_scroll);
                let sstyle = Style::new(idx(240), theme.bg);
                for (row, ch) in cells.iter().enumerate() {
                    buf.set(outline_w - 2, main_y + 1 + row, &ch.to_string(), sstyle);
                }
            }
        }

        // content panel
        let panel_title = self.content_title();
        let border_style = Style::new(theme.border, theme.bg);
        let content_border = if self.focus == Focus::Content {
            Style::new(theme.border_focus, theme.bg)
        } else {
            border_style
        };
        if content_w >= 2 && main_h >= 2 {
            buf.border(
                content_x,
                main_y,
                content_w,
                main_h,
                content_border,
                Some(&format!(" {panel_title} ")),
            );
            let inner_w = content_w.saturating_sub(2);
            let inner_h = main_h.saturating_sub(2);
            let search_matches: Vec<SearchMatch> =
                if let Some(s) = &self.search {
                    if s.kind == SearchKind::Content {
                        find_content_matches(&self.last_content_lines, &s.query)
                    } else {
                        vec![]
                    }
                } else {
                    vec![]
                };
            let current_match_line = self
                .search
                .as_ref()
                .and_then(|s| search_matches.get(s.current_match).map(|m| m.line));
            for row in 0..inner_h {
                let li = self.content_scroll + row;
                let y = main_y + 1 + row;
                let Some(line) = self.last_content_lines.get(li) else { break };
                draw_rendered_line(
                    &mut buf,
                    content_x + 1,
                    y,
                    content_x + 1 + inner_w,
                    line,
                    &search_matches,
                    li,
                    current_match_line == Some(li),
                    theme,
                );
            }
            if inner_h > 0 && content_w >= 3 {
                let cells = scrollbar_cells(
                    inner_h,
                    self.last_content_lines.len(),
                    inner_h,
                    self.content_scroll,
                );
                let sstyle = Style::new(idx(240), theme.bg);
                for (row, ch) in cells.iter().enumerate() {
                    buf.set(content_x + content_w - 2, main_y + 1 + row, &ch.to_string(), sstyle);
                }
            }
        }

        // overlays
        if self.picker.is_some() {
            self.draw_picker(&mut buf, w, h);
        }
        if self.link_mode.is_some() {
            self.draw_link_navigator(&mut buf, w, h);
        }
        if self.help_scroll.is_some() {
            self.draw_help(&mut buf, w, h);
        }
        if self.palette.is_some() {
            self.draw_palette(&mut buf, w, h);
        }
        if self.edit_cell.is_some() {
            self.draw_edit_cell(&mut buf, w, h);
        }
        if self.confirm.is_some() {
            self.draw_confirm(&mut buf, w, h);
        }

        // footer (drawn after overlays in the original? popups sit above the
        // main area only, footer remains visible)
        if h >= 2 {
            let status = self.status_line();
            buf.fill_rect(0, h - 2, w, 1, bg_style);
            buf.draw_text_clipped(0, h - 2, w, &status, bg_style);
            let help = self.help_line();
            buf.fill_rect(0, h - 1, w, 1, bg_style);
            buf.draw_text_clipped(0, h - 1, w, &help, bg_style);
        }

        term.draw(&buf, rgb_mode);
        let _ = rgb_mode;
        let _ = self.last_elements.len();
    }

    fn content_title(&self) -> String {
        let entries = &self.last_outline_entries;
        let mut title = match entries.get(self.selected) {
            Some(entry) => match entry.heading {
                Some(hidx) => {
                    let t = self.doc.headings[hidx].text.clone();
                    if self.raw_mode {
                        format!("[RAW] {t}")
                    } else {
                        t
                    }
                }
                None => {
                    if self.raw_mode {
                        "[RAW] (Document)".to_string()
                    } else {
                        "(Document)".to_string()
                    }
                }
            },
            None => {
                if self.raw_mode {
                    "[RAW] Content".to_string()
                } else {
                    "Content".to_string()
                }
            }
        };
        if let Some(lm) = &self.link_mode {
            title = format!("{} [Links: {}]", title, lm.links.len());
        }
        title
    }

    fn status_line(&self) -> String {
        if let Some(m) = &self.message {
            return m.clone();
        }
        if let Some(ec) = &self.edit_cell {
            let _ = ec;
        }
        if let Some(ts) = &self.table_mode {
            return format!(
                "[TABLE] Cell({},{}) | hjkl:Move y:Copy Y:CopyRow r:CopyTable Esc:Exit",
                ts.row + 1,
                ts.col + 1
            );
        }
        if let Some(idx) = self.interactive {
            if let Some(elem) = self.last_elements.get(idx) {
                let (label, hint) = match &elem.kind {
                    ElemKind::Link { .. } => ("Link", "Enter:Follow y:Copy Tab:Next Esc:Exit"),
                    ElemKind::Checkbox { .. } => {
                        ("Checkbox", "Space:Toggle Tab:Next Esc:Exit")
                    }
                    ElemKind::Code { .. } => ("Code", "y:Copy Tab:Next Esc:Exit"),
                    ElemKind::Table { .. } => {
                        ("Table", "Enter:Navigate y:Copy Tab:Next Esc:Exit")
                    }
                };
                return format!(
                    "[INTERACTIVE] {}({}/{}) | {}",
                    label,
                    idx + 1,
                    self.last_elements.len(),
                    hint
                );
            }
        }
        if let Some(lm) = &self.link_mode {
            if let Some(link) = lm
                .filtered
                .get(lm.selected)
                .and_then(|i| lm.links.get(*i))
            {
                return format!(
                    " [LINKS] Link {}/{}: \"{}\" → {}  • Theme:{}",
                    lm.selected + 1,
                    lm.filtered.len(),
                    link.text,
                    link.url,
                    theme_display_name(&self.theme_name)
                );
            }
        }
        let width_part = if self.outline_visible {
            format!("Outline:{}%", self.outline_width)
        } else {
            "Outline:Hidden".to_string()
        };
        match self.focus {
            Focus::Outline => {
                let total = self.last_outline_entries.len();
                let percent = if total == 0 {
                    0
                } else {
                    (self.selected + 1) * 100 / total
                };
                let bm = if self.bookmark.is_some() { " ⚑" } else { "" };
                format!(
                    " [Outline] {}/{} ({}%){} • {} • Theme:{}",
                    if total == 0 { 1 } else { self.selected + 1 },
                    total,
                    percent,
                    bm,
                    width_part,
                    theme_display_name(&self.theme_name)
                )
            }
            Focus::Content => {
                let total = self.last_content_lines.len().max(1);
                let percent = (self.content_scroll + 1) * 100 / total;
                format!(
                    " [Content] Line {} ({}%) • {} • Theme:{}",
                    self.content_scroll + 1,
                    percent,
                    width_part,
                    theme_display_name(&self.theme_name)
                )
            }
        }
    }

    fn help_line(&self) -> String {
        if self.palette.is_some() {
            return " j/k Navigate  Enter Select  Esc Cancel".to_string();
        }
        if self.edit_cell.is_some() {
            return " Enter Save  Esc Cancel".to_string();
        }
        if self.table_mode.is_some() {
            return " j/k Row  h/l Col  e Edit  y Copy  Esc Exit Table".to_string();
        }
        if self.link_mode.is_some() {
            return " Tab Next Link  1-9 Jump  Enter Follow  y Copy URL  Esc Exit".to_string();
        }
        if self.interactive.is_some() {
            if let Some(elem) = self
                .interactive
                .and_then(|i| self.last_elements.get(i))
            {
                return match &elem.kind {
                    ElemKind::Link { .. } => {
                        " j/k Navigate  Enter Follow  y Copy URL  Esc Exit".to_string()
                    }
                    ElemKind::Checkbox { .. } => {
                        " j/k Navigate  Space Toggle  Esc Exit".to_string()
                    }
                    ElemKind::Code { .. } => " j/k Navigate  y Copy  Esc Exit".to_string(),
                    ElemKind::Table { .. } => {
                        " j/k Navigate  Enter Enter Table  y Copy  Esc Exit".to_string()
                    }
                };
            }
            return " j/k Navigate  Enter Follow  y Copy URL  Esc Exit".to_string();
        }
        if let Some(s) = &self.search {
            if s.kind == SearchKind::Content {
                return " n/N Next/Prev  Tab Outline Search  Enter Accept  Esc Cancel".to_string();
            }
        }
        match self.focus {
            Focus::Outline => {
                " j/k Navigate  Enter Select  / Search  i Interactive  f Links  ? Help"
                    .to_string()
            }
            Focus::Content => {
                " j/k Scroll  / Search  i Interactive  f Links  y Copy  ? Help".to_string()
            }
        }
    }

    fn draw_help(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(scroll) = self.help_scroll else { return };
        let theme = self.theme;
        let pw = (w * 70 / 100).max(10).min(w);
        let ph = (h * 80 / 100).max(5).min(h);
        let x = (w - pw) / 2;
        let y = (h - ph) / 2;
        buf.fill_rect(x, y, pw, ph, Style::new(theme.fg, theme.bg));
        buf.border(
            x,
            y,
            pw,
            ph,
            Style::new(theme.dim, theme.bg),
            Some(" Help "),
        );
        let lines: Vec<&str> = HELP_TEXT.lines().collect();
        let inner_h = ph.saturating_sub(2);
        for row in 0..inner_h {
            let li = scroll + row;
            let Some(text) = lines.get(li) else { break };
            buf.draw_text_clipped(
                x + 1,
                y + 1 + row,
                x + pw - 2,
                text,
                Style::new(theme.fg, theme.bg),
            );
        }
        if pw >= 3 && inner_h > 0 {
            let cells = scrollbar_cells(inner_h, lines.len(), inner_h, scroll);
            let sstyle = Style::new(idx(240), theme.bg);
            for (row, ch) in cells.iter().enumerate() {
                buf.set(x + pw - 2, y + 1 + row, &ch.to_string(), sstyle);
            }
        }
    }

    fn draw_picker(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(picker) = &self.picker else { return };
        let theme = self.theme;
        let pw = (w * 80 / 100).max(10).min(w);
        let ph = (h * 65 / 100).max(8).min(h);
        let x = (w - pw) / 2;
        let y = (h - ph) / 2;
        buf.fill_rect(x, y, pw, ph, Style::new(theme.fg, theme.bg));
        buf.border(
            x,
            y,
            pw,
            ph,
            Style::new(theme.dim, theme.bg),
            Some(" File Picker "),
        );
        let style = Style::new(theme.fg, theme.bg);
        let header = match &picker.search {
            Some(q) => format!("Search: {q}_  (Esc to cancel)"),
            None => format!(
                "Markdown Files in Current Directory ({} found) - /: search, j/k: navigate",
                picker.filtered.len()
            ),
        };
        let mut row = y + 1;
        // header may wrap onto two lines
        let header_lines = wrap_plain(&header, pw.saturating_sub(2));
        for hl in &header_lines {
            if row < y + ph - 1 {
                buf.draw_text_clipped(x + 1, row, x + pw - 1, hl, style);
                row += 1;
            }
        }
        row += 1;
        let footer_lines = [
            "j/k: Navigate • /: Filter • 1-9: Jump • Enter: Open • Esc: Cancel",
        ];
        let list_bottom = y + ph - 1;
        for vi in 0..picker.filtered.len() {
            if vi < picker.scroll {
                continue;
            }
            if row >= list_bottom {
                break;
            }
            let entry = &picker.entries[picker.filtered[vi]];
            let marker = if vi == picker.selected { "▶" } else { " " };
            let text = format!("{marker} [{}] {}", vi + 1, entry.name);
            let st = if vi == picker.selected {
                Style::new(theme.selection_fg, theme.selection_bg)
            } else {
                style
            };
            buf.draw_text_clipped(x + 1, row, x + pw - 1, &text, st);
            row += 1;
            // blank line between entries
            row += 1;
        }
        let mut fy = list_bottom.saturating_sub(footer_lines.len());
        for fl in footer_lines {
            if fy > y && fy < y + ph {
                buf.draw_text_clipped(x + 1, fy, x + pw - 1, fl, style);
            }
            fy += 1;
        }
    }

    fn draw_link_navigator(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(lm) = &self.link_mode else { return };
        let theme = self.theme;
        let pw = (w * 80 / 100).max(10).min(w);
        let ph = (h * 65 / 100).max(8).min(h);
        let x = (w - pw) / 2;
        let y = (h - ph) / 2;
        buf.fill_rect(x, y, pw, ph, Style::new(theme.fg, theme.bg));
        buf.border(
            x,
            y,
            pw,
            ph,
            Style::new(theme.dim, theme.bg),
            Some(" Link Navigator "),
        );
        let style = Style::new(theme.fg, theme.bg);
        let header = match &lm.search {
            Some(q) => format!("Search: {q}_  (Esc to cancel)"),
            None => format!(
                "Links in this section ({} found) - /: search, Tab/j/k: navigate, Enter: follow",
                lm.filtered.len()
            ),
        };
        let mut row = y + 1;
        for hl in wrap_plain(&header, pw.saturating_sub(2)) {
            if row < y + ph - 1 {
                buf.draw_text_clipped(x + 1, row, x + pw - 1, &hl, style);
                row += 1;
            }
        }
        row += 1;
        let list_bottom = y + ph - 1;
        for vi in 0..lm.filtered.len() {
            if vi < lm.scroll {
                continue;
            }
            if row >= list_bottom {
                break;
            }
            let link = &lm.links[lm.filtered[vi]];
            let marker = if vi == lm.selected { "▶" } else { " " };
            let text = format!("{marker} [{}] {} → {}", vi + 1, link.text, link.url);
            let st = if vi == lm.selected {
                Style::new(theme.selection_fg, theme.selection_bg)
            } else {
                style
            };
            buf.draw_text_clipped(x + 1, row, x + pw - 1, &text, st);
            row += 2;
        }
        let footer = "Tab/j/k: Navigate • /: Search • 1-9: Jump • p: Parent • Enter: Follow • Esc: Cancel";
        let flines = wrap_plain(footer, pw.saturating_sub(2));
        let mut fy = (y + ph - 1).saturating_sub(flines.len());
        for fl in &flines {
            if fy > y && fy < y + ph {
                buf.draw_text_clipped(x + 1, fy, x + pw - 1, fl, style);
            }
            fy += 1;
        }
    }

    fn draw_palette(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(pal) = &self.palette else { return };
        let theme = self.theme;
        let pw = 54.min(w);
        let ph = 15.min(h);
        let x = (w - pw) / 2;
        let y = (h - ph) / 2;
        buf.fill_rect(x, y, pw, ph, Style::new(theme.fg, theme.bg));
        buf.border(x, y, pw, ph, Style::new(theme.dim, theme.bg), None);
        let style = Style::new(theme.fg, theme.bg);
        if ph > 2 {
            buf.draw_text_clipped(x + 1, y + 1, x + pw - 1, "Command Palette", style);
            buf.draw_text_clipped(
                x + 1,
                y + 3,
                x + pw - 1,
                &format!(": {}█", pal.query),
                style,
            );
        }
        let mut row = y + 5;
        if pal.filtered.is_empty() {
            if row < y + ph - 1 {
                buf.draw_text_clipped(x + 1, row, x + pw - 1, "  No matching commands", style);
                row += 2;
                if row < y + ph - 1 {
                    buf.draw_text_clipped(
                        x + 1,
                        row,
                        x + pw - 1,
                        "↑↓/Tab navigate  Enter execute  Esc cancel",
                        style,
                    );
                }
            }
            return;
        }
        for (vi, ci) in pal.filtered.iter().enumerate() {
            if row >= y + ph - 1 {
                break;
            }
            let cmd = &PALETTE_COMMANDS[*ci];
            let marker = if vi == pal.selected { "▸" } else { " " };
            let text = format!("{marker} {} ({})", cmd.name, cmd.aliases);
            buf.draw_text_clipped(x + 1, row, x + pw - 1, &text, style);
            row += 1;
            if vi == pal.selected && row < y + ph - 1 {
                buf.draw_text_clipped(
                    x + 1,
                    row,
                    x + pw - 1,
                    &format!("    {}", cmd.desc),
                    Style::new(theme.dim, theme.bg),
                );
                row += 1;
            }
        }
    }

    fn draw_edit_cell(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(ec) = &self.edit_cell else { return };
        let theme = self.theme;
        let pw = 45.min(w);
        let ph = 5.min(h);
        let x = (w - pw) / 2;
        let y = (h - ph) / 2;
        buf.fill_rect(x, y, pw, ph, Style::new(theme.fg, theme.bg));
        buf.border(x, y, pw, ph, Style::new(theme.dim, theme.bg), None);
        let style = Style::new(theme.fg, theme.bg);
        if ph > 3 {
            buf.draw_text_clipped(x + 1, y + 1, x + pw - 1, "Edit Table Cell", style);
            let label = format!(
                "Edit Cell [{},{}]: {}_",
                ec.row.saturating_sub(1),
                ec.col,
                ec.value
            );
            buf.draw_text_clipped(x + 1, y + 3, x + pw - 1, &label, style);
        }
    }

    fn draw_confirm(&self, buf: &mut Buffer, w: usize, h: usize) {
        let Some(confirm) = &self.confirm else { return };
        let theme = self.theme;
        let style = Style::new(theme.fg, theme.bg);
        match confirm {
            ConfirmKind::CreateFile { display, .. } => {
                let pw = 45.min(w);
                let ph = 7.min(h);
                let x = (w - pw) / 2;
                let y = (h - ph) / 2;
                buf.fill_rect(x, y, pw, ph, style);
                buf.border(
                    x,
                    y,
                    pw,
                    ph,
                    Style::new(theme.dim, theme.bg),
                    Some(" Confirm "),
                );
                let lines = [
                    "Create File?".to_string(),
                    String::new(),
                    format!("File '{display}' does not exist. Create it?"),
                    String::new(),
                    "[y] Create file  [n/Esc] Cancel".to_string(),
                ];
                for (i, line) in lines.iter().enumerate() {
                    if y + 1 + i < y + ph - 1 {
                        let lx = if i == 0 || i == 4 {
                            x + (pw.saturating_sub(text_width(line))) / 2
                        } else {
                            x + 1
                        };
                        buf.draw_text_clipped(lx, y + 1 + i, x + pw - 1, line, style);
                    }
                }
            }
            ConfirmKind::QuitUnsaved => {
                let pw = 50.min(w);
                let ph = 11.min(h);
                let x = (w - pw) / 2;
                let y = (h - ph) / 2;
                buf.fill_rect(x, y, pw, ph, style);
                buf.border(
                    x,
                    y,
                    pw,
                    ph,
                    Style::new(theme.dim, theme.bg),
                    Some(" Confirm Quit "),
                );
                let n = self.pending_edits.len();
                let lines = [
                    "Unsaved Changes".to_string(),
                    String::new(),
                    format!(
                        "You have {} unsaved change{}.",
                        n,
                        if n == 1 { "" } else { "s" }
                    ),
                    "Save before quitting?".to_string(),
                    String::new(),
                    "[y/Enter] Save & Quit".to_string(),
                    "[q] Quit without saving".to_string(),
                    "[Esc] Cancel".to_string(),
                ];
                for (i, line) in lines.iter().enumerate() {
                    if y + 1 + i < y + ph - 1 {
                        let lx = x + (pw.saturating_sub(text_width(line))) / 2;
                        buf.draw_text_clipped(lx, y + 1 + i, x + pw - 1, line, style);
                    }
                }
            }
            ConfirmKind::SaveWidth => {
                let pw = 50.min(w);
                let ph = 9.min(h);
                let x = (w - pw) / 2;
                let y = (h - ph) / 2;
                buf.fill_rect(x, y, pw, ph, style);
                buf.border(
                    x,
                    y,
                    pw,
                    ph,
                    Style::new(theme.dim, theme.bg),
                    Some(" Confirm "),
                );
                let lines = [
                    "Save Outline Width".to_string(),
                    String::new(),
                    format!("Save width {}% to config?", self.outline_width),
                    String::new(),
                    "[y/Enter] Save  [n/Esc] Cancel".to_string(),
                ];
                for (i, line) in lines.iter().enumerate() {
                    if y + 1 + i < y + ph - 1 {
                        let lx = x + (pw.saturating_sub(text_width(line))) / 2;
                        buf.draw_text_clipped(lx, y + 1 + i, x + pw - 1, line, style);
                    }
                }
            }
        }
    }
}

fn draw_rendered_line(
    buf: &mut Buffer,
    x: usize,
    y: usize,
    max_x: usize,
    line: &RLine,
    matches: &[SearchMatch],
    line_idx: usize,
    is_current_match_line: bool,
    theme: Theme,
) {
    // flatten to chars to apply search highlighting
    let mut chars: Vec<(char, Style)> = Vec::new();
    for sp in &line.spans {
        for ch in sp.text.chars() {
            chars.push((ch, sp.style));
        }
    }
    let mut highlights: Vec<Option<Style>> = vec![None; chars.len()];
    for m in matches.iter().filter(|m| m.line == line_idx) {
        let st = if is_current_match_line {
            Style::new(theme.highlight_fg, idx(208))
        } else {
            Style::new(theme.highlight_fg, theme.highlight_bg)
        };
        for i in m.start..m.end.min(chars.len()) {
            highlights[i] = Some(st);
        }
    }
    let mut cx = x;
    for (i, (ch, style)) in chars.iter().enumerate() {
        if cx >= max_x {
            break;
        }
        let st = highlights[i].unwrap_or(*style);
        let wdt = UnicodeWidthChar::width(*ch).unwrap_or(0);
        if wdt == 0 {
            continue;
        }
        if cx + wdt > max_x {
            break;
        }
        buf.set(cx, y, &ch.to_string(), st);
        cx += wdt;
    }
}

fn wrap_plain(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![text.to_string()];
    }
    let mut lines = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    for word in text.split_inclusive(' ') {
        let ww = text_width(word);
        if cur_w > 0 && cur_w + ww > width {
            lines.push(cur.trim_end().to_string());
            cur = String::new();
            cur_w = 0;
        }
        cur.push_str(word);
        cur_w += ww;
    }
    if !cur.is_empty() || lines.is_empty() {
        lines.push(cur.trim_end().to_string());
    }
    lines
}
