                    self.set_message(format!("✗ Error: Heading '{frag}' not found"));
                }
            }
            return;
        }
        if url.starts_with("http://")
            || url.starts_with("https://")
            || url.starts_with("mailto:")
        {
            match open_external(&url) {
                Ok(()) => self.set_message(format!("✓ Opened {url}")),
                Err(()) => self.set_message(format!("✗ Failed to open URL: {url}")),
            }
            return;
        }
        if url.is_empty() {
            // treated like a path based on the current file stem in the original
            let stem = self
                .file_path
                .as_ref()
                .and_then(|p| p.file_stem())
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| "tmp".to_string());
            self.set_message(format!(
                "✗ Failed to open {stem}: no editor found: set $VISUAL or $EDITOR, or install a supported editor"
            ));
            return;
        }
        // split fragment for file links
        let (file_part, frag) = match url.split_once('#') {
            Some((f, fr)) => (f.to_string(), Some(fr.to_string())),
            None => (url.clone(), None),
        };
        let path = Path::new(&file_part);
        if path.is_absolute() {
            self.set_message(
                "✗ Error: Absolute paths are not allowed for security reasons",
            );
            return;
        }
        let is_md = path
            .extension()
            .map(|e| e == "md" || e == "markdown")
            .unwrap_or(false);
        if !is_md {
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_else(|| file_part.clone());
            match find_editor(&self.cfg) {
                Some(_editor) => {
                    self.set_message(format!("Opening {name} in editor is not available here"));
                }
                None => {
                    self.set_message(format!(
                        "✗ Failed to open {name}: no editor found: set $VISUAL or $EDITOR, or install a supported editor"
                    ));
                }
            }
            return;
        }
        let base = self
            .file_path
            .as_ref()
            .and_then(|p| p.parent().map(|p| p.to_path_buf()))
            .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let resolved = base.join(path);
        if !resolved.exists() {
            let display = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_else(|| file_part.clone());
            self.confirm = Some(ConfirmKind::CreateFile {
                path: resolved,
                display,
            });
            return;
        }
        match self.open_file_path(&resolved, true) {
            Ok(()) => {
                if let Some(frag) = frag {
                    if let Some(hidx) = self
                        .doc
                        .headings
                        .iter()
                        .find(|h| slugify(&h.text) == frag)
                        .map(|h| h.index)
                    {
                        let msg = self.message.clone();
                        self.select_heading(hidx);
                        self.message = msg;
                    }
                }
            }
            Err(e) => self.set_message(format!("✗ Error: {e}")),
        }
    }
    fn go_back(&mut self) {
        if let Some(prev) = self.history_back.pop() {
            let cur = HistoryEntry {
                content: self.source.clone(),
                file_path: self.file_path.clone(),
                display_name: self.display_name.clone(),
            };
            self.history_forward.push(cur);
            let display = prev.display_name.clone();
            self.load_content(prev.content, prev.file_path, prev.display_name, false);
            self.set_message(format!("✓ Opened {display}"));
        }
    }
    fn go_forward(&mut self) {
        if let Some(next) = self.history_forward.pop() {
            let cur = HistoryEntry {
                content: self.source.clone(),
                file_path: self.file_path.clone(),
                display_name: self.display_name.clone(),
            };
            self.history_back.push(cur);
            let display = next.display_name.clone();
            self.load_content(next.content, next.file_path, next.display_name, false);
            self.set_message(format!("✓ Opened {display}"));
        }
    }
    fn copy_text(&mut self, _text: &str) {
        match copy_to_clipboard(_text) {
            Ok(()) => self.set_message("✓ Copied to clipboard"),
            Err(()) => self.set_message("✗ Clipboard not available"),
        }
    }
    fn toggle_raw(&mut self) {
        self.raw_mode = !self.raw_mode;
        self.content_scroll = 0;
        self.set_message(if self.raw_mode {
            "Raw source view enabled"
        } else {
            "Rendered view enabled"
        });
    }
    fn cycle_width(&mut self, increase: bool) {
        let widths = [20u16, 30, 40];
        let idx = widths
            .iter()
            .position(|&w| w == self.outline_width)
            .unwrap_or(1);
        let next = if increase {
            widths[(idx + 1) % widths.len()]
        } else {
            widths[(idx + widths.len() - 1) % widths.len()]
        };
        self.outline_width = next;
        self.cfg.outline_width = next;
        let _ = self.cfg.save();
        self.set_message(format!("Width: {next}%"));
    }
    fn save_width(&mut self) {
        self.cfg.outline_width = self.outline_width;
        match self.cfg.save() {
            Ok(()) => self.set_message(format!(
                "✓ Saved outline width {}% to config",
                self.outline_width
            )),
            Err(e) => self.set_message(format!("✗ Failed to save config: {e}")),
        }
    }
    fn toggle_todo_filter(&mut self) {
        self.todo_filter = !self.todo_filter;
        if self.todo_filter {
            let entries = self.outline_entries();
            let n = entries.len();
            // keep the current heading if it is still present
            let cur = self.current_heading();
            self.last_outline_entries = entries.clone();
            match cur.and_then(|h| entries.iter().position(|e| e.heading == Some(h))) {
                Some(pos) => self.selected = pos,
                None => self.selected = 0,
            }
            self.content_scroll = 0;
            self.set_message(format!("Todo filter ON: {n} headings with open todos"));
        } else {
            let cur = self.current_heading();
            self.refresh_outline_selection(cur);
            self.set_message("Todo filter OFF: showing all headings");
        }
    }
    fn start_search(&mut self, kind: SearchKind) {
        self.search = Some(SearchState {
            kind,
            query: String::new(),
            editing: true,
            current_match: 0,
        });
        if kind == SearchKind::Outline {
            self.refresh_outline_selection(self.current_heading());
        }
    }
    fn update_outline_filter(&mut self) {
        // after the outline query changes: select the first entry
        let entries = self.outline_entries();
        self.last_outline_entries = entries;
        self.selected = 0;
        self.outline_scroll = 0;
        self.content_scroll = 0;
    }
    fn quit_requested(&mut self) {
        if !self.pending_edits.is_empty() {
            self.confirm = Some(ConfirmKind::QuitUnsaved);
        } else {
            self.should_quit = true;
        }
    }
    fn save_pending_edits(&mut self, quit_after: bool) {
        if self.pending_edits.is_empty() {
            self.set_message("No changes to save");
            return;
        }
        let Some(path) = self.file_path.clone() else {
            self.set_message("✗ Cannot save: no file loaded");
            return;
        };
        let mut source = self.source.clone();
        let edits = std::mem::take(&mut self.pending_edits);
        let n = edits.len();
        for edit in &edits {
            apply_table_edit(&mut source, edit);
        }
        match std::fs::write(&path, &source) {
            Ok(()) => {
                self.source = source;
                self.undo_stack.clear();
                if quit_after {
                    self.should_quit = true;
                } else {
                    let display = self.display_name.clone();
                    self.set_message(format!(
                        "✓ Saved {} change{} to {}",
                        n,
                        if n == 1 { "" } else { "s" },
                        display
                    ));
                }
            }
            Err(e) => {
                self.pending_edits = edits;
                self.set_message(format!("✗ Failed to save: {e}"));
            }
        }
    }
}

fn open_external(url: &str) -> Result<(), ()> {
    // Roughly mirrors opening with the system opener.
    let mut cmd = std::process::Command::new("xdg-open");
    cmd.arg(url);
    match cmd.spawn() {
        Ok(mut child) => match child.wait() {
            Ok(status) if status.success() => Ok(()),
            _ => Err(()),
        },
        Err(_) => Err(()),
    }
}

fn find_editor(cfg: &Config) -> Option<String> {
    if let Some(editor) = &cfg.editor {
        if !editor.is_empty() {
            return Some(editor.clone());
        }
    }
    for var in ["VISUAL", "EDITOR"] {
        if let Ok(val) = std::env::var(var) {
            if !val.trim().is_empty() {
                return Some(val);
            }
        }
    }
    for candidate in ["nvim", "vim", "nano", "emacs", "micro", "helix", "hx", "code"] {
        if which_in_path(candidate) {
            return Some(candidate.to_string());
        }
    }
    None
}

fn which_in_path(name: &str) -> bool {
    if let Ok(paths) = std::env::var("PATH") {
        for dir in paths.split(':') {
            let candidate = Path::new(dir).join(name);
            if candidate.is_file() {
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    if let Ok(md) = std::fs::metadata(&candidate) {
                        if md.permissions().mode() & 0o111 != 0 {
                            return true;
                        }
                        continue;
                    }
                }
                return true;
            }
        }
    }
    false
}

fn copy_to_clipboard(text: &str) -> Result<(), ()> {
    let has_display = std::env::var("WAYLAND_DISPLAY")
        .map(|v| !v.is_empty())
        .unwrap_or(false)
        || std::env::var("DISPLAY").map(|v| !v.is_empty()).unwrap_or(false);
    if !has_display {
        return Err(());
    }
    let tools: &[(&str, &[&str])] = &[
        ("wl-copy", &[]),
        ("xclip", &["-selection", "clipboard"]),
        ("xsel", &["--clipboard", "--input"]),
        ("pbcopy", &[]),
    ];
    for (tool, args) in tools {
        if which_in_path(tool) {
            let mut cmd = std::process::Command::new(tool);
            cmd.args(*args)
                .stdin(std::process::Stdio::piped())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null());
            if let Ok(mut child) = cmd.spawn() {
                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(text.as_bytes());
                }
                if let Ok(status) = child.wait() {
                    if status.success() {
                        return Ok(());
                    }
                }
            }
            return Err(());
        }
    }
    Err(())
}

/// Replace a table cell in the source text. Finds the `global_table`-th
/// table (header line followed by a delimiter line) and rewrites the cell.
fn apply_table_edit(source: &mut String, edit: &PendingEdit) {
    let mut lines: Vec<String> = source.lines().map(|l| l.to_string()).collect();
    let had_trailing_newline = source.ends_with('\n');
    let mut table_idx = 0usize;
    let mut i = 0usize;
    while i + 1 < lines.len() {
        let is_delim = {
            let l = &lines[i + 1];
            l.contains("---") && l.trim().chars().all(|c| matches!(c, '|' | '-' | ':' | ' '))
        };
        if lines[i].contains('|') && is_delim {
            if table_idx == edit.global_table {
                let target_line = if edit.row == 0 {
                    i
                } else {
                    i + 1 + edit.row
                };
                if target_line < lines.len() {
                    lines[target_line] = replace_table_cell(&lines[target_line], edit.col, &edit.new);
                }
                break;
            }
            table_idx += 1;
            i += 2;
            while i < lines.len() && lines[i].contains('|') {
                i += 1;
            }
            continue;
        }
        i += 1;
    }
    let mut out = lines.join("\n");
    if had_trailing_newline {
        out.push('\n');
    }
    *source = out;
}

fn replace_table_cell(line: &str, col: usize, new: &str) -> String {
    // Split on unescaped pipes, keeping segment spans.
    let mut segments: Vec<(usize, usize)> = Vec::new();
    let bytes = line.as_bytes();
    let mut start = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if bytes[i] == b'|' {
            segments.push((start, i));
            start = i + 1;
        }
        i += 1;
    }
    segments.push((start, line.len()));
    // segments[0] is before the first pipe; cell c is segments[c+1]
    let Some(&(s, e)) = segments.get(col + 1) else {
        return line.to_string();
    };
    let seg = &line[s..e];
    let leading_len = seg.len() - seg.trim_start().len();
    let trailing_len = seg.len() - seg.trim_end().len();
    let leading = &seg[..leading_len];
    let trailing = if trailing_len > 0 {
        &seg[seg.len() - trailing_len..]
    } else {
        " "
    };
    let leading = if leading.is_empty() { " " } else { leading };
    format!("{}{leading}{new}{trailing}{}", &line[..s], &line[e..])
}

/// Toggle the `idx`-th checkbox marker in the source (0-based, document order).
fn toggle_checkbox_in_source(source: &mut String, idx: usize) -> bool {
    let mut count = 0usize;
    let mut in_fence = false;
    let mut search_from = 0usize;
    let src = source.clone();
    for line in src.split_inclusive('\n') {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            in_fence = !in_fence;
            search_from += line.len();
            continue;
        }
        if !in_fence {
            for pat in ["- [ ]", "- [x]", "- [X]", "* [ ]", "* [x]", "* [X]"] {
                if let Some(pos) = line.find(pat) {
                    if count == idx {
                        let at = search_from + pos + 2; // byte index of the char inside brackets offset by pattern
                        let bracket_at = search_from + pos + 3;
                        let cur = src.as_bytes()[bracket_at] as char;
                        let replacement = if cur == ' ' { "x" } else { " " };
                        let _ = at;
                        source.replace_range(bracket_at..bracket_at + 1, replacement);
                        return true;
                    }
                    count += 1;
                    break;
                }
            }
        }
        search_from += line.len();
    }
    false
}
