// ---------------- key handling ----------------

impl App {
    fn handle_key(&mut self, key: Key, term: &mut Terminal, viewport_h: usize) {
        // most keys clear a transient message first
        let had_message = self.message.take();

        if self.confirm.is_some() {
            self.message = None;
            self.handle_confirm_key(key);
            return;
        }
        if self.edit_cell.is_some() {
            self.message = None;
            self.handle_edit_cell_key(key);
            return;
        }
        if self.picker.is_some() {
            self.handle_picker_key(key);
            return;
        }
        if self.palette.is_some() {
            self.handle_palette_key(key);
            return;
        }
        if self.help_scroll.is_some() {
            match key {
                Key::Esc => self.help_scroll = None,
                Key::Char('?') => self.help_scroll = None,
                Key::Char('j') | Key::Down => {
                    let max = HELP_TEXT.lines().count().saturating_sub(1);
                    if let Some(s) = &mut self.help_scroll {
                        *s = (*s + 1).min(max);
                    }
                }
                Key::Char('k') | Key::Up => {
                    if let Some(s) = &mut self.help_scroll {
                        *s = s.saturating_sub(1);
                    }
                }
                Key::Char('q') => self.help_scroll = None,
                _ => {
                    self.message = had_message;
                }
            }
            return;
        }

        // search editing / accepted handling
        if let Some(search) = &self.search {
            if search.editing {
                self.message = None;
                self.handle_search_editing_key(key);
                return;
            }
        }
        if self.search.is_some() {
            // accepted search mode
            match key {
                Key::Esc => {
                    self.search = None;
                    self.refresh_outline_selection(self.current_heading());
                    return;
                }
                Key::Tab => {
                    let query = self.search.as_ref().unwrap().query.clone();
                    let kind = self.search.as_ref().unwrap().kind;
                    let new_kind = match kind {
                        SearchKind::Content => SearchKind::Outline,
                        SearchKind::Outline => SearchKind::Content,
                    };
                    self.search = Some(SearchState {
                        kind: new_kind,
                        query,
                        editing: true,
                        current_match: 0,
                    });
                    if new_kind == SearchKind::Outline {
                        self.update_outline_filter();
                    }
                    return;
                }
                Key::Char('/') => {
                    if let Some(s) = &mut self.search {
                        s.editing = true;
                    }
                    return;
                }
                Key::Char('n') if self.search.as_ref().map(|s| s.kind) == Some(SearchKind::Content) => {
                    self.jump_search_match(true, viewport_h);
                    return;
                }
                Key::Char('N') if self.search.as_ref().map(|s| s.kind) == Some(SearchKind::Content) => {
                    self.jump_search_match(false, viewport_h);
                    return;
                }
                _ => {}
            }
        }

        if self.table_mode.is_some() {
            self.message = None;
            self.handle_table_key(key);
            return;
        }
        if self.link_mode.is_some() {
            self.handle_link_key(key);
            return;
        }
        if self.interactive.is_some() {
            // keep the interactive status line, drop transients on action
            self.handle_interactive_key(key, viewport_h);
            return;
        }
        self.handle_normal_key(key, term, viewport_h);
    }

    fn handle_confirm_key(&mut self, key: Key) {
        let Some(confirm) = self.confirm.take() else { return };
        match confirm {
            ConfirmKind::CreateFile { path, display } => match key {
                Key::Char('y') | Key::Char('Y') => {
                    let stem = path
                        .file_stem()
                        .map(|s| s.to_string_lossy().to_string())
                        .unwrap_or_else(|| "untitled".to_string());
                    let initial = format!("# {stem}\n\n");
                    match std::fs::write(&path, &initial) {
                        Ok(()) => match self.open_file_path(&path, true) {
                            Ok(()) => {
                                self.set_message(format!("✓ Created and opened {display}"));
                            }
                            Err(e) => self.set_message(format!("✗ Error: {e}")),
                        },
                        Err(e) => self.set_message(format!("✗ Failed to create file: {e}")),
                    }
                }
                _ => {}
            },
            ConfirmKind::QuitUnsaved => match key {
                Key::Char('y') | Key::Char('Y') | Key::Enter => {
                    self.save_pending_edits(true);
                    if !self.pending_edits.is_empty() {
                        // save failed; stay open
                        self.should_quit = false;
                    }
                }
                Key::Char('q') => {
                    self.should_quit = true;
                }
                Key::Esc => {}
                _ => {
                    self.confirm = Some(ConfirmKind::QuitUnsaved);
                }
            },
            ConfirmKind::SaveWidth => match key {
                Key::Char('y') | Key::Char('Y') | Key::Enter => self.save_width(),
                _ => {}
            },
        }
    }

    fn handle_edit_cell_key(&mut self, key: Key) {
        let Some(mut ec) = self.edit_cell.take() else { return };
        match key {
            Key::Enter => {
                // commit the edit to the document model + pending edits
                if let Some(elem) = self.last_elements.get(ec.element).cloned() {
                    if let ElemKind::Table {
                        section_path,
                        block_idx,
                        global_idx,
                    } = &elem.kind
                    {
                        let old = {
                            let sec = Self::section_at_path_mut(&mut self.doc, section_path);
                            let mut old = String::new();
                            if let Some(sec) = sec {
                                if let Some(Block::Table { headers, rows, .. }) =
                                    sec.blocks.get_mut(*block_idx)
                                {
                                    if ec.row == 0 {
                                        if let Some(cell) = headers.get_mut(ec.col) {
                                            old = cell.clone();
                                            *cell = ec.value.clone();
                                        }
                                    } else if let Some(cell) = rows
                                        .get_mut(ec.row - 1)
                                        .and_then(|r| r.get_mut(ec.col))
                                    {
                                        old = cell.clone();
                                        *cell = ec.value.clone();
                                    }
                                }
                            }
                            old
                        };
                        if old != ec.value {
                            let edit = PendingEdit {
                                global_table: *global_idx,
                                section_path: section_path.clone(),
                                block_idx: *block_idx,
                                row: ec.row,
                                col: ec.col,
                                old,
                                new: ec.value.clone(),
                            };
                            self.undo_stack.push(edit.clone());
                            self.pending_edits.push(edit);
                        }
                    }
                }
                let n = self.pending_edits.len();
                // return to table mode on the same element
                self.table_mode = Some(TableState {
                    element: ec.element,
                    row: ec.row,
                    col: ec.col,
                });
                self.set_message(format!(
                    "✓ Cell updated ({} unsaved change{})",
                    n,
                    if n == 1 { "" } else { "s" }
                ));
            }
            Key::Esc => {
                self.table_mode = Some(TableState {
                    element: ec.element,
                    row: ec.row,
                    col: ec.col,
                });
                self.set_message("Editing cancelled");
            }
            Key::Backspace => {
                ec.value.pop();
                self.edit_cell = Some(ec);
            }
            Key::Ctrl('u') => {
                ec.value.clear();
                self.edit_cell = Some(ec);
            }
            Key::Char(c) => {
                ec.value.push(c);
                self.edit_cell = Some(ec);
            }
            _ => {
                self.edit_cell = Some(ec);
            }
        }
    }

    fn handle_picker_key(&mut self, key: Key) {
        let Some(mut picker) = self.picker.take() else { return };
        if let Some(mut query) = picker.search.clone() {
            match key {
                Key::Esc => {
                    picker.search = None;
                    picker.filtered = (0..picker.entries.len()).collect();
                    picker.selected = 0;
                    picker.scroll = 0;
                    self.picker = Some(picker);
                }
                Key::Enter => {
                    picker.search = Some(query);
                    self.picker = Some(picker);
                    // Enter while searching opens the selection
                    self.picker_open_selected();
                }
                Key::Backspace => {
                    query.pop();
                    picker.filtered = picker
                        .entries
                        .iter()
                        .enumerate()
                        .filter(|(_, e)| fuzzy_match(&query, &e.name))
                        .map(|(i, _)| i)
                        .collect();
                    picker.selected = 0;
                    picker.search = Some(query);
                    self.picker = Some(picker);
                }
                Key::Ctrl('u') => {
                    picker.filtered = (0..picker.entries.len()).collect();
                    picker.selected = 0;
                    picker.search = Some(String::new());
                    self.picker = Some(picker);
                }
                Key::Char(c) => {
                    query.push(c);
                    picker.filtered = picker
                        .entries
                        .iter()
                        .enumerate()
                        .filter(|(_, e)| fuzzy_match(&query, &e.name))
                        .map(|(i, _)| i)
                        .collect();
                    picker.selected = 0;
                    picker.search = Some(query);
                    self.picker = Some(picker);
                }
                Key::Down => {
                    if !picker.filtered.is_empty() {
                        picker.selected = (picker.selected + 1).min(picker.filtered.len() - 1);
                    }
                    picker.search = Some(query);
                    self.picker = Some(picker);
                }
                Key::Up => {
                    picker.selected = picker.selected.saturating_sub(1);
                    picker.search = Some(query);
                    self.picker = Some(picker);
                }
                _ => {
                    picker.search = Some(query);
                    self.picker = Some(picker);
                }
            }
            return;
        }
        match key {
            Key::Esc => {
                // cancel picker
            }
            Key::Char('j') | Key::Down => {
                if !picker.filtered.is_empty() {
                    picker.selected = (picker.selected + 1).min(picker.filtered.len() - 1);
                }
                self.picker = Some(picker);
            }
            Key::Char('k') | Key::Up => {
                picker.selected = picker.selected.saturating_sub(1);
                self.picker = Some(picker);
            }
            Key::Char('/') => {
                picker.search = Some(String::new());
                self.picker = Some(picker);
            }
            Key::Char(c) if ('1'..='9').contains(&c) => {
                let n = c as usize - '1' as usize;
                if n < picker.filtered.len() {
                    picker.selected = n;
                }
                self.picker = Some(picker);
            }
            Key::Enter => {
                self.picker = Some(picker);
                self.picker_open_selected();
            }
            Key::Char('q') => {}
            _ => {
                self.picker = Some(picker);
            }
        }
    }
    fn picker_open_selected(&mut self) {
        let Some(picker) = self.picker.take() else { return };
        let Some(&entry_idx) = picker.filtered.get(picker.selected) else {
            self.picker = Some(picker);
            return;
        };
        let path = picker.entries[entry_idx].path.clone();
        if let Err(e) = self.open_file_path(&path, true) {
            self.set_message(format!("✗ Error: {e}"));
            self.picker = Some(picker);
        }
    }

    fn handle_palette_key(&mut self, key: Key) {
        let Some(mut pal) = self.palette.take() else { return };
        match key {
            Key::Esc => {}
            Key::Down => {
                if !pal.filtered.is_empty() {
                    pal.selected = (pal.selected + 1) % pal.filtered.len();
                }
                self.palette = Some(pal);
            }
            Key::Up => {
                if !pal.filtered.is_empty() {
                    pal.selected = (pal.selected + pal.filtered.len() - 1) % pal.filtered.len();
                }
                self.palette = Some(pal);
            }
            Key::Tab => {
                if !pal.filtered.is_empty() {
                    pal.selected = (pal.selected + 1) % pal.filtered.len();
                }
                self.palette = Some(pal);
            }
            Key::BackTab => {
                if !pal.filtered.is_empty() {
                    pal.selected = (pal.selected + pal.filtered.len() - 1) % pal.filtered.len();
                }
                self.palette = Some(pal);
            }
            Key::Enter => {
                if let Some(&ci) = pal.filtered.get(pal.selected) {
                    let id = PALETTE_COMMANDS[ci].id;
                    self.execute_palette_command(id);
                }
            }
            Key::Backspace => {
                pal.query.pop();
                pal.filtered = filter_palette(&pal.query);
                pal.selected = 0;
                self.palette = Some(pal);
            }
            Key::Ctrl('u') => {
                pal.query.clear();
                pal.filtered = filter_palette(&pal.query);
                pal.selected = 0;
                self.palette = Some(pal);
            }
            Key::Char(c) => {
                pal.query.push(c);
                pal.filtered = filter_palette(&pal.query);
                pal.selected = 0;
                self.palette = Some(pal);
            }
            _ => {
                self.palette = Some(pal);
            }
        }
    }
    fn execute_palette_command(&mut self, id: &str) {
        match id {
            "save" => self.save_pending_edits(false),
            "undo" => {
                if let Some(edit) = self.undo_stack.pop() {
                    // revert in the model and drop from pending list
                    if let Some(sec) =
                        Self::section_at_path_mut(&mut self.doc, &edit.section_path)
                    {
                        if let Some(Block::Table { headers, rows, .. }) =
                            sec.blocks.get_mut(edit.block_idx)
                        {
                            if edit.row == 0 {
                                if let Some(cell) = headers.get_mut(edit.col) {
                                    *cell = edit.old.clone();
                                }
                            } else if let Some(cell) = rows
                                .get_mut(edit.row - 1)
                                .and_then(|r| r.get_mut(edit.col))
                            {
                                *cell = edit.old.clone();
                            }
                        }
                    }
                    self.pending_edits.retain(|e| {
                        !(e.global_table == edit.global_table
                            && e.row == edit.row
                            && e.col == edit.col
                            && e.new == edit.new)
                    });
                    self.set_message("✓ Edit undone");
                } else {
                    self.set_message("Nothing to undo");
                }
            }
            "savewidth" => self.save_width(),
            "outline" => self.toggle_outline(),
            "help" => {
                self.help_scroll = Some(0);
            }
            "raw" => self.toggle_raw(),
            "top" => {
                self.selected = 0;
                self.content_scroll = 0;
                self.outline_scroll = 0;
            }
            "bottom" => {
                let entries = self.outline_entries();
                self.last_outline_entries = entries.clone();
                if !entries.is_empty() {
                    self.selected = entries.len() - 1;
                    self.content_scroll = 0;
                }
            }
            _ => {}
        }
    }
    fn toggle_outline(&mut self) {
        self.outline_visible = !self.outline_visible;
        if self.outline_visible {
            self.focus = Focus::Outline;
        } else {
            self.focus = Focus::Content;
        }
    }

    fn handle_search_editing_key(&mut self, key: Key) {
        let kind = self.search.as_ref().map(|s| s.kind);
        match key {
            Key::Esc => {
                self.search = None;
                self.refresh_outline_selection(self.current_heading());
            }
            Key::Enter => {
                if let Some(s) = &mut self.search {
                    s.editing = false;
                }
            }
            Key::Tab => {
                let (query, kind) = {
                    let s = self.search.as_ref().unwrap();
                    (s.query.clone(), s.kind)
                };
                let new_kind = match kind {
                    SearchKind::Content => SearchKind::Outline,
                    SearchKind::Outline => SearchKind::Content,
                };
                self.search = Some(SearchState {
                    kind: new_kind,
                    query,
                    editing: true,
                    current_match: 0,
                });
                if new_kind == SearchKind::Outline {
                    self.update_outline_filter();
                }
            }
            Key::Backspace => {
                if let Some(s) = &mut self.search {
                    s.query.pop();
                    s.current_match = 0;
                }
                if kind == Some(SearchKind::Outline) {
                    let cur = self.current_heading();
                    let entries = self.outline_entries();
                    self.last_outline_entries = entries.clone();
                    match cur.and_then(|h| entries.iter().position(|e| e.heading == Some(h))) {
                        Some(pos) => self.selected = pos,
                        None => self.selected = 0,
                    }
                    self.content_scroll = 0;
                }
            }
            Key::Ctrl('u') => {
                if let Some(s) = &mut self.search {
                    s.query.clear();
                    s.current_match = 0;
                }
                if kind == Some(SearchKind::Outline) {
                    let cur = self.current_heading();
                    let entries = self.outline_entries();
                    self.last_outline_entries = entries.clone();
                    if let Some(pos) =
                        cur.and_then(|h| entries.iter().position(|e| e.heading == Some(h)))
                    {
                        self.selected = pos;
                    }
                }
            }
            Key::Down => {
                if kind == Some(SearchKind::Outline) {
                    self.move_outline(1);
                    if let Some(s) = &mut self.search {
                        s.editing = true;
                    }
                }
            }
            Key::Up => {
                if kind == Some(SearchKind::Outline) {
                    self.move_outline(-1);
                    if let Some(s) = &mut self.search {
                        s.editing = true;
                    }
                }
            }
            Key::Char(c) => {
                if let Some(s) = &mut self.search {
                    s.query.push(c);
                    s.current_match = 0;
                }
                if kind == Some(SearchKind::Outline) {
                    self.update_outline_filter();
                }
            }
            _ => {}
        }
    }
    fn jump_search_match(&mut self, forward: bool, _viewport: usize) {
        let matches = match &self.search {
            Some(s) if s.kind == SearchKind::Content => {
                find_content_matches(&self.last_content_lines, &s.query)
            }
            _ => return,
        };
        if matches.is_empty() {
            return;
        }
        if let Some(s) = &mut self.search {
            if forward {
                s.current_match = (s.current_match + 1) % matches.len();
            } else {
                s.current_match = (s.current_match + matches.len() - 1) % matches.len();
            }
            let line = matches[s.current_match].line;
            self.content_scroll = line;
        }
    }

    fn handle_table_key(&mut self, key: Key) {
        let Some(mut ts) = self.table_mode.take() else { return };
        let (rows, cols) = self
            .last_elements
            .get(ts.element)
            .and_then(|e| match &e.kind {
                ElemKind::Table {
                    section_path,
                    block_idx,
                    ..
                } => self.section_at_path(section_path).and_then(|sec| {
                    sec.blocks.get(*block_idx).map(|b| match b {
                        Block::Table { headers, rows, .. } => (rows.len() + 1, headers.len()),
                        _ => (1, 1),
                    })
                }),
                _ => None,
            })
            .unwrap_or((1, 1));
        match key {
            Key::Esc => {
                self.interactive = Some(ts.element);
            }
            Key::Char('j') | Key::Down => {
                ts.row = (ts.row + 1).min(rows.saturating_sub(1));
                self.table_mode = Some(ts);
            }
            Key::Char('k') | Key::Up => {
                ts.row = ts.row.saturating_sub(1);
                self.table_mode = Some(ts);
            }
            Key::Char('h') | Key::Left => {
                ts.col = ts.col.saturating_sub(1);
                self.table_mode = Some(ts);
            }
            Key::Char('l') | Key::Right => {
                ts.col = (ts.col + 1).min(cols.saturating_sub(1));
                self.table_mode = Some(ts);
            }
            Key::Tab => {
                ts.col += 1;
                if ts.col >= cols {
                    ts.col = 0;
                    ts.row = (ts.row + 1).min(rows.saturating_sub(1));
                }
                self.table_mode = Some(ts);
            }
            Key::Enter => {
                let value = self.table_cell_value(&ts);
                self.edit_cell = Some(EditCellState {
                    element: ts.element,
                    row: ts.row,
                    col: ts.col,
                    value,
                });
            }
            Key::Char('y') => {
                let value = self.table_cell_value(&ts);
                self.table_mode = Some(ts.clone());
                self.copy_text(&value);
                // keep table status after copy attempt message: copy_text set
                // a transient message; restore table mode
                self.table_mode = Some(ts);
            }
            Key::Char('Y') => {
                let row_text = self.table_row_text(&ts);
                self.table_mode = Some(ts.clone());
                self.copy_text(&row_text);
                self.table_mode = Some(ts);
            }
            Key::Char('r') => {
                let md = self.table_markdown(&ts);
                self.table_mode = Some(ts.clone());
                self.copy_text(&md);
                self.table_mode = Some(ts);
            }
            _ => {
                self.table_mode = Some(ts);
            }
        }
    }
    fn table_cell_value(&self, ts: &TableState) -> String {
        if let Some(elem) = self.last_elements.get(ts.element) {
            if let ElemKind::Table {
                section_path,
                block_idx,
                ..
            } = &elem.kind
            {
                if let Some(sec) = self.section_at_path(section_path) {
                    if let Some(Block::Table { headers, rows, .. }) = sec.blocks.get(*block_idx) {
                        if ts.row == 0 {
                            return headers.get(ts.col).cloned().unwrap_or_default();
                        }
                        return rows
                            .get(ts.row - 1)
                            .and_then(|r| r.get(ts.col))
                            .cloned()
                            .unwrap_or_default();
                    }
                }
            }
        }
        String::new()
    }
    fn table_row_text(&self, ts: &TableState) -> String {
        if let Some(elem) = self.last_elements.get(ts.element) {
            if let ElemKind::Table {
                section_path,
                block_idx,
                ..
            } = &elem.kind
            {
                if let Some(sec) = self.section_at_path(section_path) {
                    if let Some(Block::Table { headers, rows, .. }) = sec.blocks.get(*block_idx) {
                        let cells = if ts.row == 0 {
                            headers
                        } else {
                            static EMPTY: Vec<String> = Vec::new();
                            rows.get(ts.row - 1).unwrap_or(&EMPTY)
                        };
                        return cells.join(" | ");
                    }
                }
            }
        }
        String::new()
    }
    fn table_markdown(&self, ts: &TableState) -> String {
        if let Some(elem) = self.last_elements.get(ts.element) {
            if let ElemKind::Table {
                section_path,
                block_idx,
                ..
            } = &elem.kind
            {
                if let Some(sec) = self.section_at_path(section_path) {
                    if let Some(Block::Table { headers, rows, .. }) = sec.blocks.get(*block_idx) {
                        let mut out = format!("| {} |\n", headers.join(" | "));
                        out.push_str(&format!(
                            "|{}|\n",
                            headers
                                .iter()
                                .map(|_| "---|")
                                .collect::<String>()
                                .trim_end_matches('|')
                        ));
                        for row in rows {
                            out.push_str(&format!("| {} |\n", row.join(" | ")));
                        }
                        return out.trim_end().to_string();
                    }
                }
            }
        }
        String::new()
    }

    fn handle_link_key(&mut self, key: Key) {
        let Some(mut lm) = self.link_mode.take() else { return };
        if let Some(mut query) = lm.search.clone() {
            match key {
                Key::Esc => {
                    lm.search = None;
                    lm.filtered = (0..lm.links.len()).collect();
                    lm.selected = 0;
                    self.link_mode = Some(lm);
                }
                Key::Enter => {
                    lm.search = None;
                    let selected = lm
                        .filtered
                        .get(lm.selected)
                        .and_then(|i| lm.links.get(*i))
                        .cloned();
                    if let Some(link) = selected {
                        self.follow_link(&link);
                    } else {
                        self.link_mode = Some(lm);
                    }
                }
                Key::Backspace => {
                    query.pop();
                    lm.filtered = filter_links(&lm.links, &query);
                    lm.selected = 0;
                    lm.search = Some(query);
                    self.link_mode = Some(lm);
                }
                Key::Ctrl('u') => {
                    lm.filtered = (0..lm.links.len()).collect();
                    lm.selected = 0;
                    lm.search = Some(String::new());
                    self.link_mode = Some(lm);
                }
                Key::Char(c) => {
                    query.push(c);
                    lm.filtered = filter_links(&lm.links, &query);
                    lm.selected = 0;
                    lm.search = Some(query);
                    self.link_mode = Some(lm);
                }
                Key::Down | Key::Tab => {
                    if !lm.filtered.is_empty() {
                        lm.selected = (lm.selected + 1) % lm.filtered.len();
                    }
                    lm.search = Some(query);
                    self.link_mode = Some(lm);
                }
                Key::Up => {
                    if !lm.filtered.is_empty() {
                        lm.selected = (lm.selected + lm.filtered.len() - 1) % lm.filtered.len();
                    }
                    lm.search = Some(query);
                    self.link_mode = Some(lm);
                }
                _ => {
                    lm.search = Some(query);
                    self.link_mode = Some(lm);
                }
            }
            return;
        }
        match key {
            Key::Esc => {}
            Key::Tab | Key::Char('j') | Key::Down => {
                if !lm.filtered.is_empty() {
                    lm.selected = (lm.selected + 1) % lm.filtered.len();
                }
                self.link_mode = Some(lm);
            }
            Key::BackTab | Key::Char('k') | Key::Up => {
                if !lm.filtered.is_empty() {
                    lm.selected = (lm.selected + lm.filtered.len() - 1) % lm.filtered.len();
                }
                self.link_mode = Some(lm);
            }
            Key::Char(c) if ('1'..='9').contains(&c) => {
                let n = c as usize - '1' as usize;
                if n < lm.filtered.len() {
                    lm.selected = n;
                }
                self.link_mode = Some(lm);
            }
            Key::Char('/') => {
                lm.search = Some(String::new());
                self.link_mode = Some(lm);
            }
            Key::Char('p') => {
                self.link_mode = Some(lm);
                // move to parent heading and collect its links, staying in link mode
                let cur = self.current_heading();
                if let Some(hidx) = cur {
                    if let Some(path) = self.section_path_for_heading(hidx) {
                        if path.len() > 1 {
                            if let Some(parent) =
                                self.heading_index_for_path(&path[..path.len() - 1])
                            {
                                self.select_heading(parent);
                            }
                        }
                    }
                }
                self.open_link_mode();
            }
            Key::Char('y') => {
                let url = lm
                    .filtered
                    .get(lm.selected)
                    .and_then(|i| lm.links.get(*i))
                    .map(|l| l.url.clone())
                    .unwrap_or_default();
                let keep = lm.clone();
                self.copy_text(&url);
                // a clipboard message replaces the footer but link mode ends
                // in the original after a copy attempt; keep the navigator
                // open if the copy failed so the message can be seen on exit.
                let _ = keep;
            }
            Key::Enter => {
                let selected = lm
                    .filtered
                    .get(lm.selected)
                    .and_then(|i| lm.links.get(*i))
                    .cloned();
                if let Some(link) = selected {
                    self.follow_link(&link);
                }
            }
            Key::Char('b') | Key::Backspace => {
                self.go_back();
            }
            Key::Char('F') => {
                self.go_forward();
            }
            _ => {
                self.link_mode = Some(lm);
            }
        }
    }

    fn handle_interactive_key(&mut self, key: Key, viewport_h: usize) {
        let Some(mut idx) = self.interactive else { return };
        let total = self.last_elements.len();
        match key {
            Key::Esc => {
                self.interactive = None;
                self.message = None;
            }
            Key::Tab | Key::Char('j') | Key::Down => {
                if total > 0 {
                    idx = (idx + 1) % total;
                    self.interactive = Some(idx);
                    self.message = None;
                    self.scroll_to_element(idx, viewport_h);
                }
            }
            Key::BackTab | Key::Char('k') | Key::Up => {
                if total > 0 {
                    idx = (idx + total - 1) % total;
                    self.interactive = Some(idx);
                    self.message = None;
                    self.scroll_to_element(idx, viewport_h);
                }
            }
            Key::Char('d') | Key::PageDown => {
                self.scroll_content(10, viewport_h);
            }
            Key::Char('u') | Key::PageUp => {
                self.scroll_content(-10, viewport_h);
            }
            Key::Char(' ') => {
                self.message = None;
                self.activate_element(idx, true);
            }
            Key::Enter => {
                self.message = None;
                self.activate_element(idx, false);
            }
            Key::Char('y') => {
                self.message = None;
                if let Some(elem) = self.last_elements.get(idx).cloned() {
                    let text = match &elem.kind {
                        ElemKind::Link { url, .. } => url.clone(),
                        ElemKind::Code { content } => content.clone(),
                        ElemKind::Table { .. } => {
                            let ts = TableState {
                                element: idx,
                                row: 0,
                                col: 0,
                            };
                            self.table_markdown(&ts)
                        }
                        ElemKind::Checkbox { .. } => String::new(),
                    };
                    let stay = idx;
                    self.copy_text(&text);
                    if self.interactive.is_none() && self.table_mode.is_none() {
                        self.interactive = Some(stay);
                        // copy message should be visible; keep interactive status hidden
                        // behind the transient for one keypress like the original.
                    }
                }
            }
            _ => {}
        }
    }
    fn scroll_to_element(&mut self, idx: usize, viewport_h: usize) {
        if let Some(elem) = self.last_elements.get(idx) {
            let line = elem.start_line;
            if line < self.content_scroll {
                self.content_scroll = line;
            } else if viewport_h > 0 && line >= self.content_scroll + viewport_h {
                self.content_scroll = line.saturating_sub(viewport_h) + 1;
            }
        }
    }
    fn activate_element(&mut self, idx: usize, via_space: bool) {
        let Some(elem) = self.last_elements.get(idx).cloned() else { return };
        match &elem.kind {
            ElemKind::Link { text, url } => {
                if !via_space {
                    let link = LinkItem {
                        text: text.clone(),
                        url: url.clone(),
                    };
                    self.follow_link(&link);
                }
            }
            ElemKind::Checkbox {
                section_path,
                block_idx,
                item_idx,
                global_idx,
                ..
            } => {
                // toggle in the model
                let mut new_state = false;
                if let Some(sec) = Self::section_at_path_mut(&mut self.doc, section_path) {
                    if let Some(Block::List { items, .. }) = sec.blocks.get_mut(*block_idx) {
                        if let Some(item) = items.get_mut(*item_idx) {
                            new_state = item.checked != Some(true);
                            item.checked = Some(new_state);
                        }
                    }
                }
                // persist to the file right away
                if let Some(path) = self.file_path.clone() {
                    let mut source = self.source.clone();
                    if toggle_checkbox_in_source(&mut source, *global_idx) {
                        match std::fs::write(&path, &source) {
                            Ok(()) => {
                                self.source = source;
                                self.set_message(if new_state {
                                    "✓ Checkbox checked and saved"
                                } else {
                                    "✓ Checkbox unchecked and saved"
                                });
                            }
                            Err(e) => {
                                self.set_message(format!("✗ Failed to save checkbox: {e}"));
                            }
                        }
                    } else {
                        self.set_message("✗ Failed to save checkbox");
                    }
                } else {
                    self.set_message(if new_state {
                        "✓ Checkbox checked"
                    } else {
                        "✓ Checkbox unchecked"
                    });
                }
                // stay in interactive mode at the same element
                self.interactive = Some(idx);
            }
            ElemKind::Code { .. } => {}
            ElemKind::Table { .. } => {
                if !via_space {
                    self.interactive = None;
                    self.table_mode = Some(TableState {
                        element: idx,
                        row: 0,
                        col: 0,
                    });
                }
            }
        }
    }

    fn handle_normal_key(&mut self, key: Key, term: &mut Terminal, viewport_h: usize) {
        // count prefixes for j/k in outline/content
        if let Key::Char(c) = key {
            if c.is_ascii_digit() && !(self.count_prefix.is_empty() && c == '0') {
                if self.count_prefix.len() < 6 {
                    self.count_prefix.push(c);
                    return;
                }
            }
        }
        let count: i64 = if self.count_prefix.is_empty() {
            1
        } else {
            self.count_prefix.parse().unwrap_or(1)
        };
        let mut used_count = false;
        match key {
            Key::Char('q') => {
                self.count_prefix.clear();
                self.quit_requested();
                return;
            }
            Key::Esc => {
                self.count_prefix.clear();
                self.quit_requested();
                return;
            }
            _ => {}
        }
        match self.focus {
            Focus::Outline => match key {
                Key::Char('j') | Key::Down => {
                    used_count = true;
                    self.move_outline(count);
                }
                Key::Char('k') | Key::Up => {
                    used_count = true;
                    self.move_outline(-count);
                }
                Key::Char('g') => {
                    self.selected = 0;
                    self.content_scroll = 0;
                }
                Key::Char('G') | Key::End => {
                    let entries = self.outline_entries();
                    self.last_outline_entries = entries.clone();
                    if !entries.is_empty() {
                        self.selected = entries.len() - 1;
                        self.content_scroll = 0;
                    }
                }
                Key::Char('p') => self.outline_parent(),
                Key::Enter | Key::Char(' ') => {
                    if self
                        .current_heading()
                        .map(|h| self.doc.headings[h].text.as_str())
                        == Some("Select a file")
                        && self.file_path.is_none()
                    {
                        let dir = std::env::current_dir()
                            .unwrap_or_else(|_| PathBuf::from("."));
                        self.open_picker(dir);
                    } else {
                        self.toggle_expand_current();
                    }
                }
                Key::Char('l') | Key::Right => self.expand_current(),
                Key::Char('h') | Key::Left => self.collapse_or_parent(),
                Key::Tab | Key::BackTab => {
                    if self.outline_visible {
                        self.focus = Focus::Content;
                    }
                }
                Key::Char('d') | Key::Char('u') => {
                    // documented but a no-op in outline focus
                }
                _ => self.handle_common_key(key, term, viewport_h),
            },
            Focus::Content => match key {
                Key::Char('j') | Key::Down => {
                    used_count = true;
                    self.scroll_content(count, viewport_h);
                }
                Key::Char('k') | Key::Up => {
                    used_count = true;
                    self.scroll_content(-count, viewport_h);
                }
                Key::Char('d') | Key::PageDown => self.scroll_content(10, viewport_h),
                Key::Char('u') | Key::PageUp => self.scroll_content(-10, viewport_h),
                Key::Char('g') | Key::Home => self.content_scroll = 0,
                Key::Char('G') | Key::End => {
                    let total = self.last_content_lines.len();
                    self.content_scroll = total.saturating_sub(viewport_h.max(1));
                }
                Key::Tab | Key::BackTab => {
                    if self.outline_visible {
                        self.focus = Focus::Outline;
                    }
                }
                Key::Char('y') => {
                    let text = self.current_section_text();
                    self.copy_text(&text);
                }
                _ => self.handle_common_key(key, term, viewport_h),
            },
        }
        if used_count || !self.count_prefix.is_empty() {
            self.count_prefix.clear();
        }
    }

    fn current_section_text(&self) -> String {
        match self.current_heading() {
            Some(hidx) => self.doc.headings[hidx].content.clone(),
            None => self.doc.source.clone(),
        }
    }

    fn handle_common_key(&mut self, key: Key, term: &mut Terminal, viewport_h: usize) {
        match key {
            Key::Char('/') => self.start_search(SearchKind::Content),
            Key::Char('s') => self.start_search(SearchKind::Outline),
            Key::Char('?') => self.help_scroll = Some(0),
            Key::Char(':') => self.open_palette(),
            Key::Char('o') | Key::Ctrl('o') => {
                let dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
                self.open_picker(dir);
            }
            Key::Char('r') => self.toggle_raw(),
            Key::Char('w') => self.toggle_outline(),
            Key::Char('[') => {
                if self.outline_visible {
                    self.cycle_width(false);
                }
            }
            Key::Char(']') => {
                if self.outline_visible {
                    self.cycle_width(true);
                }
            }
            Key::Char('S') => {
                self.confirm = Some(ConfirmKind::SaveWidth);
            }
            Key::Char('t') => self.toggle_todo_filter(),
            Key::Char('m') => {
                if let Some(h) = self.current_heading() {
                    if self.bookmark == Some(h) {
                        self.bookmark = None;
                    } else {
                        self.bookmark = Some(h);
                    }
                }
            }
            Key::Char('\'') => {
                if let Some(h) = self.bookmark {
                    self.select_heading(h);
                }
            }
            Key::Char('f') => self.open_link_mode(),
            Key::Char('i') => {
                if !self.last_elements.is_empty() {
                    self.interactive = Some(0);
                    self.set_message(format!(
                        "✓ Interactive mode: {} elements found (Tab to cycle)",
                        self.last_elements.len()
                    ));
                } else {
                    self.set_message("No interactive elements found");
                }
            }
            Key::Char('b') | Key::Backspace => self.go_back(),
            Key::Char('F') => self.go_forward(),
            Key::Char('n') => {
                if self.search.is_some() {
                    self.jump_search_match(true, viewport_h);
                }
            }
            Key::Char('N') => {
                if self.search.is_some() {
                    self.jump_search_match(false, viewport_h);
                }
            }
            Key::Char('y') => {
                let text = self.current_section_text();
                self.copy_text(&text);
            }
            Key::Char('Y') => {
                let text = match self.current_heading() {
                    Some(hidx) => {
                        let h = &self.doc.headings[hidx];
                        format!("[{}](#{})", h.text, slugify(&h.text))
                    }
                    None => String::new(),
                };
                self.copy_text(&text);
            }
            Key::Char('e') => self.open_editor(term),
            _ => {}
        }
    }

    fn open_editor(&mut self, term: &mut Terminal) {
        let Some(path) = self.file_path.clone() else {
            self.set_message(
                "✗ Editor failed: no editor found: set $VISUAL or $EDITOR, or install a supported editor",
            );
            return;
        };
        let Some(editor) = find_editor(&self.cfg) else {
            self.set_message(
                "✗ Editor failed: no editor found: set $VISUAL or $EDITOR, or install a supported editor",
            );
            return;
        };
        term.suspend();
        let parts: Vec<&str> = editor.split_whitespace().collect();
        let result = if parts.is_empty() {
            Err(())
        } else {
            let mut cmd = std::process::Command::new(parts[0]);
            if parts.len() > 1 {
                cmd.args(&parts[1..]);
            }
            if !self.cfg.editor_args.is_empty() {
                cmd.args(&self.cfg.editor_args);
            }
            cmd.arg(&path);
            match cmd.status() {
                Ok(status) if status.success() => Ok(()),
                _ => Err(()),
            }
        };
        term.resume();
        match result {
            Ok(()) => {
                if let Ok(content) = std::fs::read_to_string(&path) {
                    let cur = self.current_heading();
                    self.source = content.clone();
                    self.doc = Document::parse(&content);
                    self.refresh_outline_selection(cur);
                    self.set_message("✓ File reloaded");
                }
            }
            Err(()) => self.set_message("✗ Editor failed"),
        }
    }
}

fn filter_palette(query: &str) -> Vec<usize> {
    if query.is_empty() {
        return (0..PALETTE_COMMANDS.len()).collect();
    }
    PALETTE_COMMANDS
        .iter()
        .enumerate()
        .filter(|(_, c)| {
            fuzzy_match(query, c.name)
                || c.aliases
                    .split(',')
                    .any(|a| fuzzy_match(query, a.trim()))
        })
        .map(|(i, _)| i)
        .collect()
}
fn filter_links(links: &[LinkItem], query: &str) -> Vec<usize> {
    links
        .iter()
        .enumerate()
        .filter(|(_, l)| fuzzy_match(query, &l.text) || fuzzy_match(query, &l.url))
        .map(|(i, _)| i)
        .collect()
}

// ---------------- run ----------------

pub fn run(doc: Document, content: &str, cfg: Config, opts: TuiOptions) -> Result<(), String> {
    let mut term = Terminal::open().map_err(|e| {
        let _ = e;
        "no tty".to_string()
    })?;
    unsafe {
        libc::signal(libc::SIGWINCH, on_winch as usize);
    }
    let theme_name = canonical_theme(&cfg.theme);
    let images_enabled = opts.images.unwrap_or(cfg.images_enabled);
    let color_mode = opts
        .color_mode
        .clone()
        .unwrap_or_else(|| cfg.color_mode.clone());
    let mut app = App {
        doc,
        source: content.to_string(),
        file_path: opts.file_path.clone(),
        display_name: opts.display_name.clone(),
        theme: theme_by_name(&theme_name),
        theme_name,
        color_mode,
        images_enabled,
        outline_width: if cfg.outline_width == 0 {
            30
        } else {
            cfg.outline_width
        },
        outline_visible: true,
        focus: Focus::Outline,
        collapsed: HashSet::new(),
        selected: 0,
        outline_scroll: 0,
        content_scroll: 0,
        raw_mode: false,
        message: None,
        count_prefix: String::new(),
        bookmark: None,
        todo_filter: false,
        search: None,
        help_scroll: None,
        picker: None,
        palette: None,
        confirm: None,
        link_mode: None,
        interactive: None,
        table_mode: None,
        edit_cell: None,
        pending_edits: Vec::new(),
        undo_stack: Vec::new(),
        history_back: Vec::new(),
        history_forward: Vec::new(),
        should_quit: false,
        last_content_lines: Vec::new(),
        last_elements: Vec::new(),
        last_outline_entries: Vec::new(),
        clipboard_note: None,
        cfg,
    };
    app.last_outline_entries = app.outline_entries();
    if opts.show_picker {
        let dir = opts
            .picker_dir
            .clone()
            .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        app.open_picker(dir);
    }

    term.enter();
    let result = run_loop(&mut app, &mut term);
    term.leave();
    result
}

fn run_loop(app: &mut App, term: &mut Terminal) -> Result<(), String> {
    loop {
        let (w, h) = term.size();
        let search_h = if app.search.is_some() { 3 } else { 0 };
        let main_h = h.saturating_sub(2 + search_h + 2);
        let outline_w = if app.outline_visible {
            (w * app.outline_width as usize / 100).min(w)
        } else {
            0
        };
        let content_w = if app.outline_visible {
            w.saturating_sub(outline_w)
        } else {
            w
        };
        let inner_w = content_w.saturating_sub(2);
        let inner_h = main_h.saturating_sub(2);

        // rebuild outline entries and clamp selection
        let entries = app.outline_entries();
        app.last_outline_entries = entries;
        if app.selected >= app.last_outline_entries.len() {
            app.selected = app.last_outline_entries.len().saturating_sub(1);
        }
        // keep the selected outline row visible
        if inner_h > 0 {
            if app.selected < app.outline_scroll {
                app.outline_scroll = app.selected;
            } else if app.selected >= app.outline_scroll + inner_h {
                app.outline_scroll = app.selected + 1 - inner_h;
            }
        }

        let (lines, elements, _title) = app.build_content(inner_w.max(1));
        app.last_content_lines = lines;
        app.last_elements = elements;
        // clamp content scroll
        let max_scroll = app.last_content_lines.len().saturating_sub(inner_h.max(1));
        if app.content_scroll > max_scroll {
            app.content_scroll = max_scroll;
        }
        // if a search is active and being edited (content), jump to first match
        // (only the scroll *display*; matches are recomputed in draw)

        app.draw(term);

        if app.should_quit {
            break;
        }
        let Some(key) = term.read_key() else {
            continue;
        };
        if key == Key::Unknown {
            continue;
        }
        app.handle_key(key, term, inner_h);
    }
    Ok(())
}
