                blocks.push(Block::Image {
                    alt: String::new(),
                    src: doc_url.clone(),
                    title: None,
                });
            }
            _ => {}
        }
        i += 1;
    }
    let content = heading_title_from_events(&events);
    blocks.push(Block::Heading {
        level: h.level,
        anchor: slugify(&content),
        content,
        inline,
    });
    blocks
}

